/* 平成22年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h22.committeeSessions.push(...[{"id":"h22-20100720-8","meetingId":"h22-cm07","date":"2010年7月20日","dateIso":"2010-07-20","committee":"建設委員会","time":"午後１時０３分～午後３時１１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","topics":[{"id":"topic-01","title":"平成２２年８月都営住宅入居者募集","agenda":"平成２２年８月都営住宅入居者募集","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"入るときの収入の資格が決まっていると思うんですけれども、やっぱり入った後、収入が大分上がった方も数多く、数多くはいないか、いらっしゃると思うんですけれども、その辺で収入が高くなって、範囲に合わなくなった方に対して出ていただく措置をしているのかとか、都営なので詳しくはわからないと思うんですけど、大ざっぱでいいんですけど、大まかな流れというか、実績がわかれば教えていただきたい。","respondent":"柏原住宅担当課長","answer":"件数等につきましてはちょっとわからないんですけれども、区営住宅も同様にやっておりますので、都営住宅も同じ法律でやっておりますので、同じようにやっているはずというふうに考えております。","id":"exchange-001"},{"speaker":"藤原委員","kind":"確認","question":"都営だから、その辺というのは確実にどうなっているかというのはわからないというのはわかるんですけれども、最後にはいわゆる家賃を払わない方みたいに裁判をしてまで出させるぐらいの措置をしているのか。都営のあれだから、聞けないけど、その辺はがっちり、みっちり、やっていっているのかということだけは確認の意味で教えてください。","respondent":"柏原住宅担当課長","answer":"区営のほうも幸い高額所得者の方はいらっしゃらないんですけれども、そういった方たちが出てきた場合には退去していただくということで進めていくということで考えております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"細かいことで申しわけないんですが、シルバーピア住宅というもの、いわゆる高齢者住宅なども区ではあると思うんですが、シルバーピア住宅というのは何なのかご説明いただきたいのと、今回ポイント方式ということなんですけど、年に４回大きく都営住宅の募集がありまして、ポイントもしくは普通の方式を交互に行っているように認識するんですが、その理由を教えてください。","respondent":"柏原住宅担当課長","answer":"シルバーピア住宅と申しますのは、高齢者の方を対象としました集合住宅でございまして、高齢者用としまして、手すりであるとか、それから緊急通報の装置、それから高齢者に配慮した形の設備が設けられている住宅ということでございまして、そのほか、入居者の安否確認であるとか。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"ですから、肝心な一番入居してほしい低所得者の方に毎年４回こういう募集をやっているんだという情報が届かないんじゃないかなというふうに考えるんですが、そこら辺はどうお考えなんでしょうか。","respondent":"柏原住宅担当課長","answer":"多くの方に知っていただくということで、こちらのほう、広報とかされておりますけれども、特に広報紙のほうは広報の担当に聞いたところ、かなり読んでいる方が多いということを聞いておりますし、お問い合わせのほうも。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"問い合わせが多いというのは、やっぱりそれだけ住宅を望んでいる方が多いということだと思うんですけど、まだまだ周りにそういう住宅があれば応募したいんだという方は、それ以上にいらっしゃると思いますので、広報のほうもやっぱり情報弱者の方に届かないということではよくないと思いますので、ちょっと所管も違うと思うんですが、そういう必要な方々に情報を届けるという目的を達成する意味で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"の平成２２年度地区総合防災訓練・職員防災訓練","agenda":"の平成２２年度地区総合防災訓練・職員防災訓練","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"参加者の人数が昨年は１万４,０００人ということなんですが、経年的に言いますと、参加者の方は増えてきているのか。昨年もちょっと参加したんですが、基本的には町会の単位で訓練されているというふうに思うんでけれども、例えば町会以外の参加者の方々というんですかね、そういうような方々というのは、参加しているのはどういう人が参加しているのかお伺いします。","respondent":"佐藤防災安全担当課長","answer":"そのほか、昨年度も各大使館に声をかけて、外国人が参加するということも、今年度も同様に実施する予定です。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"参加者が増えてきているということなんですけれども、これからも頑張っていただきたいんですが、これからも参加者を増やしていくためにどんな工夫をしていくお考えがあるのかというのをお伺いします。","respondent":"佐藤防災安全担当課長","answer":"参加者を増加するための工夫についてなんですが、過去からいろいろ町会長を中心に周知等しているところですが、年々増加しているということを先ほど述べさせていただきましたが、これ以上増加。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後にしますけど、これ以上のなかなか増加というのは難しい面もあるんだというお話があったんですが、それは会場のキャパシティ問題なのか、それともそれ以外の、例えばちょっと今の、そこら辺、何で難しい面があると思っていらっしゃるのかというのをちょっともう少し聞かせていただきたいのが１点と、あと自衛隊のヘリコプター離発着訓練というのは、いつぐらいから実施されているのか。","respondent":"佐藤防災安全担当課長","answer":"自衛隊のヘリコプター離発着訓練につきましては、昨年度から天王洲野球場で実施している訓練です。","id":"exchange-008"},{"speaker":"阿部副委員長","kind":"質問","question":"今のご答弁でいろいろ工夫をされて実施されているということがわかったんですけれども、ちょっと１点気になっているんですが、防災訓練という設定が、何か戸建ての住宅地域での防災訓練というのが何となく念頭にあるように感じています。ですから、今のは今のでいいんですけれども、何かそういった視点を加えた工夫というのも今後あればいいなと思うんですが、いかがでしょうか。","respondent":"中山防災課長","answer":"それも３日間ではなくて、もうちょっと長い期間。それから、食料、備蓄倉庫をどうするか、これを今後３８棟の管理組合に私どもが働きかけまして、超高層マンションに住まわれている方の避難訓練等をこれから話し合っていく、ちょうどそういう話が出てきているところです。","id":"exchange-009"},{"speaker":"阿部副委員長","kind":"意見","question":"まさに取り組んでいらっしゃるということで、ただ、超高層には超高層の課題もあると思うんですけど、例えば超高層でなくても、５階、１０階ぐらいであっても、やっぱり戸建てとは違う逃げ方みたいなものがあると思うんですね。超高層に完全に絞り切らないで、ある程度集合住宅ということで広く使えるような何か方策というのも考えていただければいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]},{"id":"topic-03","title":"の戸越幹線貯留管中流部整備工事における今後の対策","agenda":"の戸越幹線貯留管中流部整備工事における今後の対策","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"あわせまして、地元説明会の開催予定が出されていますが、町会の掲示板、回覧板などは出したと思うんですが、ポスティングは現場から半径何メートルとか、そういう決まりとかはあるのかお伺いします。","respondent":"藤橋都市整備下水道課長","answer":"地元説明会につきましては、今回は７月２日の事故調査検討委員会第３回の会合が行われた以降、直ちに地域の方々へ地域センターを通じて説明会の案内の回覧をしておりまして、ポスティングは今回行っておりません。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"説明会、現場、ちょっと特に今工事が何でとまっているのかということが一切看板に書いていないように見受けられるんですけど、何か町会とかそういう団体を通してというのももちろん大事なのでそれはいいんですけど、それプラスやっぱり近隣のところには改めてポスティングをしたほうがいいと思うんですけど、その範囲とかはいろいろ課もおありと思うんですが、ぜひやっていただきたいと思うんですが。","respondent":"藤橋都市整備下水道課長","answer":"ただ、今回中止した経緯がありますので、改めて２回に分けて説明会を開催するという形をとりましたので、十分地域の方々への案内をさせていただいたというふうに考えております。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望です。費用の問題で言うと、工法で新たに区から２.８億円というのは、事業負担という点ではどのようになるのか、お金の出どころはどこになるのかお伺いしたい。","respondent":"藤橋都市整備下水道課長","answer":"報告書の２７ページ、２８ページの一覧表で示していますお金につきましては、この対策費用に必要なお金でございまして、今回、前回の工事といたしまして、その分工事期間が延びること等がございまして、この対策工法以外に現場で発生する経費が多々あります。","id":"exchange-013"},{"speaker":"阿部副委員長","kind":"確認","question":"すみません、ちょっと確認をさせてください。原因の究明をこれ以上行わずに工事を優先する。そうすると、今のご答弁だと、特に業者側には落ち度がなくて、都なりがこのエキストラの費用については負担をするのだというところで決着したということでよろしいんですか。","respondent":"藤橋都市整備下水道課長","answer":"したがいまして、事故調査検討委員会での調査検討を行ってきた中で、施工業者は事故原因の調査や対策方法の選定、そして施工に関して積極的に協力するという立場をとってきてあります。","id":"exchange-014"},{"speaker":"阿部副委員長","kind":"確認","question":"何か大人の解決という感じがします。すみません、もう一つだけ確認させてください。これは最大径であったということなんですけれども、この大きさではふだんは別の工法をとっているということなんですか。最大径１２ｍあったら、普通はアーバンリング工法ではなくて、別のをやっているけど、今回は大きいけど、これをとったということですか。","respondent":"藤橋都市整備下水道課長","answer":"ただ、ここの現場の条件として、いわゆる限られた場所での施工で、なおかつ浸水対策ということで、短期間にできる工法としていろいろ比較した中で、この方法が採用されたということで、この工法が１０ｍ、１２ｍまでできないというわけではなくて、様々な施工方法の中で。","id":"exchange-015"},{"speaker":"松澤委員","kind":"質問","question":"今までの話でよくわかりましたけれども、説明会なんですけども、２３日と２６日に２回やりますよね。これは基本的には２３日に来れなかった人のためにもう一度やって、周知徹底して、たくさんの人に説明会を聞いてもらうという趣旨なんですよね。やっぱり一番大変なのは三ツ木公園のそばなわけですから、２３日、２６日に開くというのはよくわかりますよ、丁寧に。何で三ツ木会館で２回ともやらないんですか。","respondent":"藤橋都市整備下水道課長","answer":"したがって、２３日の三ツ木公園だけで、これだけで終わりというわけではございませんで、この中でもいろいろまたご質問、あるいはご要望等もあるかと思いますので、これに限らず逐次説明会なり、あるいは現場の途中の段階でも、昨年度実施しましたように。","id":"exchange-016"},{"speaker":"阿部副委員長","kind":"質問","question":"すみません、ちょっと１点だけ言い忘れていました。この対策方法の選定表みたいなものを、住民説明会で出されるんでしょうか。","respondent":"藤橋都市整備下水道課長","answer":"地元説明会におきましては、やはりわかりやすく説明しなければなりませんので、これらについては、この資料を使うという形ではなくて、前回の、先の委員会でも出したような資料で、パワーポイント等でわかりやすく整理した資料をお示しする予定です。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"自転車の駐輪場のほうですけれども、指定管理業務の概要というところで、設備機器の維持・修繕・入替とありますが、この費用というのは、修繕費用とかというのと委託費との関係というんですかね、委託費から出すものなのか、ちょっとそこら辺がわからないので教えていただきたいのと、管理運営委託料と使用料収入との関係、先ほど何かなかなか３年になっても黒字にならないと書いてありましたけれども。","respondent":"藤木交通安全担当課長","answer":"きめ細やかな料金の設定ですけれども、アンケート利用者の方々の場合、こういったいろいろな要望が私どもに来る中で、一定時間無料とかにはできないのかとか、そういうご要望なども来ております。その辺の検討はしていく必要があります。そういうことです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"設備投資は区がして、それがちょっと故障したという場合は、修繕は指定管理会社がやるのかということ、そういうことでいいのかということをお伺いします。委託料が２億円少しで、使用料収入は一たん区に入ると思うんですが、これは２億円に届いていないので、差額として赤字ということをおっしゃっているかと思うんですけど、そういうことですか。すみません、感想です。","respondent":"藤木交通安全担当課長","answer":"アンケートにつきましては、過去いろいろこういう利用者の声を聞きたいということで、区のほうとか指定管理者のほうの事業計画などにも当ててもらっているんですけど、内容につきましては、利用の目的は何ですかとか、あとあなたは駐輪場まで大体何分ぐらいかかりますかとか。","id":"exchange-019"},{"speaker":"安藤委員","kind":"提案","question":"今のアンケートにかかわるかもしれないんですけど、それはどっちかというと区のほうでそういうことをやってほしいというのでやってもらっているということなんでしょうか。ちょっと一番下のところでいろんな提案を促したいということなんですけど、今後、なかなかそういう提案が向こうから出てこないというのは何か原因があるんですか。そこら辺はちょっと教えてください。","respondent":"藤木交通安全担当課長","answer":"提案につきましては全くないということではございませんで、平成２１年度中は目立った提案が出されなかったということで、例えば昨年途中に増設した大森駅の水神口区営自転車等駐車場は、キャパシティがいっぱいで増設できないかとか、そういうような提案するのは。","id":"exchange-020"},{"speaker":"安藤委員","kind":"提案","question":"ちょっと昨年の半ばに出されたという五反田の話とかというのは、それはそれで立派な提案というか、大事な現場からの提案だと思うので、それはこたえていく必要があると思うんですが、その点に関しては、区としてはどのように対応したということなんでしょうか。","respondent":"藤木交通安全担当課長、岩田都市環境事業部長","answer":"大森駅の水神口につきましては、昨年の９月に増設させていただきまして、あともう一件の五反田の関係ですけど、現在そういう適した場所であるかということを前提にいろいろ、もろもろの問題を現在検討して。これは大赤字の事業であります。一方の撤去・保管のほうは、公権力の行使を伴う事業ですので、指定管理業務にはできないということで、区の直轄事業としてやっているわけです。","id":"exchange-021"},{"speaker":"藤原委員","kind":"確認","question":"一つ確認をしたいんですが、課長の答弁でアンケートで特定の時間帯だけでも無料にできないかというのがあって、それを検討しますと言いましたが、今まで品川区において利用者負担ということで有料だ無料だということをずっとやってきたわけですよね。確認なんですけど、また無料に対しての検討というのを区として始めちゃうんですか。","respondent":"藤木交通安全担当課長、岩田都市環境事業部長","answer":"時間限定で商業施設のように無料とすることで、また無秩序な自転車の利用が増加をしまして、放置自転車が駐輪場の周辺にあふれてしまうと、せっかく有料。いわゆる初期の段階で１時間無料、１時間後に有料に変わるというのは最近は増えてまいっております。","id":"exchange-022"},{"speaker":"松澤委員","kind":"質問・要望","question":"住宅についてお伺いしたいんですけど、ファミーユ西五反田西館・東館が東急コミュニティー、そのほかが品川宅建管理センターということですが、この管理委託料がそれぞれ予算で幾らになっているのか。それと、家賃はどれぐらいあったのか、その管理委託料というのは、家賃の何パーセントぐらいになるのかという数字を教えていただきたい。","respondent":"柏原住宅担当課長","answer":"使用料につきまして、委託料はどのくらいかといいますと、家賃がそれぞれの住宅によってあれですけど、単純にこれで割返すというふうにいたしますと、家賃のほうが圧倒的に多いものですから、区民住宅のほうですけれども、単純に割りますと、大体２５％ぐらいなんですけれども。","id":"exchange-023"},{"speaker":"松澤委員","kind":"質問","question":"普通、一般の場合は、例えば家賃で貸していて、不動産屋がある。うちが管理しますよ、家賃集めるのは大変でしょうなんていって。やっぱりそれは例えば５％から３％、地価関係がある。そのパーセンテージで聞いたんですが、そんなに高いんですか。間違いじゃないんですか。","respondent":"柏原住宅担当課長、片田防災まちづくり事業部長","answer":"使用料に対しての委託料ということで、単純な計算ですけれども、大体２０％を切るぐらいかというところで、使用料というのは、国の法律等と計算式とか。ただ、逆に公益的な形での区民住宅ですので、やはり利用者の収入とか、収入分位によって金額が違ってくるわけですから。委託料の中に徴収業務とか管理業務のほかに、いわゆる工事ですね、小破修繕であるとか、大規模的な修繕であるとか。","id":"exchange-024"},{"speaker":"松澤委員","kind":"質問","question":"これはやっぱり指定管理者の場合も入札でやるわけですから、業者がかわった。何を言いたいかというと、私は前にも質問したけれども、これだけの率があるんだったら、議会の中でも何回か滞納で裁判しているなんて言っていますけど、こんなものは指定管理者に保証してもらうような制度にすべきなんですよ。あのね、いいですか。本来利益なんか出しちゃいけないものなんですから。","respondent":"岩田都市環境事業部長、柏原住宅担当課長","answer":"それと、よくこういう区民住宅はもうかるというふうに言われるんですが、実はこれは公会計ですから、減価償却というのを全く考えていません。例えば宅建管理センターですが、住宅援助が２億円ちょっと。肝心なのは入居者管理ですけれども、こちらにかかっている費用が区営住宅・区民住宅入居者管理、いわゆる入居者管理ですね。こちらにかかっている費用は４,３００万円です。","id":"exchange-025"},{"speaker":"松澤委員","kind":"質問","question":"今４％から５％だろうと思いますけれども、そうしますと、先ほど私が言った家賃保証の問題、当然含めていいんじゃないかと思うんですよ。民間ならそれぐらいでやりますよ。やらせてくださいとみんな言います。今の時代ですから。当然こんなの、家賃補助を入れてやってもらえば手がかからないし、裁判して議会に何だかんだ報告するとなったら、どうです、その辺、考えたことないんですか。","respondent":"冨久増用地担当課長","answer":"委員がただいまご発言のお話というのは、おそらく民間で言えばサブリース契約あたりを想定しているのかなというふうに考えられるんですが、基本的に公営住宅法はサブリース契約等については一切想定しておりませんので、基本的な債権債務については。","id":"exchange-026"},{"speaker":"松澤委員","kind":"意見","question":"わかりました。ただし、かなり難しいというのと、できないのとは違うんですよ。今答弁でかなり難しいと言ったけど、かなり難しいというのは、我々の解釈ではできる。ただ大変だということなんです。その辺をしっかり考えていただいて、今度は本会議でやります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"ですので、部長答弁にもありましたけれども、それはだれかが負担してくれなきゃやらないというのではなくて、放置自転車が減れば撤去費用だって減るわけですから、トータルに放置自転車対策の一つとして検討する価値が私はあるのではないかと思いますし、昨年度同じような質問を建設委員会でしたときには、当時の担当課長がそういったやり方について。","respondent":"藤木交通安全担当課長、岩田都市環境事業部長","answer":"２点目の無料の関係の対策ですけど、この辺は、先ほど部長からも説明しましたとおり、原則として通勤通学の方を対象に我々の自転車駐輪場の解消対策をやっているわけです。それを区がすべて税でもって対応すべきなのかというのは、これはいわゆる意見が分かれるところですので、民間経営が成り立つように駅前駐輪場というのはなりましたので、そろそろ民間で成り立つ事業については。","id":"exchange-028"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"そうすると、今から途中で契約を変えるわけにはいかないんでしょうけれども、当然更新もあるわけですし、少しやり方を考えるべきであるかと思います。実際には、ちょっと置いて、何か銀行かなんかに行ってすぐ帰ってきてというような使い方は実際にしているわけですからね。そうでないと、やっぱり放置自転車を置くなと区民に対して言えないですから、五反田については、今あの状況では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"渡部委員","kind":"質問","question":"自転車の総括シートの見方を教えてください。パーセンテージででてきているんですけど、何をもって分母と分子になっているのか教えてください。見方がわからない。","respondent":"藤木交通安全担当課長","answer":"例えば定期ですとそのラックについては、そのお一人の方しか使いませんので、最大１００％までしか当然行きません。当日利用ですと、例えば一つのラックに対して、お二人の方が利用したとなると、それは２００％になります。その辺の年間を通じてならした数字がこちらです。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問","question":"定期のほうの１００％はわかります。それを２００とみなしているのか、３００とみなしているのかという分母の基準を教えてもらわないと、この数字の見方がちょっとわからないなと思ったので、２回転とみなしているのか、３回転とみなしているのかという基準が、１ラックに対してあるのかどうかということなんです。","respondent":"藤木交通安全担当課長","answer":"１ラックに対して１日１台、１件ということになります。","id":"exchange-031"},{"speaker":"渡部委員","kind":"確認","question":"じゃあ確認だけします。今回１２０何％というのがあったので、そういうことだろうというのは見てとれるんですけれども、実際区としてこういう数字を扱うときに、じゃあこれはそういうケースがあるにせよ、当日利用に関しても１ラック１回利用と考えるからバイクの利用率が１２０％に、当日利用になっているんだよということで、１００個あるところに１２０台入っているという計算ですよね、イメージとして。","respondent":"藤木交通安全担当課長","answer":"そうです。","id":"exchange-032"},{"speaker":"若林委員","kind":"質問","question":"自転車のほうなんですが、今後利用料制度も考えられるかどうか、考えるなんていうことはできないんでしょうか。そういうのもあるんでしょうねということで、赤字黒字という話ばっかりなんですね。いつもこの形態が赤だ黒だと、要するに黒にしたほうがいいのかどうかという議論が全然されていないので、もし黒字赤字とこだわるのであれば、利用料制も考えてしたほうがいいんではないか。わかりました。","respondent":"岩田都市環境事業部長、柏原住宅担当課長","answer":"したがって、早急に行わなければいけないのは、ばらばらのところは料金を下げるというのは当然のことで、満杯のところは料金を上げられるかということも含めて、これは早急に検討して議会にも提案していく必要があると考えております。表の出し方につきましては、ちょっと一定の区全体のフォーマットでやっておりますので、関連課と調整させていただきたいと考えています。","id":"exchange-033"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと今回選挙の関係で、日程が大分ずれちゃったということが大きいんだと思うんですけど、ちょっと今回初めて具体的に視察先を出していただいたわけですが、ちょっと景観の問題では確かに景観条例のこともあって、視察を深めていくことは大事だと思うんですが、お城ということになると、ちょっと品川の観光の問題でも観光資源が何か大きいのがあるかなと思うと、そうでもないですし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"阿部副委員長","kind":"質問","question":"これだけ見ると、それは大変シンプルなといいますか、ごもっともなご感想だと思います。この日程、東北地方の各自治体は既に議会が始まっているところ、それからもうすぐ始まるところがありまして、今回日程の調整に大変労力を要しました。同じルートを行ったり来たりします。ですから、これでだめなら行かない。二者択一ぐらいの、そういった状況であるということもあわせてご理解をいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"若林委員","kind":"質問","question":"この景観まちづくりのかぎ括弧の中は、何か公式に出るんでしょうか。表に出るのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"阿部副委員長","kind":"意見","question":"これはそれぞれの都市がこのテーマで一つの事業を進めているという面が大きいです。私たちが盛岡でぜひお城を見ようということではなくて、このまちはお城を中心とした景観まちづくりをしている。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"若林委員","kind":"意見","question":"区民にどういうふうに出るのか。委員会報告とか、ホームページ等々。","respondent":"原委員長","answer":"基本的にはないと。ないというのは、具体化として、今丸印がついているところは出していこうという考えで、正副では考えております。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"今委員長から説明いただいたんですが、３番目の秋田市のほうの市街地再開発というところですけれども、これもこちらの選定から見るというか、何を視察に行くのかというのを説明していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと説明を聞くと、副委員長のほうがこれでだめだったら行かなくてもいいんじゃないかということもありましたけれども、ベストではないんだけども、今回選択肢がほとんどなくて、ここしかなかったんですということだったんですけれども、あとは行きようがないので、やめるという選択肢しかないんだという話だったんですが。","respondent":"原委員長","answer":"前回のお話の流れとして進めてきたのは、行くという方針を前提のもとに正副で案をまとめさせていただきました。それで、都合２泊３日という話し合い、この委員会の中での話し合いをとりまして、そこで反対論が特に出ませんでしたので、一応例年どおりに３カ所決定をしたと。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとやっぱり議論の日数が足りなかったというのが今回かなり厳しい状況にあったと思います。最初の意見に戻るんですが、そういったことが難しいというのであれば、要するに次回視察を検討していく上で、この委員会運営にぜひ改善をしていっていただきたいなという私の意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"渡部委員","kind":"質問","question":"僕自身も実は候補地が難航しているんだという話を伺ったときに、ではこういうところに行ってみたいな、ああいうところに行ってみたいなというのを実は正副には発言させてもらいました。例えば京都までしかないし、だから、そんなことを言い出したらきりがないので、実際に盛岡市がそのようなことをやっているんであれば、僕は堂々と出して、堂々と行くべきだと思う。正副、お疲れさまでした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118011?Template=document&Id=3984#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":38093,"voices":118}},{"id":"h22-20100720-9","meetingId":"h22-cm07","date":"2010年7月20日","dateIso":"2010-07-20","committee":"文教委員会","time":"午後１時０２分～午後３時１２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"の平成２２年度「通学区域の弾力化」に関するアンケート調査結果","agenda":"の平成２２年度「通学区域の弾力化」に関するアンケート調査結果","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"評価についてなんですけれども、さっき、地元を選ぶ傾向が増えているということと、学校の教育活動とか、地域のつながりとか、小中一貫教育のその辺が選ばれている理由になってきているというのと、学校により差があるので各学校で今後この中身を生かしていくという最後のところにご説明があったんですけれども、今回は３年分の比較なので、選択制が始まって１０年、１１年、その間の変化とか。","respondent":"富田学務課長","answer":"分離型の連携校だから選んだという方々もいらっしゃるわけですけれども、これは小学校についてはかなり少数でございまして、全体の数も低いですし、少ない状況でありますけれども、中学校につきましては、一体型の一貫校ほどは多くないですけれども。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"出たり入ったりのところも、よその地域から来たり、転出したりとかいろいろ、そういった面で、すごく平均的に出してしまうと、毎年そんなに変わらないけれども、学校別に見たら、かなり学校によって特色が出てくるのではないかなと思うんですけれども、その辺において、各校ごとのパーセンテージは、私たちが知るすべがあるのかどうか、そこも知りたいなと思っているんですが、そこが１つと、あと。","respondent":"富田学務課長","answer":"学校長にきちんとこの数字を理解してほしい、今後の学校経営に役立ててほしいということを目的として学校にお知らせをしているものですので、ちょっとこちらでの報告というのは控えします。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"いろいろな努力で選択というところで特色というところで選ばれていらっしゃると思うんですが、最後のところで、増えているところ、減っているところという、その二極化現象というのはどうとらえていらっしゃるのか１つ伺いたいのと、あと、今回は保護者の方々に対するアンケートなんですけれども、この通学区域の弾力化について。","respondent":"富田学務課長","answer":"二極化というようにおっしゃいましたけれども、毎年毎年保護者の方々それぞれのお考えで選ばれており、それは似たような結果になる学校もあれば、さまざまな選択をされてくるということもあり、固定化されているというようには全く考えておりません。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"保護者の皆さんに向けてのアンケートは、これ以外にほかにどういうものがあるのかということを教えてください。","respondent":"和氣小中一貫教育担当課長","answer":"これ以外に、毎年３月にすべての保護者、１年生から９年生までの保護者すべての３分の１を対象にしたアンケートをとってあります。これはまたまとまり次第、検証を順番に出します。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"表の中に、小学校の保護者への質問のところで順位が書いてあるんですが、この順位が、例えば、平成２１年度だと、１番から１９番となっているんです。途中抜けている数字がないですか。なので、それはどこへ行ってしまったんですかねところが１つ。地域の学校に行くようになってきたというのは、それは当然の話であって、私は最終的には学区域の学校に自然と行くべきだと思うんですよ。","respondent":"富田学務課長、和氣小中一貫教育担当課長","answer":"４番目ですけれども、「学校が力を入れている教育活動を考えて」と今年度なっておりますが、昨年度までは、「学校の特色ある教育活動を考えて」ということで、習熟度ですとか、小中連携、英語、教科担任等々ということで。実際の教育活動を知っていただくという意味で、今、さまざまな取り組みをしていこうということで、研究をし、具体化を進めているところですので、今年度かけてしっかりまた周知をしてまいりたいというように考えてあります。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"わかりました。２番目の質問は、学校選択の意味です。当然ながらどこの学校もそれなりに頑張るわけだから、それをたくさん知っていただいて、それで、選んでいるんだけれども、やっぱり地域の学校というべきだと思っているので、その辺の動きがどういうふうになっているんですかということをお聞きしています。先ほどの質問だけ、関連質問して、よろしくお願いいたします。","respondent":"富田学務課長","answer":"そこで自分の不足、ここの部分をもっとこうすればいいとか、ここに力を入れていきたいとか、そういったところを振り返り、新しいそういった課題を考えていく大きな参考になるのではないかなと、このアンケートについては思い、毎年実施をしているところです。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"なので、それがかなりの年数がたっている部分があるものですから、その方向性、弾力化の目的に対して、どういう形で、このアンケートではわからないよと言われればそれまでかもしれませんし、でも、弾力化という検証する１つの方法の手段をとっているのがアンケートだと思いますから、それに対してどういうふうな方式のものをやっているんですか。","respondent":"若月教育長","answer":"今度は１つ１つの学校の努力の様子が具体的にどう上がってきているのかということでありますが、ここは大変難しいところでありまして、なぜ難しいか。なぜ私たちがそこがなかなか分析しにくいかと言いますと、学校というのは、毎年、人が入れかわるわけであります。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"このアンケートで、多分、この集計の仕方なんですけれども、上のほうに従来の指定校に入学した方と、指定校以外を選択したという人たちの、その人たちにとって２がどうであったかという評価の仕方が必要で、私たちはこれを見て、何をここで知らせようとしているのかということがよく見えないんですけれども、こういうアンケートの結果では、その中で指定校を選んだ方たちが学校の近さとか。","respondent":"富田学務課長","answer":"これはクロス集計をしたものではないので、それぞれの単純集計、大きく分けたごとの単純集計ですけれども、かなり特定される形での自由意見等もありますので、そういったものを含めて、それは学校にこういった意見があるということは伝える仕組みがあるところです。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"やっぱりここのところで、文教委員会としてその小中一貫教育がどうなのかとか、そういう弾力化に向けていろいろな課題があるというところを浮き彫りにして、それを区が求めていくような方向に進めていくという意味では、やはりクロス集計をして、正確な調査報告というものをした上で住民合意を図っていくのがよいのだというふうに思うんですけれども、そこは今後。","respondent":"富田学務課長","answer":"学校に何かあるのかどうなのかといったことも含めて、さまざまな理由については学校ごとに把握をするということでやっているところであり、これについて、例えば全体の数の中で１,４０５人が従来の指定校に行ったことで。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"しっかりしたデータをクロス集計をして出していただいて、みんなが議論していく素地をつくっていくということで、これは要望させていただきたいというふうに思いますので、ぜひ検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"金野委員","kind":"質問","question":"先ほどのほかの委員ともちょっと関連するんですが、今回新たに５項目、選択項目が見直されて、内容を少し変えたということで、２つほど委員の質問の中でご説明があったのが、４番と５番、「学校が力を入れている教育活動を考えて」と、「地元、地域とのつながりがある」という、この２点は説明をいただいたんですが、１２番の「校長にリーダーシップがある」、あるいは「児童の態度が良い」。","respondent":"富田学務課長","answer":"これは本当にその学校長によりかなりの幅があるわけでございまして、こういった学校の努力の部分での評価というものも選択肢として新たに入れていったことは、学校に返すに当たっては非常に参考になったのではないかと考えております。","id":"exchange-011"},{"speaker":"金野委員","kind":"質問・要望","question":"特にこれはあまり比較にならないと言えば比較にならないのかもしれない、それはあくまでも選択ですからあれなんですが、やはり国公立・私立を選ぶお子さんのご家庭の中のこの数字を見ると、「教職員に熱意がある」とか、「生徒の態度が良い」というのは、やっぱり上位を占めているというところは、やっぱりそれだけかかわっているということもあるのでしょうし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"なので、この設問はどういう意図があって保護者たちがここに印をつけるのだろうと、すごく不思議に思っているんですね。リーダーシップがあるからという、リーダーシップはどうやって判断するんだろうなと、すごく不思議な設問だなと思っているんですけれども、これは何か理由があるんですか。簡単にリーダーシップと書いてある人が多いからということなんですか。","respondent":"富田学務課長、市川教育次長","answer":"全体として先生たちがみんなあいさつをしてくれたとか、あるいはしてくれなかったとか、校長先生の説明が本当によかったとか。ただ、概して校長の個人的な評価というよりは、学校の教育活動、学校の組織、そうしたことについて校長の存在というのがどのように保護者の皆さんにかぶっているというんですか。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"そこはちゃんと分析してあげないと、何か個人個人を攻めるような状況になってしまうような気がするので、そこら辺をもうちょっと細かく、要は、個人を特定しているようなものに関しては、もうちょっと細かく分析結果をしてあげないと、せっかく一生懸命やっている先生が逆な方向にとられてしまったり、やる気がなくなってしまったりするといけないかなと思っているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"伊藤副委員長","kind":"質問","question":"簡単に聞きますけれども、このアンケートの設問ですけれども、お子さんはどちらの小学校、それから中学校へ入学しましたかと書いていますけれども、気になったのは、小中一貫校が何でないのかなという単純な疑問が１つ。それから、公立中学校の設問の中の２０番、「男子校または女子校だから」、これは公立のほうは要らないんじゃないでしょうか。その２つを質問させていただければと思います。","respondent":"富田学務課長","answer":"２点目ですが、これは同じアンケート用紙を配っておりまして、無記名で回答をいただいておりますので、公立のお子さんだけこの用紙とかということで選別することができませんので、申しわけありません。設問自体を入れることがどうかということについては検討したいと思います。","id":"exchange-015"},{"speaker":"伊藤副委員長","kind":"確認","question":"確認なんですけれども、小中一貫校、例えば伊藤学園とか日野学園とかありますよね。それは何で入っていないんですかということを単純に聞いただけなんですけれども、検討するんですか。済みません、質問の仕方がわかりにくかったですかね。小学校、中学校、公立の分もありましたよね。厳密に言えばですよ。","respondent":"富田学務課長","answer":"これは正式には小学校という位置づけを小中一貫校の小学校の部分についてもしておりますので、このような表現をしておりますが、回答しにくいというようなことも考えられますので、これについては検討したいと思います。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"だから、意見としては、従来の指定校というのが、小中一貫校であっても、そこが指定校という人はいるわけで、そこを選択したかしないかとかという話だと思いますので、小中一貫校を選択しましたかという特別な設問になっては、ちょっと違うのではないでしょうかということを意見としてだけお伝えしておきたいと思います。","respondent":"富田学務課長","answer":"わかりにくい答弁で申しわけございません。私が申し上げましたのは、どちらの小学校に入学しましたかのところに、小学校（小中一貫校）ということでの表記に変えることは検討できるかなと考えています。","id":"exchange-017"}]},{"id":"topic-02","title":"の児童扶養手当制度改正","agenda":"の児童扶養手当制度改正","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"間違っていたら済みませんということなんですが、この児童扶養手当は、前に離婚して生活が激変するというか、大変な世帯のことを考慮してできたみたいな話をちょっと聞いたことがあるんですが、一部支給停止、５年間たったらなくなる、新たに申請をして通らないと継続できないという話を聞いたんですが、その制度がどうなっているのかと、父子家庭も全く同じかどうかということを教えてください。","respondent":"安井子育て支援課長","answer":"国も、やはり基本的に手当をばっさりただ切るという方針でやっているわけではありませんので、なるべく自立支援のほうへ向かっていただきたいということで、そういった制度は今のところまだ生きているという形になっております。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと心配だったのでお聞きしました。今すごく仕事を探していても、本当にご相談に行っても、お子さんを抱えていてというところでは、なかなかないですよね。一律に切るというのではなくて就労支援を力を入れているということなので、ぜひその方向で行ってほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"の平成２１年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"の平成２１年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"家庭あんしんセンターのほうなんですけれども、まず、ちょっと概要になってしまうかもしれないんですが、こちらのほうから、真ん中辺に書いてあります「平成２０年度に療育部門が品川児童学園に移転」というふうになっていますが、ここの部分で、どういうふうに評価をされているのか、相談部門みたいなものが品川児童学園でも、こちらのほうでも。","respondent":"安井子育て支援課長","answer":"そちらのその後の、あちらに週何回通うとかということで、それから、継続してその子どもたちを見ていくという立場に立ちますと、やはり最初に見た段階と、それから療育指導が全く別の人が行うというのはあまり望ましくないだろうというところで。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"次は、養育支援訪問事業がこちらのほうで充実をしていこうということなんですけれども、延べ件数が２４８件ということは、多分件数としてはもっと大分少ないのではないかというふうに思うんですが、件数がどのぐらいかと、あと、ここに専門のスタッフの方たちは、どういう体制でいらっしゃるのか、大変重要なところで、連携も必要だし、相当ハードな職場になってくるかと思うんですが。","respondent":"安井子育て支援課長","answer":"子どもを見る方と、それからお母さんに対応する方と、お２人セットで必ず伺うということと、それから、家の中の状況をよく見せていただくということも必要になるのかなと考えています。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"１つ。ぷりすくーるのほうなんですが、総括のところに、２ページ目で、評価事項のところで2)なんですけれども、「上級保育学校」とあるんですけれども、これは何ですか。ちょっと説明していただけますか。","respondent":"吉岡保育課長","answer":"例えば今年度について言いますと、子どもの眠りの研究ということで、つい先月、６月２６日ですけれども、中小企業センターで、「子どもの夜更かしは大丈夫？","id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"上級保育学校というそのものがどういうものなんですかと。そこでやっている研究なのか、どういう組織をつくったのか、よくわからないんです。","respondent":"吉岡保育課長","answer":"今言ったのは、今年度、研究テーマというのを掲げてありますけれども、ぷりすくーる西五反田の保育士、幼稚園教諭、それから、区内の保育士、幼稚園教諭等が、今言ったようなテーマに基づきましていろいろ研究をしたり。","id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"ということは、ぷりすくーるも独自で研修の場をつくられているということでよろしいんですか。","respondent":"吉岡保育課長","answer":"さようです。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"新しい情報が載っていないというところにおいて、もうちょっと中身が知りたいなという意味で、ここの事業報告書のところの来訪者と来館者数とかが出ていますけれども、例えば先ほどショートステイとかトワイライトステイが数が落ちていると、それは必要に迫られている人が求めるから必要がなければそれでいいんですけれども、どんな状況になっているのかなとか、あと、ファミリーサポートにしても。","respondent":"安井子育て支援課長","answer":"子育て支援センターですけれども、子育て支援センターについては、いわゆる子育て広場という形で、お母さんと小さいお子さんが来て、親子サロンとか、保育園の一時交流室と同じような形で、サークル活動ですとか、そういったものにつなげていって、子育ての不安を解消するとか。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"多分見られていらっしゃると思うんですが、要望や不満を事業所に言いやすいかどうかというところで、「はい」が５５％で、「どちらとも言えない」が２７％、「いいえ」が１３％とか、利用者の要望や不満はきちんと対応されているかというので、「はい」が４７％で、「どちらとも言えない」が４１％、「いいえ」が８％とか。","respondent":"安井子育て支援課長、吉岡保育課長","answer":"苦情の処理制度ですけれども、改善が必要とされた原因の分析及び対応方針というところとも関連しているんですけれども、苦情について意見箱を用意していまして、ご意見、介入が必要だというような形になったものがあるんですけれども。それで、ぷりすくーるといいますか、受託しているＮＰＯ法人としても、サービス向上について十分意識を持っておりまして、内部でも苦情サービスの向上委員会というようなものも年に６回ほど開いて。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"予算のところなんですが、国基準プラス区の加算ということで、平成２１年度からということは、その前は国基準かなんかで切られて減ってしまっていたということなのか、ちょっとこの辺の増額を図ったというのが、例えば人で何人分なのかとか、その辺がわかったら、その辺がどのように増えたのか違いを教えてください。","respondent":"吉岡保育課長","answer":"算定の項目自体、時代の変化とともに適切性を欠いているものもございまして、その辺を児童福祉法に基づきます保育園の国が支弁すべき経費、支弁単価に基づき計算した部分プラス、先ほど申しましたように、区の１００人規模の保育園を経営する場合、子ども１人当たり。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"これは緊急避難ですから、どうしてもという場合はこういう制度があることによって助かる保護者の方もいらっしゃると思うんですが、こういうものを恒常的に使っておられるという方はいらっしゃらないでしょうか。それから、ぷりすくーるのところですが、先ほどから苦情処理の問題が出ていると思うんですけれども、では、親の満足は１００％かなえるべきものなのでしょうか。まさか下げることはないですよね。","respondent":"吉岡保育課長、安井子育て支援課長","answer":"ただ、一定の保育園にご要望をいただいたときに、理由の説明なり、適切なお話し合いによって、納得いただければ、ある程度、苦情に対する受けとめ方は満足度が上がってくるのだろうと思いますので、その辺のところで。ショートステイ、トワイライトステイについてですけれども、傾向として減ったという話はてきめんにリーマン・ブラザーズショックからやっぱり出てきているというのはあるんですけれども。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"家庭あんしんセンターのほうを先になんですが、恒常的に使っている方はいらっしゃらないんですかというのをお答えいただきたいんですが、いろいろ指導していかなければいけないということがあると思うので、十分にその家庭の状況について対応しているということだと思うんですが、保育園が１０時まで預けているよという現実があります。小学校のすまいるスクールは長くて６時までですよね。","respondent":"安井子育て支援課長、吉岡保育課長","answer":"トワイライトステイについて、３日ぐらい前までに申し込みいただくという形になっていまして、ずっと毎日のようにということではなくて、例えば小さな商店だとか、そういうところにお勤めの方の場合、棚卸の時期であるとか。ただし、経営、運営ですので、無制限に経費を投入してやるということにはならないので、その辺は決算の状況をよく分析しまして、必要十分な研究をやっていただきながら。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/976656?Template=document&Id=4706#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":39740,"voices":86}},{"id":"h22-20100721-14","meetingId":"h22-cm07","date":"2010年7月21日","dateIso":"2010-07-21","committee":"行財政改革特別委員会","time":"午後１時０２分～午後３時０１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","topics":[{"id":"topic-01","title":"の事務事業評価に関すること","agenda":"の事務事業評価に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この前の５年間やった目的の中に、そういった目的があったのかどうかお伺いします。それであとあわせまして、５年間続けた事務事業評価を、前回は一たん終了したわけですけれども、その理由とそれをまた今回改めて復活させるといいますか、その目的をお伺いします。","respondent":"久保田行財政改革担当課長","answer":"前回の事務事業評価につきましては、平成１３年度から平成１７年度の５年間、全事務事業を対象に評価を実施してきたところでございまして、ここの部分で一定の総括を行いまして、さらなる新たな事務事業評価の仕組みを検討するといったところで、前回の制度については。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"最小の費用で最大の効果というところが１つのポイントだというお話だったんですが、前回の５年間の事務事業評価で、民間委託も進んで、職員定数の削減も進んだと思うんですけれども、以前の５年間、削減された職員定数というのは何人になるのかということと、事務事業評価の削減コストは大体どれぐらいになると概算しているのか伺います。","respondent":"久保田行財政改革担当課長","answer":"削減コストにつきましても、事務事業評価全体でいきますと、見直しということで事業を一部見直してやめたというものもありますし、逆に一方で拡充といったものもありますので、それら総体的にプラスマイナスといったところもありますので。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"今回の事務事業評価の公開の方法なんですけれども、今回は効率性ということで、より現場に近い課長のところは省いているようなやり方なんですけれども、内部で確定した評価が、では、評価が実際事業の見直しとどうつながっていくのかというんですか、工程表というんですか、それがあれば、お伺いしたいのと、あと実際に内部評価、自己評価なんですけれども。","respondent":"久保田行財政改革担当課長","answer":"工程表につきましては、事務事業評価につきましては、来年度の予算編成や実施計画等のローリング等に反映させていきたいというところがありますので、そうしたところを基本に事務事業評価を行っていきたいと考えております。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"今回やる事務事業評価の公開の方法というんですか、どういうふうに公開、いつのタイミングでどのような形で、区としてはこういうふうに評価したというのを当然知らせると思うんですけれども、どのタイミングでどういう形で行うのかというのを重ねてお伺いしたいのと、あと総額削減ありきではないということは当然だと思うんです。","respondent":"久保田行財政改革担当課長","answer":"公開の時期ですけれども、６月最初の調査事項概要のときにもご説明いたしましたが、予算特別委員会前に議会に報告をさせていただいた上で、区民にも公表していきたいと考えているところです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"先ほどの観点から、効率性と住民サービスの質の問題からいって、それはもうバラ色だと評価するのか、もうちょっと課題があると思っているのか、そこら辺はどのように評価しているのか、それだけお伺いします。","respondent":"久保田行財政改革担当課長","answer":"委託についての総括ですけれども、やはり事業をとり行っていく上では、その事業を行う中で効率性といったものがなければ、その事業自体の最大の効果が得られないといったところもありますので、民間委託という形で効率性も取り入れながら。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"図書館の問題もありますし、給食の問題もあります。学童保育が前回のやつでは廃止ということで、すまいるスクールに移行して、実態としては区の職員が１名配置はされておりますけれども、かなりのところを派遣とかでやっているわけですけれども、そういった評価というんですか、その結果、区としてはどういうふうに評価をしているのかというところを聞いたので、ちょっとそこら辺をお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"例えば、学童をすまいるスクールにしたですけれども、こちらの取り組みについても、区民の方から非常に好評を得ているといったところですが、こうしたものにつきましては、民間委託等をすることによって、効率的な運営を図りつつ、我々ではできない民間のノウハウというか。","id":"exchange-006"},{"speaker":"稲川委員","kind":"質問・要望","question":"さまざまあると思うので、それがまず１点と、もう１回私も勉強させていただきたいんですが、多分行政が運営をする、行政の運営だと、それはやるべきかどうかというのを議論したときに、例えば、そこを指定管理者にするとか、指定管理者だとあれだと、それが民間委託になって、ＰＰＰというんですか、結構種類があると思うんですけれども、その種類を教えてもらいたいんです。","respondent":"久保田行財政改革担当課長","answer":"行政と民間の役割ということで、民間委託を例にご説明してきたところですけれども、民間との役割分担というと、いろいろな形があろうかと考えています。","id":"exchange-007"},{"speaker":"稲川委員","kind":"質問","question":"それぐらいまで先を見て、今見直しを行っているのか。例えば、ＰＦＩというのは結構問題というか、いいところもあれば、悪いところもあるという部分で、そういう研究もちゃんと進めているのかどうなのかというのを教えてください。最近委託というのは、時代の流れからすると、もう委託ではなくて、どんどん違う手法に転換していっているような感じがするんですけれども、その辺をお答えください。","respondent":"久保田行財政改革担当課長","answer":"今、事務事業評価の作業をしておりますので、もしかしたら、今年度の中でそうしたものという評価結果も出てくる可能性もあるかと思いますけれども、私どもとしましても、民営化という言葉がいいのかどうかというのもあるかもしれませんけれども、最終的には行政ではなくて。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"今回、事務事業評価をするのに当たって、行政がやらなければならないこと、民間に託すことができることと、いずれまた分かれてくるとは思うんですが、例えば、評価の中で今後またＡの拡充とかについた場合、そういう事業が多いと判断された場合は、まず、逆に今後区役所の職員の方、行政サービスは人がやる部分が多いと思いますので、私は人の補充というんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"必ずしも拡充することによって、公務員を増やさなければならないという考えは持ってございませんで、そうした中で拡充をする中でも、より効率的な事業運営をするためには、どういう手法がいいかといったところで、先ほど来お話ししています民間委託といったところもありますし。","id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"そのようによろしくお願いします。１０年前ではなかったことだと思うんですが、当然この事務事業評価、今回は評価をするわけですから、平成２１年度までの中でどうだったというものでしょうけれども、今後どういうふうにやっていくかというものに関して、この先を見越したものがこの評価に反映されていくのかどうなのか、ちょっと教えていただけますか。","respondent":"久保田行財政改革担当課長","answer":"ランニングコスト、イニシャルコスト等については、やはりこれから施設の老朽化等が進んでくる中で、改修等も必要ですので、平成２１年度につくりました中長期改修計画等もありますが、そうしたものも踏まえながら。","id":"exchange-010"},{"speaker":"井上委員","kind":"質問・要望","question":"区として粛々とやっていれば、それでよしというような視点があったかと思うんですが、今回この評価によって、そういう部分をぜひ明らかにしてほしいと思うんですけれども、やはり区民のニーズというのは、日ごろの職務だけでは把握できないものもあると思うんですが、その辺をもう少し積極的に対応できないかということでお考えを伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"区民ニーズの把握ですが、私どもは、先ほど日ごろの職務を通じてということでご説明いたしましたが、あとは区民を代表いたします議会からもさまざまな意見といったもの、一般質問とか、委員会等で寄せられる意見といったものも、これは区民の声として大切な意見ですので。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問・要望","question":"わかりました。それは今後の課題として、先々市民の意見が反映される仕組みがあって、今後の検討ということは、市民の意見を反映することを検討するのではなくて、反映する方法の検討だと私は理解したいんですが、それでよろしいのかどうかという確認をまず先にさせていただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"今後外部の意見をどう取り入れるのかといった意見も寄せられているところですので、こうした課題につきましては、次の段階としての、ステップとしての事務事業評価をどうしていくかといったところでの課題だと認識しておりますので、次の段階におきまして。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"次、１８ページなんですけれども、今回からの評価のところで、代替性のＡのところで、区が積極的に実施すべき事業であるということは、何をもってそういうふうに判断するのかというところが見えないんですけれども、そこはどういう基準で、区民にとって区が積極的に実施すべき事業であると判断しているのか。そこのところはどういう基準を持っているのかということが１点。その次には、すごく飛ぶんです。","respondent":"久保田行財政改革担当課長","answer":"効率性のところでＡとＢの差があまりないですけれども、効率性のＡの部分につきましては、実施手法が、今やっているものが非常に効率的で、費用対効果の部分でも非常に効果的であるといった場合にはＡというところで、Ｂの場合には。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問・要望","question":"見直しの中で、私は非常に重要だと思うのが、統合するという部分があってもいいと思うんです。事業部内での統合ではなくて、別事業部が同じような事業をやっているときに、統合して、なおかつ効果的にできるのではないかと。検討の余地があるのかどうかわかりませんが、そういう意見に対して何かお考えがあれば、お聞かせいただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"その役割として、私ども企画財政課、企画部が各事業を横ぐし的な視点を持って、横断的に評価もしていくといったところも非常に大切ではないかと考えていますので、そういった視点も取り入れながら、事務事業評価を実施していきたいと考えているところです。","id":"exchange-014"},{"speaker":"石田委員","kind":"質問・要望","question":"そのうちの約半分の１６６事業が載っているというのはどういった理由があるのか、まず、その２点をお聞かせください。","respondent":"久保田行財政改革担当課長","answer":"もう１つのほうなんですけれども、６ページの各年度の評価実施状況のＣとＤの部分が、５年間合計すると３００事業を超えているということで、こちらの見直し、廃止・中止とされた現時点の改善状況の取りまとめというところが１６６事業ということで。","id":"exchange-015"},{"speaker":"石田委員","kind":"質問","question":"この年間スケジュールを聞くと、一次評価、二次評価があって、公表がある。半分ということは、残りの１６０事業近いものというのは重なっている部分として考えていいんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"数の件ですけれども、こちらにつきましては、重複というところでございまして、延べ件数ですので、例えば、２年、３年かけて１つの事業について、全体、項目について見直しということであれば、その件数が延べ件数として挙がってきますので、６ページでは三百幾つという形ですが。","id":"exchange-016"},{"speaker":"石田委員","kind":"質問・要望","question":"例えば、見直しする事業も５０事業から６２事業の間で行き来していますし、廃止・中止する事業も、平成１７年度は４と書いてありますけれども、完了する事業を含めたら、９ですから、大体同じような数字がそこに並んでいるというので、ほかのページに課題の中で、作業が膨大で煩雑になってしまうので、数値の選び方とか、的確さに欠けてしまったという部分が載っているんですが、私はこれをぱっと見たときに。","respondent":"久保田行財政改革担当課長","answer":"平成１７年度に、最後に事務事業評価をやって、まだ見直しになっているものについてですが、これにつきましても、事務事業評価は平成１７年度で一たん終えていますので、平成１８年度、平成１９年度の中でそれぞれ事務事業評価の結果に基づいて。","id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"それからもう１つ、これを書くのは担当者氏名、連絡先というので、事業部長が書くわけじゃないだろう、だれかが書いてくるんだろうと思うんですが、その書くメンバーというのはどういう人を考えているのか、担当課長なり、係長なりが指名するのか、それともぽんぽんぽんと勝手に選んできて、お願いするのか、ここは客観的なものと主観的なものが出てくると思うので、書き方によっては、その次に。","respondent":"久保田行財政改革担当課長","answer":"例えば、事業実績というところで、右側の欄に目標、実績と書いてありますけれども、これも前回の課題の中でいろいろと挙げられたところですが、数量化が難しい事業というものが確かにありますので、そうしたものの数量化の部分、例えば、予算書に挙げている数を目標にして。","id":"exchange-018"},{"speaker":"須藤委員","kind":"質問","question":"事務事業評価は、過去のがどうなのかと聞いたのは、このこと自体が１つの仕事になってきて、本来の仕事が少しおろそかになってしまうという思いがあるので、またこういうのを書くのは、所管課でも得意な人がいるので、どうしてもそういう人に集中していってしまうのではないかという思いがあるので、そのあたりをしっかりしないと。","respondent":"久保田行財政改革担当課長","answer":"多分こちらの担当者氏名に書くのは係長の名前が書いてあるんだとは思うんですけれども、実際には、現場で事業をとり行っている職員一人ひとりがそれぞれの担当職務について原案というか、たたき台となるものは書いていると考えていますので。","id":"exchange-019"},{"speaker":"菊地委員","kind":"意見","question":"先ほどから聞いていると、区民参加とかというのは今後の課題だと言うんですけれども、これは最も重要な部分を抜きにして、今回、この３つの必要性とか、代替性、効率性だけで考えていくというんだけれども、透明性の問題というのは、ここにはっきりと入れるべきなのではないかと私は思うんですけれども、その辺の考え方を聞かせていただけますか。","respondent":"久保田行財政改革担当課長","answer":"ただ、透明性ということにつきまして、事務事業評価を行った結果につきましては、私どももきちんと公表していくといったところですので、そういった中で透明性、公平性というものも担保していきたいと考えています。","id":"exchange-020"},{"speaker":"菊地委員","kind":"質問","question":"最初、初年度やったときから９年目になるわけですよね。この間最も行財政改革の中で必要な区民の参加の問題や情報公開、説明責任というところで、この行政評価の中に、今後の課題だと言っているんですけれども、取り入れられなかった理由というのは何なんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"全事務事業全体を見直すというところが重要だと考えまして、その意味では区が主体となって事業を実施している点では、区が主体となった内部評価を行うのがまず第１段階であろうという判断をいたしまして、今回は外部評価を取り入れなかったです。","id":"exchange-021"},{"speaker":"菊地委員","kind":"意見","question":"５年間やってみて、その中で生まれた教訓というのは、単純にここに出されているだけの問題ではないんだと思うんです。事務事業評価は行財政改革の１つの手法である以上は、やっぱりどうやって説明責任を果たしていくのか、情報公開の方法はいろいろな手だてがあるんだと思うんですけれども、いろいろな手だてを使って、情報公開をしてきたのかどうかということも、１つの評価の基準なんだと思うんです。","respondent":"久保田行財政改革担当課長","answer":"私どもでも５年間実施してきたという成果と課題はありますが、また今回改めて平成２２年度に新たな仕組みで事務事業評価を行うといったところがありますので、その意味では、まずは第１段階として、区の内部評価という取り組みをさせていただいたです。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問","question":"各部長がこれを書かなければいけないわけですよね。相当な作業になってくる。ですから、ここの部長の評価というのは、どういうふうに出てくるのかなというのが、そこら辺を見てみたいという気もするんです、自分とすると。その辺、課長のほうで答えるのは非常に答えにくい部分かもしれないけれども、部長職としてどのようにとらえていくのかなという考え方をちょっと教えてもらえばと思います。","respondent":"日下部企画部長","answer":"実際に事業部長として評価をするに当たって重要なことは、今なぜ事務事業評価を改めて実施しなければいけないのか、その原点をしっかりと我々が認識するところから始まるんじゃないかと思います。この間、行財政改革担当課長のほうでご説明させていただきました。５年間やった。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問・要望","question":"前の平成１８年のものを見ても、評価後の改善内容なんていうと、個別にものすごく丁寧に書いてある。それと、部長の思いが各課長、係長、係の方にどのように伝わっていくかというのもこれから重要な課題だと思うので、その辺も下の担当の係の方にもわかるようなメッセージをしっかり出していただきたいなと思って、その辺をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問・要望","question":"区政資料コーナーに来なければ見られないということではなくて、見たいと思う人が見られるという、今ＩＴも盛んになって、ホームページを見る方たちの層も広がっていると思いますので、そこはしっかりと、幾ら内部の評価であるということでも、税金を使われて行う事業として当然の仕事だと思いますので、その辺は前向きにというか、絶対にというか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-02","title":"の公有地活用に関すること","agenda":"の公有地活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"なかなか地元では、そもそもここがＴＯＣの駐車場になるということが、もちろん知っている人もいますけれども、知らない方もまだまだいるので、何が言いたいかというと、庁内検討会というのはいいんですけれども、それぞれの跡地について情報を出して、区民の皆さんのご意見というのを、くどいようなんですけれども。","respondent":"久保田行財政改革担当課長","answer":"こうした中で、区民の声をですが、区民からの要望につきましては、私どもは日ごろより区民の声として承っているところもありますし、区民の方にも跡地等につきましては、本委員会をはじめ、議会にもそれぞれご報告させていただいているところですので。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"この話をすると繰り返しになってしまう面があるので、あまり長くやれないんですけれども、庁内検討会というところでもう少し具体的に、前にも聞いたかと思うので恐縮なんですが、跡地活用をしていく上で庁内の検討会という話が出るんですけれども、具体的にどういう仕組みで庁内で検討されていくのかというのを、スケジュールをもって教えていただきたいんです。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、跡地についてそれぞれ現在どうなっているかといった状況等もご説明していきながら、長期基本計画に掲げるような行政計画の中で、どういう施設、事業展開が必要かというところ、また、跡地の活用という意味では、財産的な活用といった側面もありますので。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"今のご説明で、私、認識が足りなかったんですが、詳細を詰めているということは、今までとは違って、新しい組織というんですか、庁内検討会というものを新たに立ち上げる計画をされているということなんですか。今、ちょっと驚いたので、それをお伺いしたいのと、それは何を検討の対象に乗せるんでしょうか。この１から７全部なんでしょうか。それを具体的にお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"新たな組織というものではありませんけれども、今まで跡地等を活用する中で検討してきた延長線上ということで、きちんとした形で事業部長にお集まりいただきまして、跡地というものについての検討をいただければと考えているところです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"確認","question":"庁内検討会で検討するものは、この１から７全部なんですか。それで、検討された案はどのような形で出されるんですか。それを確認したいんです。","respondent":"久保田行財政改革担当課長","answer":"跡地ということで、今お手元にお配りしています資料の中にありますように、７つの跡地がありますので、こちらを中心に検討をしていきたいと考えています。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"それぞれについて原案ができ上がり次第、随時、行財政改革特別委員会にその案が出されるということでよろしいんでしょうか。以前の平塚小学校のような感じなんでしょうか。そこら辺をもう一度お願いします。","respondent":"久保田行財政改革担当課長","answer":"検討の形ですけれども、今までは個別についていろいろ、個々具体的にやってきたんですけれども、今回この７つについて、跡地全般について議論をしていきたいということで、こうした会を設置できればと考えているところです。","id":"exchange-030"},{"speaker":"井上委員","kind":"質問・要望","question":"前回の視察でちょっと疑問なんですけれども、１番の大崎在宅サービスセンターは、平成２５年までということで、跡地は品川区の所有かと思うんですが、建物は結果的に平成２５年の後は、どこの所有かによってあのまま残るのか、なくなるのか、あるのかと思いますので、その辺のところを説明いただきたいということと、もう１つ、今の安藤委員の質疑の中で、原案を行財政改革特別委員会。","respondent":"久保田行財政改革担当課長","answer":"もう１点ですけれども、原案の時期についてというご質問ですが、これらにつきましては、これらすべての原案をまとめて、１つの時期にということではなくて、利用計画がたたき台というか、素案というか。","id":"exchange-031"},{"speaker":"井上委員","kind":"質問","question":"１番目のところ、ちょっとわからないんですが、大崎在宅サービスセンターは、再開発で戻るということが前提だと思うんですが、リース会社の建物であるということは、区がその土地を貸してあげて、リース会社が建てたという認識なんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"それ以外のもともとあった建物については、その跡地活用の内容によってどうするかというのを含めて、検討していきたいと考えているところです。","id":"exchange-032"},{"speaker":"井上委員","kind":"質問","question":"そこは後で整理したいと思います。たまたまその場所で跡活用ができるということでできた部分についても、結果的にこういうふうにならしてみたときに、そこではなくて、違う場所のほうがもっと効率的な運営ができたり、そういう事例はないことはないと思うんですけれども、そういう検討というのはいろいろな時期にされるべきだと思うんですが、そういうことはされないんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"そうしたことも含めまして、私どもとしましては、施設の跡地活用を図っていく上では、施設の立地条件とか、施設の持つ特徴とか、特殊性といったもの、また、地域の状況等も踏まえながら、適正な配置ができるように。","id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"リサイクルショップというのは行政が本当にやるべきことなのかと言えば、地域でもそういう市民団体もありますし、もうそろそろそういうことも含めて、ここは区の耐震工事をしている部分の場所をもう少し有効活用すべきではないかと、そういう発想もあると思いますので、行ったから必ず戻ってくるということではなくて、トータルで場所の検討もあわせてぜひしていただきたいと思います。これは要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"石田委員","kind":"確認","question":"１点だけ、先ほどで出ました大崎在宅サービスセンターの件なんですが、これは視察をした際に、プレハブの部分にリース期間が載っていたんですが、そのリース期間が平成２５年まで区が使う予定だと聞いていたんですが、年月日は忘れてしまったんですが、当初予定されている平成２５年より前にリース期間が終わるような表記がされていたんですが、その辺の確認をしたいと思いますので、よろしくお願いします。","respondent":"久保田行財政改革担当課長","answer":"委員ご指摘のように、平成２５年度までということですから、たしか私の記憶では、あれは平成２５年１月か、平成２４年１２月ぐらいの表記だったと思うんですけれども、福栄会に確認をしたところ、リースの時期がちょっとずれたので、日付がそういうふうになっているということで。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/677130?Template=document&Id=5888#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":39035,"voices":78}},{"id":"h22-20100722-15","meetingId":"h22-cm07","date":"2010年7月22日","dateIso":"2010-07-22","committee":"環境対策特別委員会","time":"午後１時０２分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/187541?Template=document&Id=6192#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":2722,"voices":11}},{"id":"h22-20100726-5","meetingId":"h22-cm07","date":"2010年7月26日","dateIso":"2010-07-26","committee":"総務委員会","time":"午後１時０１分～午後５時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","topics":[{"id":"topic-01","title":"最初に、報告事項を聴取します。 それでは、(1)区民活動情報サイトの開設","agenda":"最初に、報告事項を聴取します。 それでは、(1)区民活動情報サイトの開設","exchanges":[{"speaker":"堺委員","kind":"提案","question":"何点か確認で教えていただきたいんですけれども、我が会派が、たしか平成２１年２月の第１回定例会のときに、協働ということを取り上げた経緯があるんですけれども、その際に、新たな協働の推進者となる区民が集う場として、他の自治体で既に導入実績のある地域ＳＮＳというんですね、この導入を提案した経緯があるんです。","respondent":"中川原広報広聴課長","answer":"ほかの自治体の様子なども、始めているところに視察等で勉強させていただいたんですが、立ち上げたのですが、なかなか動いていないという問題、状況があるようで、いろいろな機能をやることも想定はいたしますが、まずは、皆さんの活動の紹介をして。","id":"exchange-001"},{"speaker":"堺委員","kind":"質問","question":"わかりました。その辺がまだ書かれていないが、これからの検討になるのか。それから、構築業者、運営業者、そういうふうになってくるんだろうと思うんですけれども、その辺の選定方法というのか、業者というのか、その辺については、これから検討するのか、もう既に決まっているのか、その辺はどうなんでしょうか。","respondent":"中川原広報広聴課長","answer":"業者の選定にあたりましては、４月末に簡易プロポーザルを行いまして、そこに業者を募りまして、審査会を開きまして、また選定会議を行いまして、業者が決定しております。","id":"exchange-002"},{"speaker":"堺委員","kind":"質問","question":"７月１７日の参加希望者のサイトの説明会の件なんですけれども、どのぐらい参加したのかと聞こうと思ったら、たしか、１２０名ということだったようですけれども、そうしますと、その中で絞られていくのか、それが全部登録できるのか、どうか。登録できる団体数の上限というのがあるのか、ないのか。あれば、どこまでなのか、その辺のところはどうなんでしょうか。","respondent":"中川原広報広聴課長","answer":"ただし、自分たちで入力したいという、ＩＤパスワードを持って、イベントとか、講座とかを随時発信していきたいというところは、そこまでは契約の金額に入っていませんで、それは、今のところ、３００団体ぐらいまでという形でご用意はしているところです。","id":"exchange-003"},{"speaker":"堺委員","kind":"質問・要望","question":"そういう場合なんかは、そういう要望にこたえていくことは可能なのか、どうか。こういう協働という面から考えていくと、仮にそういう要望等があれば、積極的にそういう改善等に取り組まれたほうがいいような気もするんですけれども、その辺のお考えは、どうなんでしょうか。","respondent":"中川原広報広聴課長","answer":"先日、７月１７日の説明会で集まっていただいた１２０名の方たちとお話をしますと、とてもこういうことが得意でどんどんやりたいタイプと、載せたいんだけれども、ちょっとパソコンは、という方まで幅が広いんです。","id":"exchange-004"},{"speaker":"堺委員","kind":"意見","question":"今のお話のように、そういう差があるというのは、私もちょっとよくわからなかったので、みんなほとんど同レベルというか、かなりレベルの高い人たちがこういうところに参加してきているのかと思いましたので、それを前提にして、ちょっとお尋ねしたんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"土井委員","kind":"質問・要望","question":"ということですから、この形が一番適切なのかどうかも含めたものについて、どのように議論がされて、こうなってきたのかということ、その辺のことをちょっとお聞かせいただきたい。特に今、いろいろな入力ができるサイト等を見ると、さまざまな課題の問題が起こっているのが現実ですから、それらのものに対処するためにも、どこが管理をして、どこがどうするのか。","respondent":"中川原広報広聴課長","answer":"今回、大体こういう形ができて、説明会を開く前の７月初旬に、把握できるところには、個別に１,８００団体に通知を出したり、所管を通じて説明をしてもらったりしまして、個別に説明もできる限りした中で登録を受け付けて、質問なども承って、今、進めているところです。","id":"exchange-006"},{"speaker":"土井委員","kind":"質問","question":"だから、そこら辺がどのように議論をされてこういう形になったのかということが知りたいんです。運用サイトの皆さんは、このぐらいはいいだろうと思ったけれども、お役所はだめでしたなんていう話とかは往々にして起こる話ですから、そこら辺をどのようにして調整をするというか、どういう発想を持ってやっていくのかということを話してください。","respondent":"中川原広報広聴課長","answer":"このサイトに関する区の関与ですが、要綱で定めすることになると思うんですが、システム管理運営委員会というのを、やはり庁内に設けまして、適正な運営を担保していくということを、区として行っていく予定です。","id":"exchange-007"},{"speaker":"土井委員","kind":"意見","question":"まさしく、下手すると官権で押さえつける話になりかねないという、もっと協働で、民間の皆さんが幅広く柔かい頭でやっていただこうというのと、そことをどう調整するという話なので、あまり固い話をされると、ちょっとまた何か言いたくなってしまう。","respondent":"中川原広報広聴課長","answer":"どこまで関与というのは、先ほど、すみません、運営委員会もそうなんですが、できれば、区民の方同士でやっていただくのが理想的なんですが、やはりこのサイトは区が立ち上げてやるというところに信頼性があると思いますので、ある一定の新しく始める方とか。","id":"exchange-008"},{"speaker":"土井委員","kind":"質問","question":"そこら辺を非常に気にしているものですから、お話を伺っているんです。一定の信頼性を担保するために、区が立ち上げるんですと、そのお話は、それも一つの考え方ではありますけれども、逆に柔軟に進んでいかないと、この種のものは発展していかないのではないかという発想も、これまた大いにあるわけで、その辺がちょっと、今のお話だけではわからないんです。","respondent":"日下部企画部長","answer":"それで、今後のそういう状況もしっかりと見極めて、区側としても柔軟な対処をしていく、そういう方向で進めていくのが一番適切ではないかと考えているところです。","id":"exchange-009"},{"speaker":"土井委員","kind":"質問・要望","question":"そうすると、変な疑いばかり起きて、かえって信頼感をなくすという問題等があるので、そこら辺がきちんと、ある意味では、話し合いがされて、もう公表ですから、公開しているわけですから、その中できちんとみんなが議論できるような、するような、そういう雰囲気も含めたものをつくっていただきたいということで、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"意見","question":"事業をＮＰＯ法人に委託するということなんですけれども、これはどういうふうにつくっているのかということと、具体的にどこというのが決まっているのかどうか、お尋ねしたい。それから、１,８００団体に通知して、１２０名が参加したという話なんですけれども、どういう団体なのかということ、区は、どういう団体を想定しているのかというところを聞きたいと思います。","respondent":"中川原広報広聴課長","answer":"それもまだ個別にお話ししていませんので、どういう方かはちょっとあれなんですが、やりとりしながら、委託事業ではないので、こういうことだったらできるというあたりをお話ししながらやっていかないと難しいかなというところはあります。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"１２０団体がきて、枠としては１,０００団体あるということなんですけれども、大体、どのぐらいの団体が来ると想定されているのか。年間１６０万円のランニングコストといいますけれども、それとの費用の関係、どういうふうにお考えなのか伺いたいと思います。","respondent":"中川原広報広聴課長","answer":"それで、第１次締め切りを７月末にして、８月にもう１回説明会をやって、第２次締め切りをして、アンケートを取りましたら、９月オープンした様子を見て、また決めたいというところもありますので、やはり何カ月か、３月までにいろいろやりとりをさせていただいて、今回。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"まして、これから急速にネット社会がますます発展していくわけですから、そういう意味では、一歩踏み出したということは価値があるのではないかと思います。責任としては、システムの管理運営を区で構築しているわけですから、そこに対して、ここのＮＰＯ法人がきちんと管理できるような裏付けは、ちゃんとお持ちになっているのでしょうか。どのような状況になっているのか。","respondent":"中川原広報広聴課長","answer":"このサイトなんですけれども、原則、ＣＭＳという仕組みを使っていまして、わりと簡単に入力できるということは、そんなに難しいことは入らないということです。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"私の質問の内容が悪かったのかもしれないんですが、善意で登録された方がいますよね。でも、サイトというのは、突然変わりますよね。そのときに、やっぱりだれかが必ず監視できるような状況は、ちゃんとあるのかどうか。それだけ、ちょっと心配しているんですが、何かお考えでしょうか。","respondent":"中川原広報広聴課長","answer":"今後、ＮＰＯ法人と具体的な話をする中で、どこまでできるかということは考えていく形になると思います。ほんとうに大事なことだと思います。","id":"exchange-014"},{"speaker":"林委員","kind":"質問","question":"いろいろ議論された中で、区が出すというのは、さっきから出ている個人がつくる、あるいは、個の団体がつくるホームページと基本的に違うところだと思うんですけれども、さっき言っていた、だめなものは何があるんですか。極端に一つ言うと、品川区という自治体に対するチェックというのも入れておいてあげればいいのではないですか。だめというのだけびしっと言ってくれますか。","respondent":"中川原広報広聴課長","answer":"これは、登録をしていただかないと使えなくて、登録をしていただくのはサイト管理者で、サイト管理者は品川区になっているんです。登録の段階で、今から申し上げます、だめというのは、チェックをする予定になっています。","id":"exchange-015"},{"speaker":"林委員","kind":"意見","question":"その他というところが問題になりそうだけれども、例えば社会貢献活動を行っている団体ならいいというのは、その活動のみについては認めるという細かいことが言われるのか、スタートするときまでに。どういうのが営利団体なのか、このサイトを運営しているのも、営利団体でしょう。","respondent":"中川原広報広聴課長","answer":"ですから、その会社の製品をこのサイトでＰＲすることはできないんですけれども、例えば区内で清掃活動をやるとか、そういった品川区のために企業が貢献している活動があれば、ここでご紹介することができるということなんです。","id":"exchange-016"},{"speaker":"林委員","kind":"意見","question":"その辺が危なくなってくる。助成金は出るけれども、７０歳以上の人を新規に雇用したら、雇用促進のためとなる。そういう意味で、スタートするときに、かなり区のほうがプレッシャーを感じて、これに参加する人もプレッシャーを感じてくれてスタートしたほうがいいように、私は思いますので、それだけを念を押して、改めてお願いをしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"}]},{"id":"topic-02","title":"の「広報しながわ」全戸配布の実証実験","agenda":"の「広報しながわ」全戸配布の実証実験","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"新聞の講読者数が少なくなっている状況にありますから、それはそれでいいんですけれども、では、それでどうなったかということを、どう確認をするのかということにもつながらないと、評価ができないので、そこら辺をどのようにお考えになっているのかということ。その方法等によっては、具体的なものはなかなかわからないという形になりかねませんので、そこをちょっと聞かせていただきたいと思います。","respondent":"中川原広報広聴課長","answer":"それを受けまして、区のほうで、できるだけ多くの方に配布する方法としまして、どのようなことができるのかということの検討を、さらに具体的に進めるという形で考えております。","id":"exchange-018"},{"speaker":"土井委員","kind":"質問","question":"ということになると、ただ、これを配ってくださいというのではなくて、いつ幾日までに、どのように配ったかというような検証を含めたものも、業者に出してもらうことになりますよね。そうすると、今の４８７万７,０００円という費用のうち、具体的に印刷まで、物ができるまでと、配布にかかる費用と、検証にかかる費用というような意味も含めて出ているんだと思うんですけれども、内訳を教えてください。","respondent":"中川原広報広聴課長","answer":"印刷費が２６２万円です。配布業者にお願いした費用が、２０７万６,０００円で、その中に、そういった検討も含んでいるものです。","id":"exchange-019"},{"speaker":"土井委員","kind":"意見","question":"当然、今後、これがいいとなれば、年に何回とか、ある種のものは、そうすることになるんですよね。そうすると、検証費用はちゃんとやっておかないと、我々は、幾らぐらいかかるのかという検討ができないんですよ。","respondent":"中川原広報広聴課長","answer":"今回、新聞の講読者が減っているということに対しても、非常に問題意識を持って、日ごろ業務に取り組んでいるということでありますので、今回の配布する中で、事前にこういったことを見てきてくださいということで、項目としては、問題点として。","id":"exchange-020"},{"speaker":"土井委員","kind":"質問","question":"仕様で、全戸配布を３日でやってくださいということなのは、それはもうわかったんですけれども、そのためには、業者は、何人でやって、どうするという見積もりをしなければいけないわけですよね。今のお話を伺っていると、１回はできるかもしれないけれども、４０回だとできないかもしれないなんていう話になると、はじめからできないものをやるわけにはいかない、ということにもなりますよね。","respondent":"中川原広報広聴課長","answer":"これを１回やったからといって、すぐに全戸配布につながるものかどうかというのも、非常に難しいとは思っているんですが、新聞講読者数が減っているという状況を見ると、何らか検討して、当面は難しいかもしれないですけれども。","id":"exchange-021"},{"speaker":"土井委員","kind":"意見","question":"そうすると、この業者は、新聞販売店だそうですけれども、この業者でいけば、２０７万円何がしというお金がかかりますと、それが回数が増えても、これから頼んでも、同じような近い値段で、回数が増えれば割引きをしてくれるのかどうかわかりませんけれども、そういう値段ですよという意味ですね。","respondent":"中川原広報広聴課長","answer":"これがそのまま言えるかどうかわかりませんが、新聞折込みですと、単価は６円２５銭なんですが、今回、全戸配布という形での単価は１０円３８銭になっております。","id":"exchange-022"},{"speaker":"堺委員","kind":"質問・要望","question":"後で本人から質疑が出るかどうかわかりませんけれども、そこで、今回、全戸配布を担当する業者については、今、新聞販売店に委託をすることになったようなんですけれども、その辺の決まった経過、その辺のところをちょっと、例えばシルバー人材センターとか、今、お話の出た新聞販売店、いわゆる新聞協会というのですか、それから、民間でもポスティング専門にやっている業者等がおりまして。","respondent":"中川原広報広聴課長","answer":"これにつきましては、一般競争入札で行いました。説明会には８社ほどお見えになりました。シルバー人材センターも見えています。すみません、手元にはないんですけれども、入札に参加したのが、そのうち４社です。シルバー人材センターは、今回は辞退をされています。","id":"exchange-023"},{"speaker":"堺委員","kind":"質問","question":"そうしますと、先ほど来からもお話が出ておりましたが、今回、配布期間が１日から３日ということなんですけれども、あくまでも実証実験が前提になっているので、例えば、このことが費用対効果という面から見ても、よかったということになって、継続して次回も実施しようということを考えるにあたっての基準といいましょうか、例えば、今回は１日、２日、３日ということになっていますが。","respondent":"中川原広報広聴課長","answer":"先ほどの一般競争入札の数に誤りがありました、すみません。説明会に６社が見えまして、３社が辞退しております。例えば、今まで私どもがやった全戸配布なんですが、「しながわガイド」があります。あれは１月半かかっているんです。","id":"exchange-024"},{"speaker":"堺委員","kind":"確認","question":"そうすると、２点確認しておきたいんですけれども、今回は、８月１日の臨時号を全戸配布する。これはこれで従来どおり、定例号と同じような形でやっていくのかどうか。今回はポスティングだから２０７万６,０００円になってしまうんですが、従来の新聞折込みで仮にやったとすれば、この経費はどのぐらいなんでしょうか。","respondent":"中川原広報広聴課長","answer":"広報紙を読んでいらっしゃる方が、在勤の方もいらっしゃいますので、今回の８月１日の臨時号につきましては、スタンド配送は行う予定です。ただ、スタンドが１本ですので、定例号と通常号が入りますので、ちょっと少なめにはなろうかと思います。","id":"exchange-025"},{"speaker":"堺委員","kind":"質問","question":"従来ですと８６万円で、ポスティングすると２０７万６,０００円だと。そうすると、これは約１２０万円の開きがあるという理解でいいんでしょうか。","respondent":"中川原広報広聴課長","answer":"全戸配布ですと、部数も多くなりますので、単価も上がりますので、そういうことになります。","id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"新聞講読世帯が減っていると。ここでは２０万世帯を対象にとなっているんですけれども、そうすると、２０万世帯で、今までは、新聞折込みだと何世帯に届いていたのか、大よそわかっているんですか。今回、全戸配布で２０万世帯の何％ぐらい、何世帯ぐらいに届くのか、そこのところをどういうふうに見ているのか伺いたいと思います。そこら辺はどうなんでしょうか。","respondent":"中川原広報広聴課長","answer":"今回はダブりではありませんで、８月１日号の定例号は、締め切りに係わる募集記事が多いので、それはやはり通常どおりやらないと、いろいろ事業に支障が出ますので、それはそれとしてやらせていただいております。","id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問","question":"新聞折込みでやった場合の２０万世帯中何世帯ぐらい届いていたか。いろいろ新聞を複数講読しているところ、していないところとかあるかと思うんですけれども、今までのやり方だと、どのぐらい行っていて、今回、どのぐらいになるのか、そこら辺の比較というか、それはどうでしょうか。","respondent":"中川原広報広聴課長","answer":"今までの新聞折込みですと７５％ぐらいが新聞折込みで、あとの部分を、広報スタンドとか、公共施設とか、郵便局、浴場組合、今年はスーパーマーケットにも置いていただいたりとか、そういったところで補足をさせていただいているというのが現状です。","id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"今までのやり方だと、新聞折込みは７５％だと。今度の全戸配布で、基本的には１００％自宅に届くということになるでしょうけれども、今、そういう前提でいいのか、どうなのか。そこら辺で１００％ではなくて、何％見ているかとかがあるんだったら、ちょっと聞きたい。そこのところは、どういうふうに考えられているのでしょうか。","respondent":"中川原広報広聴課長","answer":"区民の方にどの程度届いているかという見込みにつきましては、世論調査とかで、区民の方にどのぐらいお読みいただいているかということを把握させていただいているんですが、区からの情報は、やはり広報紙から得るという方が一番多うございまして、直近の世論調査でも。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"意見","question":"全戸配布で１００％を目指しているということなんですけれども、今までの新聞折り込みだと７５％は届いているけれども、あとはおふろ屋、駅等で見ているのではないかと、こういうところがはっきりしないわけです。そうであれば、期日が決まった申込み等があるということを言うのであれば、私はやっぱり、全戸配布のほうが筋ではないかなと思います。意見だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほども、広報広聴課長のほうから何度も話が出ていますが、やはり締め切りとか、先着順の募集記事、それをちょっと工夫して、３日以内に届かないと先に押さえられてしまっているというのでは、おっしゃるとおり、限られた団体にしか届けさせるということはできないと思うんですが、もうちょっと枠を広げて、募集の記事、応募の期間などを長くする、または抽選にするとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"林委員","kind":"質問","question":"目的の中にある、新聞講読者数が減少しているというのが、トライをするための大きい要因になっているように聞こえるし、減少しているというのは、今も意見が出たけれども、どのぐらい減少しているとつかんでいるわけですか。","respondent":"中川原広報広聴課長","answer":"実は、昨年までは１５万６,０００部を新聞折込みしていたんですが、この実証実験をやるにあたりまして、もう１回、新聞販売店に全部調査を行ったんです。そして、今年度から１３万８,０００部に精査いたしました。","id":"exchange-032"},{"speaker":"林委員","kind":"質問","question":"新聞というと、１軒で１紙だけというお宅が多いんでしょうけれども、例えば品川区役所だと、何部ぐらい取っているのかわかりませんけれども、非常にあてにならない数字でしょう、失礼な言い方ですけれども、新聞に対して、そうではないですか。読まれているという確率でいくと、確率が高い数字なんですか。広報紙が届かないという苦情はあったんですか。","respondent":"中川原広報広聴課長","answer":"もうだめになってから始めると、ちょっと振れ幅が大きいものですから、そういった意味で、この時期に実証実験させていただいて、先ほども意見を言っていただきましたが、いろいろな方法を検討して、何が一番できることなのかを考えることが必要かなと思った次第です。","id":"exchange-033"},{"speaker":"林委員","kind":"質問","question":"これについて反対しているわけではないんですけれども、新聞ということを主たる広報紙の経路としてとらえていらっしゃるようだけれども、一番大事なのは、区民が広報紙が手元にきていない、あるいは広報紙という区のいろいろな情報から、私はまるっきり除外されているというような、区民の感情というか、感覚というか、そういうことはお聞きになったことはあるんですか。","respondent":"中川原広報広聴課長","answer":"年に何回か、新聞を取っていないので広報紙が届かないのだけれども、それは不公平ではありませんかという電話をいただくことがあります。","id":"exchange-034"},{"speaker":"林委員","kind":"質問","question":"そういう人がいらっしゃるとすれば、送ってあげればいいのではないですか。年に何人かから、そういう情報が届いていないと来るとすれば、４０回出したとして、１００円で送って、１人４,０００円ではないですか。さっから言うように、反対しているわけではないんですが、そういうことも考えられるのではないのかと思うんですけれども、そこまでは突っ込んでやらないんですか。","respondent":"中川原広報広聴課長","answer":"それも検討の方策の一つには入っています。費用対効果とか、そういった場合にどういうことが起こるかとか、すべて広報のほうでは、今、担当者と案を検討はしているんですが、その中の一つとして、今回のことを、いろいろなご意見をいただきますので、すみません。","id":"exchange-035"},{"speaker":"林委員","kind":"質問","question":"郵送だって、新聞の場合は、二十何円で郵送されるようになっているから、いろいろな方法があると思うんですよ。ただ、区の情報が届かないということを訂正していくということも一つのトライなんでしょうから、十分なトライを、今回、８月の１、２、３日で実施されることでやっていただければと思います。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-03","title":"の平成２２年１０月３日執行、品川区長選挙・品川区議会議員補欠選挙執行計画","agenda":"の平成２２年１０月３日執行、品川区長選挙・品川区議会議員補欠選挙執行計画","exchanges":[{"speaker":"土井委員","kind":"質問","question":"となりますと、今回、初めて使ったわけですから、それの評価なり、何なりというものが活用されるべきだと、人数が圧倒的に少ないので、何ともあれですけれども、評価なりをきちっと活用して、公正で速やかな開票業務等が行われるようにしてもらいたいと思うんですけれども、どのようにお考えでしょうか。","respondent":"早津選挙管理委員会事務局長","answer":"これが選挙区は８％だったんです。したがって、ほぼ予定どおりに出来ていたんですが、比例区のほうが１７％という２倍以上の読み取れなかったということが起こりました。","id":"exchange-037"},{"speaker":"土井委員","kind":"質問","question":"これは、まだ私の思いだけですから、何とも申し上げられませんけれども、そういうことをしっかり検討していただいて、少なくとも来年の区議会議員選挙になりますと、また数十人が立候補されるでしょうから、そうなりますと、比例とまではいきませんけれども、相当な形で、今回短くなったのと同じ程度以上に、何とかしてもらいたいと思うものですから、ぜひ、検討を十分にしておいていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-04","title":"所管事務調査に入ります。 今年度の所管事務調査項目につきましては、６月２９日の委員会で、「都区制度のあり方」","agenda":"所管事務調査に入ります。 今年度の所管事務調査項目につきましては、６月２９日の委員会で、「都区制度のあり方」","exchanges":[{"speaker":"林委員","kind":"意見","question":"よく言われる、新人類とか、いろいろ若い人の呼び方が社会的につくられるというか、そういうときがあって、今の学校出たての人たちの社会生活習慣というか、そんな言葉があるかどうかわからないけれども、自分から積極的に何かに取り組んでいくという人が少なくなっていると、私たちは聞いているんですけれども、そういう新しい若い人たちへの、区側の特に注意をして指導というか、指導という言葉ではないか。","respondent":"榎本人事課長","answer":"世代交代の部分がありますので、その世代交代をどうやって乗り切れる職員を育てていくかということで、先ほど紹介いたしましたが、経験者採用も織りまぜながら、要は今一番少ないのが３０歳代の職員でありますので、３０歳代の経験者採用の職員も増やしながら。","id":"exchange-039"},{"speaker":"林委員","kind":"質問","question":"あくまでも基本的なベースはあるんでしょうけれども、皆さんの経験値の中から考え出した指導要領というようなものも、大事なものがたくさんあると思うんですけれども、そういうものに取り組んで、若手が品川区を支えてくれないと困るわけで、そういうこともやらなければいけないと思うんですけれども、その辺はいかがですか。","respondent":"榎本人事課長","answer":"特に人事考課制度の中では、チームワークの力をどう生かせるかという視点を重要視してやっています。人事考課も、それぞれの組織体に合った人事考課制度というのがありますので、そういう形できちんと運用していきたいという考えです。","id":"exchange-040"},{"speaker":"林委員","kind":"質問","question":"いろいろ、随時品川区に入ってきたいという若い人たちを生かしてあげる、これは皆さん方の仕事だろうと思うので、よろしくお願いしておきます。最後にちょっとお聞きしたいんですけれども、ここ５年ぐらいで、退職していった人はいらっしゃるんですか。品川区はもうすっかりわかって嫌だと出て行った人ではなくて、ここ５年ぐらいに採用した人でです。","respondent":"榎本人事課長","answer":"ただし、ちょっと病気になる方もいますので、例えば５年間の新採を見ますと、たしか二、三人は、メンタル系の病気になった方がいた記憶があります。","id":"exchange-041"},{"speaker":"土井委員","kind":"質問","question":"そういう中なんですけれども、やはり新しい人が入ってくるわけですよね。私に言わせれば、２年過ぎてしまうと、もう枠にはめるのは皆さんはお上手ですから、すとんと枠にはまってしまうのではないかなと。そうなる前に、いろいろ意見を聞いたりも含めて、こちら側の発想も変えられる研修みたいなものに活用できないのかと、こんな思いがあるんですが、どうでしょうか。","respondent":"榎本人事課長","answer":"それは全職場ではないんですけれども、例えば保育園ですと、チューター制度、メンター制度ということで、だれかがお姉さん役をやって面倒を見てくれるというような形なので、直属の上司ではない人に意見を言えるというようなところを増やしていきたいと考えています。","id":"exchange-042"},{"speaker":"土井委員","kind":"意見","question":"今のお話は、非常にいいと思うんですよね。その意味では、いわゆる型どおりではなくて、少し型を外れかけているが、ちゃんと一定のところにいると、こういう研修で、きちんと発言をする新人をつくってもらいたいと考えていますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"須貝委員","kind":"意見","question":"今回、研修のお話もありますが、ちょっと知識として、特別区の職員、平成２２年度に新人として入った方、かなり応募者が殺到したという話を聞いております、倍率も高かったと。それで、優秀な人材もかなり応募してこられたという話も聞きますが、その辺の実態について聞かせてください。","respondent":"榎本人事課長","answer":"今年、１８９人の採用のうち、９３人は保育士ということで、保育士につきましては、実技選考も踏まえて選考してきております。","id":"exchange-044"},{"speaker":"須貝委員","kind":"質問","question":"お話はわかりました。特に新人に対して、マスコミ等の情報によりますと、先ほどもお話があったかと思いますが、１年以内にやめる方が多いと。新人に対する精神的な、メンタル的なケアをするシステム、また今言った職務のケアですが、こういうことに対しては、そういうシステムとか、また、どこに相談に行きなさいというようなケアする人はいるんですか。その辺について、お聞かせください。","respondent":"榎本人事課長","answer":"それからあとは採用５年目でも、同じくカウンセラーからの話をして、もし何かあった場合には、区のカウンセラーですので、カウンセラーのほうへ相談すれば大丈夫ですよという意味も含めて、そういうような研修をしています。","id":"exchange-045"},{"speaker":"須貝委員","kind":"質問・要望","question":"成績上では優秀な方も、品川区目指して大勢の方が来られるということはありがたいんですが、ぜひ、メンタルの面に対して、ほんとうにやめる人が出ないようなケアを、今後もしっかりと取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"本多委員","kind":"質問・要望","question":"研修にも、このように何種類もありまして、新任研修だけを見ましても、特別区がやる研修所での研修のほうが基本的な部分の研修なのかなと。例えば品川区の新任研修の後期で、接遇とありますけれども、特別区の研修は基本的な部分で、品川区はレベルアップで、行政マンとしてのサービス業をレベルアップするというか、もしそういう部分が品川区の研修の中で、独自性みたいなものがあれば教えていただきたい。","respondent":"榎本人事課長","answer":"特に特別区の経験者採用につきましては、倍率はものすごく高い、普通の大学卒業のＩ類の比ではなくて、２０倍から３０倍ぐらいの倍率がありますので、面接も２回ありますし、その中で残ってくるというのは、かなり自分がどうしても公務員をやりたい。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/653420?Template=document&Id=1860#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":45841,"voices":114}},{"id":"h22-20100824-6","meetingId":"h22-cm08","date":"2010年8月24日","dateIso":"2010-08-24","committee":"区民委員会","time":"午後１時０３分～午後２時４４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","topics":[{"id":"topic-01","title":"を行います。 住民基本台帳カードの不正取得","agenda":"を行います。 住民基本台帳カードの不正取得","exchanges":[{"speaker":"渡辺委員","kind":"確認","question":"なりすましの住民基本台帳カードを取得は、その後悪用されるケースとして、どのようなことが想定されるのか、それともう１点、運転免許証の確認専用システムのソフトウエアはどのようなソフトウエアなのでしょうか。オンラインか何かで本人確認をするソフトウエアなのか、どのようなものか教えてください。","respondent":"梶戸籍住民課長","answer":"ただいまのご質問ですが、第１点目、住民基本台帳カードの不正取得でどのような犯罪が行われるかということなんですが、新聞報道とかで、例えば、携帯電話の申し込みをしている。","id":"exchange-001"},{"speaker":"菊地副委員長","kind":"質問","question":"最後のところ、情報のもとになる部分というのは、警視庁だか何だかの事項になるのか、運転免許証そのものが交付されたり、その中身については、だから、私はコンピュータのシステムがよくわからないんだけれども、ソフトウエアを入れれば、それで、はいといって出てくるような、一般的なインターネットの活用とはまた違うんだと思うんですけれども、その辺をもう少し詳しく教えてくれませんか。","respondent":"梶戸籍住民課長","answer":"ご本人が持ってございまして、その方にお聞きしたところによりますと、どうも自分の住所、あるいは電話番号、氏名、生年月日等をある団体の名簿等に出していることから、そこから漏れたんじゃないかということをおっしゃっていたんですが、ただ、それにつきましては。","id":"exchange-002"},{"speaker":"菊地副委員長","kind":"質問","question":"例えば、この中にどれだけの方が運転免許証を持っていらっしゃるかわからないけれども、一つ一つは公開されていない情報なわけですよね。だから、その情報のもとになるものというのは、ソフトウエアを入れることで、どういうふうに取得できるのかということなんです。要は、普通に考えますと、警視庁からその情報も全部入ることになります。だから、その辺のことをちょっと教えてもらいたいんです。","respondent":"梶戸籍住民課長","answer":"専用ソフトウエアのお話ですね。","id":"exchange-003"},{"speaker":"菊地副委員長","kind":"意見","question":"ソフトウエアがどうなるのかというところから、運転免許証の情報。","respondent":"梶戸籍住民課長","answer":"運転免許証のＩＣチップの中に入っている情報というのは、運転免許証の表書きに書いてあります生年月日と運転免許証の種類と顔写真がＩＣチップの中に入っているということです。","id":"exchange-004"},{"speaker":"菊地副委員長","kind":"質問","question":"それはわかったんですけれども、一般的な質問、私がそのソフトウエアを入れれば、その情報がとれるかというと、とれないわけですよね。例えば、課長の情報を私がとろうとしたときに、一般的に私が自分のパソコンにそのソフトウエアを入れたところで、それはとれないわけですよね。情報の発信元となるところとの連携というのか何というのか、そこら辺の区との関連がよくわからないんです。","respondent":"梶戸籍住民課長","answer":"運転免許証の情報を読み取れるのかという話になりますと、ソフトウエア自体は多分市販されていないものですし、ダウンロードを通常はできるようなものではありません。ネットにつながるものではなくて、その運転免許証用のＩＣチップを読み取ることができるソフトウエアなんです。","id":"exchange-005"},{"speaker":"菊地副委員長","kind":"質問","question":"要するに、それは公的な機関が発行しているソフトウエアということなんですね。そうすると、それにかかわる経費が発生してくるものになるんでしょうか。もし、発生するとなると、そういう経費というのは、住民基本台帳カードだから、どこからか、国なり、都から出てくるような経費ということなんですか、そこを最後に。","respondent":"梶戸籍住民課長","answer":"は機械なんですけれども、機械に関しましては、カードリーダーとパソコンについては、１台ずつについては、国の予算で出ております。ただし、今後各地域センターに乗せる際には、ソフトウエアは無料ですけれども、カードリーダーだけは用意しなければいけないです。","id":"exchange-006"},{"speaker":"山内委員","kind":"質問・要望","question":"住民基本台帳カードのことについて、関連で教えていただきたいんですけれども、今回はこの偽造運転免許証を本人確認資料として確認をしたと。そういった方々というのは、例えば、写真つきのものであれば、パスポートがあるし、写真つきでなければ、保険証になるけれども、住民基本台帳カードを取得するに当たっての本人確認を今後はどういう形でしていくのか。","respondent":"梶戸籍住民課長","answer":"この辺につきましては、運転免許証等につきましては、ただいま述べましたように、専用のシステムを使うとか、すかしを使うとか、もし、ご協力いただければ、運転免許証以外にもう１点何かありますかというお尋ねをしていって、少し確認を強化していきたいと考えているところです。","id":"exchange-007"},{"speaker":"山内委員","kind":"質問・要望","question":"その辺について、パスポートで住民基本台帳カードを欲しいと言った方には、２点以上のものを強制するのか、それとも、今これだと確認するシステムが多分整っていないと思うんですが、運転免許証では今こういった形で整っているという話だけれども、そういったことについてどのようにお考えなのか、国に対してどのような要望をしていくのか、その辺の流れを教えてほしいと思います。","respondent":"梶戸籍住民課長","answer":"今までの中で、そういった確認方法について、あまり苦情等は出てございません。今まで以上に２点確認につきましても、また、本人確認につきましても、区民のご協力を得ながら、確認強化に力を入れていきたいと考えているところです。","id":"exchange-008"},{"speaker":"山内委員","kind":"質問","question":"それはわかるんです。ですから、パスポートを提出された際にはどうするのかということを今聞いているんです。その辺を教えてください。","respondent":"梶戸籍住民課長","answer":"そういった中でも、パスポート等につきましても、もちろん運転免許証と同じように、コピー、写しをとって、後日通知証を送付すると同時に、運転免許証と同じように、パスポート以外に何かございませんかと提示を求めたり。","id":"exchange-009"},{"speaker":"山内委員","kind":"質問・要望","question":"最後に要望。今おっしゃったように、あわせて協力をお願いする、これを強化する必要があると思います。そうでないと、またこのような同じ事件になるということも考えられるので、その辺はよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"所管事務調査に移ります。 今年度の所管事務調査の項目につきましては、６月２９日の委員会で、「町会支援のあり方」","agenda":"所管事務調査に移ります。 今年度の所管事務調査の項目につきましては、６月２９日の委員会で、「町会支援のあり方」","exchanges":[{"speaker":"石田委員","kind":"質問","question":"町会会計アドバイザー制度についてお伺いしたいんですが、１町会３回までとなっているんですけれども、これは２時間で、３回で、それで納得していただければいいんですけれども、例えば、もうちょっと聞きたいとかという場合には、もうこの助成制度は使えないので、紹介をするというような形で対応していくのか、その辺、３回以降の部分を教えていただければと思います。そこをちょっとお願いします。","respondent":"中山地域活動課長","answer":"原則として２時間ということですから、例外がないのかということで、もし、こちらもお聞きした上で、これはアドバイザー派遣が必要な状況だということになれば、そこから有料でという形は考えておりません。","id":"exchange-011"},{"speaker":"石田委員","kind":"意見","question":"この会計アドバイザー制度は非常にいいものだと思うので、ぜひこれからも力を入れて支援していただければと思います。もう１点が、掲示板なんですが、町会の掲示板とふれあい掲示板の差は一体何なのかというのがまず１点。","respondent":"中山地域活動課長","answer":"最初の町会掲示板とふれあい掲示板の違いということで、設置主体からすれば、町会掲示板はまさに町会で、ふれあい掲示板のほうは区だという話なんですけれども、ふれあい掲示板はもともと区の広報掲示板であったものを、昭和６３年だったと思うんですけれども。","id":"exchange-012"},{"speaker":"山内委員","kind":"質問","question":"２０４町会で、町会に加入されている方というのは何人いらっしゃるんですか。そこから教えてください。","respondent":"中山地域活動課長","answer":"分子・分母が一致した数値になかなかできないというところで、約と申し上げたんですけれども、ちゃんと報告が上がってきて、会費を払っている会員数と世帯数を考えると、大体６２％ぐらいの数字というのが区内の平均値になっておりますので、半分以上の方は加入している。","id":"exchange-013"},{"speaker":"山内委員","kind":"質問・要望","question":"その辺をちょっと教えていただきたいと思います。","respondent":"中山地域活動課長","answer":"継続的な統計がないので、数値としてというは、お答えはできませんが、この間の長期的な流れを考えると、下がってきているというお声は実際町会の方から出ておりまして、それは先ほどのご説明の中で申し上げたような、特に転入して、人が入ってきても、マンション。","id":"exchange-014"},{"speaker":"山内委員","kind":"質問・要望","question":"今私もそれを言おうかと思って、マンション対策なんですけれども、品川区という土地柄を考えますと、どうしても建物が高く建っていくようなことが今後増えていくだろうといった中で、マンションの管理組合とのつながりというのを強化していく中で、会員の増員が望めるのかなというところもあるので、その辺、もう少し調査・研究をしていただいた中で、そういうところに努めていただきたいと思いますので。","respondent":"中山地域活動課長","answer":"部屋の構造からいって、何かあれば、人々が集ってやれるような形で、そのような申し出であれば、区としてはしっかり支援していこうというスタンスで考えていきたいとは思っておりますし、その結果として、最近では、予算特別委員会等でも質疑があったように記憶しているんですが。","id":"exchange-015"},{"speaker":"山内委員","kind":"質問","question":"細かいことになってしまいますけれども、うちは骨葬はオーケーですといった場合はどうするんですか。要は、平塚橋会館みたいな形で、骨葬だけだったらオーケーですとした場合、利用率は減りますよね。その場合はどうなんですか。それでもこれは葬祭として認めて、葬祭の範囲の助成をするということでいいんですか。","respondent":"中山地域活動課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういう中で、これまでの経緯の中で、特に学校なんかの変化もあったり、警察や消防という公的機関とのおつき合いの中で、よく町会に頼る比重、町会での情報量だとか、特に窓口である町会長の負担というのはよく聞かれるところなんですが、この辺はどのように、結構善意のボランティアですから、実際のところ、この善意にかなり頼っている部分が多いのかなと、聞き方があれなんですが、感想的なもの。","respondent":"中山地域活動課長","answer":"基本的にはこういう地道なことをやりながら、町会を支援し、区としては、ご負担は重々わかりつつも、まず町会と連携をとりながら、町会にお願いしながら、仕事を進めていくというのは、今後とも一番重要な進め方の１つかなと考えていますので。","id":"exchange-017"},{"speaker":"渡辺委員","kind":"質問・要望","question":"伺った中で、品川区という視点から区民サービスを見たときに、加入率が６割、これが多いか少ないかという地域差もあるでしょうし、物の見方はあると思うんですが、区民サービスを提供する当てが一番見えるというんですか、区民の顔が見える形が町会なり、商店街だと思っています。その点について伺いたいのと、もう１点は、加入促進にかかわってくるんですが、１番は、皆さん地域センターを頼られている。","respondent":"中山地域活動課長","answer":"地域センターのマネジメント機能の充実というのは、基本的には所長を中心とした職員が、先ほど来出ている町会が非常に大事だということをまず認識する中で、今現実に連合会の事務局をしているという役割がありまして、これは１つの支援として。","id":"exchange-018"},{"speaker":"渡辺委員","kind":"質問・要望","question":"最後ですが、加入率の中で、私たち自民党ではよく町会調査ということで、意識調査だとか、そういうことに取り組んだ経緯がありました。加入されて、推計で６割強という中で、逆の立場の方、加入していない方がなぜ加入しないのかという視点を、これはまだ推測でも構わないんですが、調査する価値があるという気が私はしています。その辺をどのように考えられているのか教えていただきたい。","respondent":"中山地域活動課長","answer":"町会にはなかなか聞けない話ということになりますから、アンケートをもう少しランダムにやるとかという形で考えていきたいと思います。何らかの形できちんとそういう声を聞き、それをどうやって改善していくかという対応をしていきたいと思います。","id":"exchange-019"},{"speaker":"菊地副委員長","kind":"質問","question":"１つだけ教えてもらいたいんですけれども、２０４の町会のうち、町会会館を持っている町会というのはどれぐらいなんですか。","respondent":"中山地域活動課長","answer":"どこまでを会館というかというのは、実は微妙なところがあるんですが、ざっくり言うと、約８０です。所有そのものが町会かというと、結構微妙な会館というのもあるんですが、そういうものも含めて考えていくと、約８０です。","id":"exchange-020"},{"speaker":"菊地副委員長","kind":"質問","question":"微妙なところは除いたりしても、１つは８０の町会がとりあえず会館を持っていらして、今５０町会が法人化ということですから、多分町会会館を持っているような大きな町会できっと法人化が進んでいるのかなと思うんですけれども、法人化の考え方というのは、ここで記されているのは、以前いろいろなトラブルがあったということで、財産上の問題はもちろん出てきますけれども、そういうことで。","respondent":"中山地域活動課長","answer":"１点目の３０ぐらいが法人化していないで会館を持っているのはどういうケースかということですけれども、いろいろな対応があるということを言い出すと細かくなってしまう。まあ、単純に言うと、賃借の物件もあります。必ずしも所有でないものもあります。","id":"exchange-021"},{"speaker":"高橋委員","kind":"質問・要望","question":"そういうことが起きないように、区としては今後どうされていくかというのをちょっとお伺いしたい。","respondent":"中山地域活動課長","answer":"あくまでも会費の中での話ですから、なかなか区の直接的な関与ではありませんけれども、そういうときにきちんと町会の運営であるとか、会の運営等について、どのように体制も再構築していくかということについて。","id":"exchange-022"},{"speaker":"山内委員","kind":"質問","question":"内容の２番、今スポーツごみ拾いの話がありましたけれども、これはちょっとおかしくないかなと思うんです。たくさんごみを拾ったら、そこが優勝というのは、汚いまちというのを露呈するというか、ＰＲしているようなことだと思うんだけれども、まず、この内容をどういう形で決めていったのか、その辺をちょっと教えてほしいんですけれども。","respondent":"諸岡商業・観光課長","answer":"ルール違反をしないようにということではなくて、親子連れで参加される方もいらっしゃいますので、お子さんが交通事故に遭わないようにとか、地域にご迷惑をかけないようにということをチェックしながら、そういった方々も一緒に歩くということで、わりと整然と実施され。","id":"exchange-023"},{"speaker":"山内委員","kind":"意見","question":"こうやって字だけで見ると、そういう思いがしてしまって、まさか協会があるとは思ってもいなかったので、それの説明を事前にしていただければ、ありがたかったなと。要は、散歩をしながら、いろいろと発見をしていくといった意味での取り組みだと受けとめします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"渡辺委員","kind":"質問","question":"最後、５番の主催などの運営のところなんですが、品川区の位置づけ、よくあるのが、主催、共催、後援という段階があるんですが、これは今回協賛という、珍しく見えたんですが、この辺の経緯を教えてください。","respondent":"諸岡商業・観光課長","answer":"これはあくまで主催はしながわ観光協会が中心になりまして、観光協会の中で実行委員会というのを組織いたしまして、その中で内容でありますとか、今申し上げましたスポーツごみ拾いについても、皆さん方でお決めになられたということで、主体的に実施されたものです。","id":"exchange-025"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"１つだけ聞きたいんですけれども、国勢調査が地域振興事業部の管轄になっているんですけれども、今、全国的にも問題になっている例の高齢者の方の所在不明という話、品川区はどうなっているのかがわからないので、教えていただきたいんですけれども。","respondent":"梶戸籍住民課長","answer":"厚生委員会でも多分お話が出ているかと思いますが、聞いた話では、品川区では１００歳以上の方について、所在不明の方はいらっしゃらないという形では聞いております。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/764503?Template=document&Id=2588#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":30987,"voices":75}},{"id":"h22-20100824-7","meetingId":"h22-cm08","date":"2010年8月24日","dateIso":"2010-08-24","committee":"厚生委員会","time":"午後１時０２分～午後２時４５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"品川総合福祉センター本部の改修工事と（仮称）八潮南特別養護老人ホーム整備","agenda":"品川総合福祉センター本部の改修工事と（仮称）八潮南特別養護老人ホーム整備","exchanges":[{"speaker":"南委員","kind":"確認","question":"そういう部分では、この工事期間中はどういうふうになるんですか。当初、ここの施設を建てた２８年前には複合型施設だったんだけれども、障害者施設と高齢者施設と別々の補助制度があったために分断されたということなんですけれども、この点では、全くクリアされていることなのかどうか、ちょっと確認をしたいと思います。とりあえず、以上です。","respondent":"冨岡高齢者福祉課長","answer":"各フロアの食堂ということで、これから実施設計に細かく入っていくところですが、あわせて、補助金の獲得に向けて、東京都とのやりとりも入っているということで、あらあら、各フロアということでオーケーのように聞いているところです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"２,０００万円の補助、この根拠について答弁がなかったのでお願いしたいと思います。それから、個室にすると、定員もそうですけれども、また費用についてもいろいろと出てくるということもあるんですけれども、そういう点でも、もう少し検討を要する部分もあるかなと思って伺っていました。最初の部分を、ちょっとお願いしたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"２,０００万円ということで、先ほど、申し上げましたように、当初予算でお願いしたときは、実施設計費を考えていたわけでございまして、その中で、どの程度、品川総合福祉センターに助成できるかというところを。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"２,０００万円という金額そのものは、具体的にどういう法律のもとで、どういうふうな関係の中で２,０００万円という数字で補助をするというのが出てくるのか、そのあたりの根拠を教えていただきたいということで、冒頭、質問したつもりです。よろしくお願いします。","respondent":"冨岡高齢者福祉課長","answer":"言い足りない部分がございましたけれども、実施設計といいますのは、今後、改修するにあたっての設計費ですので、どれだけ工事をするか見積もっていくための細かい設計費が２,０００万円です。","id":"exchange-003"},{"speaker":"三上委員","kind":"提案","question":"こういうようなことで、ずっと以前から、そういう提案をしてきております。ですから、この際、居室およびトイレ等について、生活する中にあってのそういったにおいを吸収するとか、浄化するとかという作用が、むしろあるようなものを積極的に活用していくべきではないかと考えていますけれども、そういった点について、この施設については検討されているのかどうかということについて、いかがでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"これを、品川総合福祉センターが検討しているか、どうかというご質問ですが、それについては、私自身はちょっと確認はしてございませんが、今、委員からこういうお話があって、においの吸収等に非常に効果があるということで、ご提案があったということにつきましては。","id":"exchange-004"},{"speaker":"三上委員","kind":"質問・要望","question":"こういった点から考えたならば、運営するところ自体は、きちっと共通するところでやるのがベターではないかと思います。ですから、西大井の保育園をつくるにあたっても、室内については、やっぱり耐久の検査もきちっとやるとかというようなことで、問題がないように対応すべきだと、いろいろ言ってきたりしてきているわけです。お答えがあったら、いただきたい。","respondent":"冨岡高齢者福祉課長","answer":"指定管理につきましては、条例の制定、それから指定管理者の選定ということで、また議会の会議等で上程する予定です。それから、珪藻土、しっくい塗料の利用につきましては、私どもももちろん、真摯に受けとめて研究させていただきたいと考えているところです。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"やはり環境が変わることによって、高齢の方は順応するのに時間がかかると思うんですけれども、そこら辺のところを、どういうふうにお考えなんでしょうか。社会福祉法人のほうに、指定管理ということで運営を委託しているわけですけれども、品川区の担当部局でおわかりになるところを教えていただきたいと思います。よろしくお願いします。","respondent":"冨岡高齢者福祉課長","answer":"さまざまな状態像の方を４０名、どのように移っていただくかということについては、慎重に法人、区と協力し合いながら検討して決めてまいりたいと考えていますので、今、軽々には答えを申し上げられない状況です。","id":"exchange-006"},{"speaker":"山元委員","kind":"質問・要望","question":"ちょっと教えていただきたいのは、やはり、「入所者の特性に応じた対応が可能なようにバリエーションを用意する」とありますが、具体的に何か考えていることがあれば、ちょっと教えていただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"障害の方の場合ですと、個室が必ずしもいいという状況ではなくて、例えば重たい人とか、知的で言えば自閉の重い方については個室がいいんですけれども、逆に、一人っきりになると不安になってしまうというような状況も見られますので。","id":"exchange-007"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"なぜそんなことを伺ったかと言いますと、具体例を見ておりますと、正直、どうしてここまで放っておいたのかなという印象を、すごく受けるんです。それから、概算９億６,０００万円と書いてありますけれども、その財源内訳というんですか、国、東京都、区、そのほか介護保険の特別会計なのか、一般財源なのか、そこがわからないので、どこから幾らというふうにお考えになっているのか、ご説明いただけますか。","respondent":"冨岡高齢者福祉課長","answer":"ただ、区については一定の支援をするという予定です。","id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"土地は区で、建物は品川総合福祉センターというお話で、今現在、指定管理者として、今は委託ですか、民設民営ですか、要するに、この資料に書いてある具体例で見ますと、この話がうまくいっているのかなと率直に感じたんです。要するに、９,５００万円かからないからこっちなんだという説明だと思うんですけれども、ちょっとこの辺を、もう少し詳しくご説明いただけますでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"障害者支援施設かもめにつきましては、対応については、当然あるかと思いますが、現在のままで工事をしていくです。事情の説明につきましては、家族会等を中心に説明をしていると聞いております。","id":"exchange-009"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"最後にもう少し伺いたいのは、今回、（仮称）八潮南特別養護老人ホームを４０ベッド使って工事をするということですけれども、この議論、検討は、いつごろから行っていたのか。あわせて、どうして仕切りがあってプライバシーに配慮したいと思ったのか、改善を図るというその理由、また区の考え方を、改めて伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"議論についての検討がいつぐらいからかですけれども、実施計画を進めていくためには、もう少し具体的な対応が必要になってくるという中において、こういう形で議論がありまして、たしか第２回定例会前ぐらいまでには、ふだん考えていたところで、まとめつつあったところです。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"伺えばよかったんですけれども、改修工事着工が来年８月ですよね。ですから、当然、それまで地域の住民への説明会なりをしなければいけないですよね。それはいつごろやろうとしているのか、ちょっとその辺だけ伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"議会に報告をさせていただいて、それに基づきまして、今後、地域への説明会等あると思いますが、今、私どもは、法人からいつとは聞いておりません。","id":"exchange-011"}]},{"id":"topic-02","title":"夜間対応型訪問介護事業所を活用した２４時間対応システムモデル事業","agenda":"夜間対応型訪問介護事業所を活用した２４時間対応システムモデル事業","exchanges":[{"speaker":"南委員","kind":"質問","question":"第５期介護保険事業計画に向けて、ということなので、この４カ月を設定されたということで、そういうことで、今この時期に国が設定したという理解でいいんですか。それから、ここにも書いてあるように、もう既に品川区としては、平成２１年度から市町村特別給付で実施していますよね。この現況がどのようになっているのかも、あわせてこの機会に伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"これにつきましては、現在、実施をしております夜間の事業と、どううまくリンクしていくのか、２４時間の見守りということで、利用者に安心感を与えていけるようになるのか、また、もちろん利用者側に立って、どういうふうに評価いただけるのかということを総合的に踏まえて。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"確かに次期の介護計画をつくるにあたってのモデルですから、前向きにやっているというところで批判することになるかもしれないけれども、どうせやるのだったら、きちんとしたデータを、という思いがあるので、ちょっと申しわけない、しつこく聞くんですけれども、こういうことを契機に、必要なことをもっと国に言っていくことも含めて、品川区のモデル実施の見解を、ちょっと１点。","respondent":"冨岡高齢者福祉課長","answer":"今回の事業ですけれども、夜間のサービスも実際にベースとして実施しているわけでございまして、そういう方を中心にお声がけをしながら、あとは、昼間、訪問介護をしている民間の事業者とも連携をとりながら進めてまいるということで、逆に言えば。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"最後におっしゃった、要支援者１２人と、その他要介護者、トータルで８３名というのは、今現在の数字で、合わせて９５名がご利用されているということで伺っていいのか、どうか。だから、さっきも申し上げたように、これは１年数カ月の間に拡大してきているんだろうと思うんですけれども、その辺の状況も、どういうふうに見たらいいのか。","respondent":"冨岡高齢者福祉課長","answer":"今回の４カ月の部分について、どう考えるかですけれども、一応、モデル事業で、さまざまな事情から決められているということで、区としては、今までの機会、それから仕組み、利用者へのお知らせというところで最善を尽くして、いい結果が出るように。","id":"exchange-014"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"この事業目的といいますか、品川区の問題意識を、少し詳しく伺いたいと思うんです。ここにはオペレーション機能とか、２４時間サービス提供とありますけれども、ちょっと仕組み全体がよくわからないので、何かボタンを押すと何かがどうなって、こうなるのか、ちょっとそこが、サービスの事業の中身がよくわからないので、そこをご説明いただけますでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"この事業を拡大していくですけれども、これは中身とちょっと絡んでまいりますが、ナースコールのボタンと思っていただければいいんですが、ペンダントのようなボタンを押しますと、夜間対応型訪問介護事業所に受信機がございまして、そちらで「どうしましたか」という声が。","id":"exchange-015"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"モデル実施をしたいということですけれども、要するにモデル実施をすることによって、ここには効率的な仕組みとそのあり方、効果等を検証すると書いてはあるんですけれども、モデル実施ですから、そういうことなんだろうと思うんですけれども、要するにどんなことを検証したいのか、どういう問題意識や課題を、今感じていて、それをモデル実施してみようというか、その内容がよくわからないんです。","respondent":"冨岡高齢者福祉課長","answer":"２４時間対応と申しますのは、地域包括ケアということで、３０分以内にさまざまな福祉、医療、それから社会的な支援といったサービスが、地域に生活をされながら受けることができるというものを、２０２５年の団塊の世代が７５歳を迎えるときを見越して、視野に入れて。","id":"exchange-016"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"緊急だとどうなるのか、その辺を伺いたい。要するに、ヘルパーに聞くと、サービス自体に介護報酬はくるけれども、移動の時間というのは、介護報酬という見方にはつかないと、そんな話も伺うので、この仕組みというのが、もちろん今後検証することですけれども、その点の問題意識というのはどんなふうにお考えになっていらっしゃるのか、お聞かせいただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"じゃあ、これを検証していきまして、今、副委員長がおっしゃったように、現在、夜間対応型訪問介護では、基本料とか随時訪問で、それぞれ介護報酬と自己負担分が出ているところでございまして、では２４時間対応型にした場合、当然考えられるのは。","id":"exchange-017"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"その中における利用設定のあり方というのは、やっぱりしっかり考えていかなければいけない。減免制度であったり、いわゆる収入よってサービスが受けられないという事態を生まないようにする必要はあると思うんですけれども、最後に、利用者の生活実態や要望にしっかり目を向けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-03","title":"平成２２年度高齢者福祉週間行事","agenda":"平成２２年度高齢者福祉週間行事","exchanges":[{"speaker":"南委員","kind":"確認","question":"１０１歳のところでは、品川区は不明の方がゼロだというお話だったんですけれども、ちょっと聞きそびれていたらと思ったので、改めて確認ですけれども、介護サービスを受けている方、そして、医療保険等と突合して、というお話でしたよね。介護サービスを受けていない１００歳以上の方なんてあり得ないんでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"今、委員おっしゃったように、民生委員には、７０歳以上のひとり暮らしの方と高齢者世帯を訪問していただいていますので、ひとり暮らしで１００歳以上の方、あるいは、高齢者のみの方については、そこでカバーできるです。","id":"exchange-019"}]},{"id":"topic-04","title":"ふくしまつり２０１０","agenda":"ふくしまつり２０１０","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"障害者団体との関係、ほかにもいろいろな団体がありますけれども、今回の会場の変更について、どういうふうに説明しているのか、どういった意見が挙がっているのか、どんな話し合いがされているのか、その現状も教えていただけますでしょうか。","respondent":"永尾障害者福祉課長","answer":"昨年から引っ張っている部分がございまして、昨年、実施する際に、大崎のニューシティのほうから、今年度、飲食の関係だとか、出展スペースについてお話がございまして、それを受けて、昨年は、ゲートシティ周辺と大崎の駅周辺で実施をいたしました。","id":"exchange-020"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"大崎ニューシティから、飲食に対して制限があったというのは、どんな理由なのか。今までどういうふうに借りていたのかも含めて、よくわからないので、率直に伺っているんですけれども、要するにどんな事情があったのか、その経過を教えていただきたいと思います。結果的にここになったということですけれども、話し合いの中身を、もう少し教えていただきたいと思います。","respondent":"木下健康福祉事業部長、永尾障害者福祉課長","answer":"夢さん橋との関係で、去年からの経過もありますので、簡単に補足しますけれども、こういう公の場ですので、あまり具体的なところは割愛しますけれども、夢さん橋のほうも、もう既に１８回ぐらいになるのでしょうか。ただ、やはり、中小企業センターの中というと、なかなか目立ちにくいというような心配もありましたので、中央公園から中小企業センターにかけてのぼり旗を立てるとか、案内員を動員するとか。","id":"exchange-021"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"第１回にしたというか、みんなのまちフェスタにしたというか、これをここで聞いて、だれがどう答えるのかよくわからないんですけれども、そこの思いといいますか、考え方といいますか、単に場所が変わったというだけではなくて、場所が変わったという問題もあるけれども、企画として第１回とした、その理由は何なのか、ご説明いただけますでしょうか。","respondent":"永尾障害者福祉課長","answer":"そのときどきにやさしいまちづくりとか、そういう関係で横の連携はとっておりましたけれども、やはり、こういうイベントを通すことによって、内部だけではなくて、区民の皆さんにも、そういうようなことを理解していただきたいという思いから。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"質問するつもりはなかったんですけれども、改めてこのチラシを見て、主催と実行委員会、事務局のところを見て、健康福祉事業部も入っているんですけれども、防災まちづくり事業部、都市環境事業部、地域振興事業部、社会福祉協議会も入れて五つのセクションが主催するということで、１面のほうは、今までずっとふくしまつりをしてこられた、そういう思いがこもったデザインになっているんでけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"一つは、私のほうでも、事前にＪＴに問い合わせをして確認しておけばよかったのかもしれないけれども、ちょっとしなかったから時間が経って、今、改めてこういう形になってしまったのは、それはそれとして申しわけないと思うんですけれども、区のほうとしても、事前にＪＴに直接なり、問い合わせする中で、こういう答弁になったのかなということと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"南委員","kind":"確認","question":"あれはたしか６月の終わりですよね。ですから、１カ月半ぐらい経った中で、ＪＴのほうが変わっているということであれば、それはそれとして理解するんですけれども、事業財産として管理をしている、活用について検討している、その活用について検討しているという中身がわからないわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"ＪＴに、あそこの土地の活用はどういうふうに考えているのかということで質問したんです。ですから、社内で活用する方針という答弁をされた、そことは、方向性も含めて、大きな開きがあるのではないかということで、今日、委員長にお許しをいただいて質問することになったわけです。ですから、企画のところが、あちらと直接交渉した中での情報提供だというところは、それはそれであったにしても…。","respondent":"冨岡高齢者福祉課長","answer":"すみません、私が聞いたのは経理課管財係です。要するに用地交渉はそこがいたしますので、その観点でしか、私は聞いておりません。","id":"exchange-026"},{"speaker":"南委員","kind":"確認","question":"改めて、品川区が管理している以外の部分についてのとらえ方は、私ももちろんですけれども、みんなそれぞれが正確な情報を持って臨まないといけないかなと、反省も込めて、思ったところです。そういうことで、出所の確認と、そこがわかったということで、とりあえず納めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"三上委員","kind":"確認","question":"そうすると、そこのところで、仮に自分では出られないかもわからないけれども、自分の代理人として、だれかが、だれだれが確認したところによると、こういうふうにＪＴは言っているけれども、そういうことについて、現段階では、もう一度確認する必要があるのではないのかということを、総務委員会の場で確認してもらいたいということであれば、それはそれで話は通るけれども、この場で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"だけれども、後で読み返してみて、また、直接聞いてみた中で、やっぱり違ったのではないかと、私は思ったので、正確性を期すという点で、それから、区のほうがどういう確認ルートをとってこられたのかも、やっぱり知る上で、その他のところで質問させていただいたということです。ですから、その辺については、ぜひ、そういうことで受けとめていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/347330?Template=document&Id=3276#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":30639,"voices":84}},{"id":"h22-20100824-8","meetingId":"h22-cm08","date":"2010年8月24日","dateIso":"2010-08-24","committee":"建設委員会","time":"午後１時０３分～午後３時１０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"今回パブリックコメントに際して説明会をあわせて開催するということで、その際、今いただいた机上配付の資料もお配りするということなのかなと思うんですが、説明会の開催というのをあわせて行っていくということはすごく大事なことだと思いますし、要望していたわけですけれども、すごくいいことだなと高く評価したいんですが、今回の説明会というのは。","respondent":"藤田水とみどりの課長","answer":"そういった面から、きちんとした説明をやはりする必要があるであろうということで今回説明会を行うというような形で進めるものです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと今制限がかかるというお話だったんですけど、若干ちょっとこの景観計画によってどのような街並みのルールがつくられて、どういう制限がかかって、街並みがどう変化するのかというのがちょっと、こういう今回計画のパブリックコメントがあるんだなという皆さんが広報などを通して見たときに、これでもわかりづらいのかなという印象がちょっとあるんですが。","respondent":"藤田水とみどりの課長","answer":"１冊読むのはなかなか難しいということもありまして、今回はダイジェスト版というような形もつくりましたので、その辺をご覧いただきながらご理解をいただければなというふうに思います。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"これはやっぱり説明会に直接テストケースでこの資料などを提示しながら、計画の内容を一番やっぱり理解してもらって、計画の内容を理解してもらえればそれに対する意見というのは初めて出てくるわけですから、説明会への参加というのがかぎになるんじゃないかと思うんですけども、説明会に今環境とか景観に対しての関心が高くなっていると思うので。","respondent":"藤田水とみどりの課長","answer":"説明会等を含めて、いろんな形でのご案内の方法はあろうかと思います。その中で、今区の中で一番広くお知らせをする形というのが、やはり広報紙の活用だというふうに考えてあります。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望なんですが、例えば環境ですとかまちづくりですとか、景観とか、いろんな協議会なども各地であるわけですけど、そういった団体の方々にご案内するとか、そういった、これまで行政のほうでもつかんでいらっしゃる景観とかまちづくりにすごく関心のある方々への周知とかご案内なども、時にはしていただきたいなというふうに、要望ですけれども、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"阿部副委員長","kind":"質問","question":"例えば、景観計画というものが全国的にどういうふうになっていて、その中で品川が今なぜこの計画を策定するのかとか、これまでと何が変わるか、今やっているものがどうなるとか、そこに自分たちが積極的に参加するにはこんな方法があるよとか、何かちょっと区民の日常の意識とこの計画をつなぐための簡単な資料が１枚、この二つの資料に添えて出されると。","respondent":"藤田水とみどりの課長","answer":"そういう面で、１枚目のＡ４のペーパーの前文のところですが、区のほうでは平成１７年からさまざまなことに取り組んできたというようなことを前提に広報「しながわ」のほうでお知らせをしながらやっていくということで考えてあります。","id":"exchange-005"},{"speaker":"阿部副委員長","kind":"意見","question":"姿勢としてはいいと思うんですけど、取りまとめもそうなんですけど、まず説明するときの資料として、品川区でこういう流れですというだけじゃなくて、もう少し方向的にわかったほうが多分理解しやすいだろうなと思ったので言わせていただきました。ご理解いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"ルート的に品川区にもかぶるとか環境というか騒音の問題に関してはよくわかるんですが、こういう形でまちづくりの推進計画が出てきたということで報告事項に入ってきていると思うんですけれども、改めて伺いますが、羽田空港跡地まちづくりに対して、品川区は関係をどういうふうにしていくんでしょうか。","respondent":"山崎マスタープラン担当課長、片田防災まちづくり事業部長","answer":"今回その協議会のほうでメイン議題となっているものが沖合展開ですとか、そういったことによる跡地の活用でございまして、ここは大田区のほうの区域ということになりますので、品川区としましては。ただ、大田区のほうが、今課長のほうから説明しました第１ゾーン地区、大田区の市街地に一番近いところ、海老取川に面したエリアですけれども、そこの土地を取得するという考え方を示しております。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"そうですよね。まちづくりの進め方で、第１ゾーンは大田区だということで、大田区が取得するように動いているわけでしょう。だから、出してくれたんですけれども、直接この跡地のまちづくり推進計画に関しては、品川区はどういうふうにかかわっていくのかという質問をしたので、もっとストレートに報告はしましたけど、まちづくりに関しては品川区は積極的にやっていかないと、その辺ははっきりしてほしい。","respondent":"片田防災まちづくり事業部長","answer":"直接跡地に取り組むということは全くありませんけれども、ただ、今後の羽田の発展、羽田空港としてハブ化を含めて将来的には平成２５年ぐらいには、今の発着回数の１.５倍ぐらいの発着が見込まれると、年間を通して４５万７,０００回ですか、そういう中でアジア。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"部長、そんな難しいことじゃなくて、ハブ空港にまだなっていないけど、なるまちづくり推進委員会だと思うんだけど、そうじゃなくて、跡地まちづくり推進計画だから、この跡地に関しては品川区は関係ないんですよねと。関係ないという言い方は変か。じゃなくて、このできた跡地まちづくり、跡地に関して品川区はどういうふうにかかわり合っていくんですか、跡地に関してということです。","respondent":"片田防災まちづくり事業部長","answer":"跡地に対しては、今品川区はかかわる考えは持っていません。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"羽田空港移転問題協議会の件について伺いたいんですが、すみません、ちょっと説明が少しあったんですけど、いつから羽田空港移転問題協議会は開催されて、品川区ではだれが、どういう方が何人参加しておられたのか。その場で今回跡地利用はおやりになっていると言ったんですが、品川区はこの議題に対しては、どのような発言をしてきたのかお伺いします。","respondent":"山崎マスタープラン担当課長","answer":"羽田空港移転問題協議会の関係ですけれども、先ほども若干ご説明を申し上げましたけれども、発足は昭和５２年です。羽田空港移転問題協議会につきましては、羽田空港ができまして、一定程度航空需要が増してきた。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"騒音の問題と、あと飛行ルートがどう品川区に影響があるのかと、あと航空荷物が増えると思うんですけれども、それはどれぐらい増えて、車両の問題もどんな車が増えて、それがどういうふうに品川区の区域内を通って区民生活に影響があるのかとか、そういうのをちょっとお伺いしたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"シールド工事をしております中央環状品川線もその一つです。それから、一般道としての湾岸道路の国道３７５号線の東京トンネルの工事への着手というようなことで、そうした周辺アクセス道路の整備も進んでいるというような状況です。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"中央環状品川線が資料の１５ページにあるんですけど、今お話があったんですが、ハブ化、国際化における中央環状品川線を品川区はどう位置づけているのかというのをもう少しお伺いしたいなと思います。羽田空港移転問題協議会の中で、品川区はこの推進計画に対してどんな意見を出しているのかなというのを聞いているんですけど、紹介できるところがあれば教えていただきたいなと思います。","respondent":"片田防災まちづくり事業部長","answer":"それとあと、副区長の協議会での意見ということについてのご質問ですけれども、移転問題協議会が先日行われまして一連の説明がございましたけれども、特に私ども品川区のほうから意見は出しませんでした。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと中央環状品川線のほうはわからないけど、総量はかなり増えるというなかで、搬送する車両が中央環状品川線に流れてくるということは考えられると、そういうご説明だったのかなと思います。ちょっとあまり大がかりな計画なので、総事業費というのは幾らぐらいなのか教えてください。","respondent":"片田防災まちづくり事業部長","answer":"その事業計画についても、一般の、例えば第２ゾーンについては民間活用とか、いろいろ考えられているところですので、将来的にホテルとか、あるいはコンベンションセンターみたいなものが仮にできるにしても、総事業費として今私どものほうがお示しできるものではございませんし。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"ものづくりの施設も北品川五丁目の再開発について、国際都市ということでやっていこうということなんですが、そういう大きな施設がドーンとこの近くにできますと、品川区のそういった施設というはちょっと影響があるんじゃないかなと、何か閑古鳥が鳴いたりとかしないのかなと思うんですが、そこら辺の影響はどうなんでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"それは確かに私どものほうもいろんな観光面でのＰＲができないかというところについては、所管課のほうともいろいろ議論していますし、そういうところは明らかにしたり、またお示ししていきたいと、このように考えてあります。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問・要望","question":"そもそも論になってしまうんですけど、昭和５２年に羽田空港移転問題協議会が発足して、騒音の問題の関係で品川区が入った。でもって、今後の騒音等の問題に立ち会われるのであれば意義があるのかもしれないんですけど、ここに今の段階で品川区が入っていることについてお示しいただきたい。","respondent":"山崎マスタープラン担当課長、片田防災まちづくり事業部長","answer":"先ほどもご説明申し上げましたとおり、騒音等は今のところ大きな影響はないというふうに言われておりますけれども、羽田空港の近隣区の品川区といたしましては。補足になりますけれども、今後の羽田空港移転問題協議会としての対応ですけれども、基本的にやはり事業を進めるに当たっては、やはり共同の協議が必要だということを国のほうも示してございまして。","id":"exchange-015"},{"speaker":"渡部委員","kind":"意見","question":"でもって、実際品川区は一切かかわっていない。率直に聞きます。じゃあこれに参加しているから、例えば都有地である、国有地であるといったものの、第１ゾーンは大田区が何か利用するということなんですけど、この協議会に参加している品川区として、逆に意見を、区の中で例えばこういう施設が欲しいとかといった場合に言えるのか。その羽田空港移転問題協議会の中で言っていけるのか。","respondent":"片田防災まちづくり事業部長","answer":"おそらくいろんな、例えばＰＦＩとか、いろんな民間の活力を利用してまちづくりを推進することになると思われますが、そういう中で、私どものほうもいろんな情報を収集して、例えば、観光とか、共同施設というようなものを利用できる立場があるとすれば。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問","question":"最後の質問ですが、せっかくその羽田空港移転問題協議会に入っているわけですから、何らかのメリットというものがあるといいのかなというふうに感じます。区民に対して説明するにしても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"阿部副委員長","kind":"質問","question":"そういった説明は今後この２カ月でご説明を予定されているかどうかということを伺いたい。米軍の関係だったかと思いますけれども。そういうことを考えれば、たとえ公式な飛行ルートが区域の真上まで来なかったとしても、ある程度聞こえ方というのは影響があるであろうと思うんですけれども、そういったことを事前に何らかの形で説明をする予定はあるのかということをまず１点聞きたい。","respondent":"山崎マスタープラン担当課長","answer":"ホームページ等々を活用するなりしまして、今のところは影響なしですけれども、そうした内容も含めまして、周知という点で留意してまいりたいというふうに考えてあります。","id":"exchange-018"},{"speaker":"阿部副委員長","kind":"質問","question":"これはこれとして、品川として現在国際化を受けて何をしていくんだというのは、どこか影響部署でも何でも検討というのは何かされているんですかね。","respondent":"山崎マスタープラン担当課長","answer":"先ほども話がございましたけれども、観光面等々におきましては、大田区、それから大田区の観光協会、東京都等と連携を図りながら取り組みを検討しておりまして、予定が一定まとまったら区民委員会等々で今後報告予定というような形でそちらのほうは聞いてあります。","id":"exchange-019"},{"speaker":"阿部副委員長","kind":"質問","question":"これはどちらも、観光のほうも国際化プロジェクトチームも区民委員会ということでよろしいんでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"庁内におけるプロジェクトチームにつきましては、国際化というテーマで観光面によらずに、多角的な方面でプロジェクトチームを立ち上げているというのが一つです。それから、二つ目の観光面は、先ほどの大田区と連携をしながら、一定方向のまとめに至る手前まで来ていますよです。","id":"exchange-020"},{"speaker":"阿部副委員長","kind":"質問","question":"全庁的なプロジェクトチームのタイムスケジュールと、どういった段階で、どういう形でまとめが出てくるのかということを教えてください。","respondent":"山崎マスタープラン担当課長、藤田水とみどりの課長","answer":"企画セクションのほうで取りまとめているプロジェクトです。現在具体的なスケジュールにつきましては、大変申しわけないです。伺っておりませんというか、年度内に一定というようなところまでしか伺っておりません。私ども何で入っているのかというと、国際ターミナルができるということで、外国のお客様もぜひしながわ水族館のほうに来ていただきたいということで、到着ロビーのところに。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"これはどういうところのどういう制度のパブリックコメントで、発表の仕方とか、それはかかわっている自治体がどういうふうに調整するのかとか、その辺がわからないので、そこだけ教えてください。","respondent":"山崎マスタープラン担当課長","answer":"現在実施しておりますパブリックコメントにつきましては、国と東京都、大田区、品川区と同様のものです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"確認ですが、スタートは品川区のパブリックコメントの要望に基づいてやりますけども、これは東京都がやるパブリックコメントということなんですかね。普通窓口というのは、入口は各国や大田区や品川区でやると、そういうことでよろしいんでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"委員おっしゃられたとおりです。","id":"exchange-023"},{"speaker":"藤原委員","kind":"確認","question":"改めて確認をしますが、まずカッター部分が欠けちゃったということでいいんですよねということと、あとこの何枚かあるうちのカッターのある部分が欠けちゃっても、ある程度掘ってここまで来たわけですよね。やっぱり完璧な状態にカッターをしないとだめなんでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"ということもあって、この状態で１００ｍほど今回も補修予定の位置までは掘削するんですけれども、その後の残りの５kmという距離等々を勘案すると、今回そこにシールドマシンをとめまして、一定工事ヤードで、立坑で穴を掘りまして、それで前面を、一定程度地盤を整備して。","id":"exchange-024"},{"speaker":"藤原委員","kind":"確認","question":"ということは、ボーリング調査をしますよね。これはボーリング調査、掘って、シールドがある位置の確認とか、あとその後の地盤とかの調査をして、人が入れる立坑が掘れるかどうかの調査をしていくんですか。","respondent":"山崎マスタープラン担当課長、片田防災まちづくり事業部長","answer":"ボーリング調査につきましては、先ほど説明しました本格的なシールドマシンのビット、歯を交換する作業のための事前調査という位置づけです。ただ、一応目標としてはそれをいじらない部分で日程調整をして、ボーリングして立坑をつくって歯を取り替えるという作業になってくると思いますので、改めて明確なところがまた決まり次第、地域のほうにも説明しつつ。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"ボーリングして、そこを埋めていく。地域の方が不安にならないようにその辺の説明はちゃんとしていただきたいのと、それと調査をして修理をしてという負担がまだ特定できないということですけれども、今はシールドがとまっちゃっているわけですよね。それが、その分がイコール全体の工事の予定から、その期間が全部おくれちゃうというふうに考えてよろしいんでしょうか。","respondent":"片田防災まちづくり事業部長、岩田都市環境事業部長","answer":"今の前提ではおくれない方法で検討できないかということを考えております。ただ、場合によってはおくれるところについてはきちっと説明をしていきたいと思います。それらが全部完成するのが今のところ約束している日にちですから、シールド自体は押し始めれば非常に早いスピードで行ってしまいますから、シールドが到達してからまた数カ月全体が完成するまでかかりますので。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"今修復に６カ月ぐらいかかるんじゃないかというお話があったんですが、大体修復をいつぐらいに始める予定ですかね。費用なんですけど、およそでいいんですけど、大体こういうのは修復するのにどれぐらいかかるのかをお伺いしたいと思います。施工者負担ということだったんですが、首都高速道路株式会社ということなんですけれども、税金は１円も投入されないということでよろしいんでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"スケジュールですが、そうしたことが特定されて、スケジュールが判明してくるという関係です。ということで、現時点でははっきりしたスケジュールが明確じゃないです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"おおよそは何となく原因が、候補はあるんだろうけども、特定に至っていないということなのか、全然わからない状況ということなのか、ちょっとそこら辺を知りたいのと、あと同様のルート、東京都のシールドマシンもこれから通過するわけですけれども、そちらへの影響というのはどうなのか、それはどうなんでしょうか。","respondent":"山崎マスタープラン担当課長、岩田都市環境事業部長","answer":"基本問題につきましては慎重に対応しているということですけれども、東京都のほうのマシンについては、現在首都高のマシンが損傷した位置に到達しておりませんし、順調に動いているということですので。先端部分のビットの形状も、東京都は全く違う構造のものを使っているようですから、同じ位置を通ってきても、同じような形で損傷するということは今のところ考えられないと東京都は言っております。","id":"exchange-028"},{"speaker":"安藤委員","kind":"確認","question":"部長のご説明ですと、例えば固い岩盤がすごくあって、そこを通ったときに故障したんじゃないかというようなことを考えられるわけですけれども、そうしたことであるならば、また同様な地点を東京都のほうが後から通るとなると、また同様に故障してしまうんじゃないかというふうな心配もあるんですけれども、この１台目の首都高速道路株式会社のほうが今から原因を究明して修理をするわけですけども。","respondent":"山崎マスタープラン担当課長、原委員長、柏原住宅担当課長","answer":"実測の結果、現時点で東京都のマシンについては磨耗なく、今後約６kmの掘進に対して十分に安全であるということで。ほかに。ご発言がないようですので、本件を終了いたします。今回募集につきましては、区民住宅（あき家）入居予定者ということで、ファミーユ下神明、ファミーユ西五反田西館・東館。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"すみません、ちょっと根本的なところで申しわけないんですが、区民住宅の概要について伺いたいんですけれども、建設型ですね、今回。どんな収入階層の人が入れる住宅なんでしょうか。単身でも入れるんでしょうか。家賃は同様のグレードの民間住宅と比較して、どれぐらいの水準なんでしょうか、教えてください。","respondent":"柏原住宅担当課長","answer":"同様の近傍の、例えば６０平米とかというところのお家賃ですと、場所によっては１９万円から２０万円程度の家賃のところもありますので、そこと比較しますと、安いところでは１万円、それから広さも違いがありますけれども、５万円程度安い家賃を設定しています。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"２００９年度で４８人入って、全体の応募数は２２１人という、以降書いているんですけども、実際このうち建設型の実績というのはちょっとわからないので、ここ３年ぐらいの内訳などを教えていただきたい。","respondent":"柏原住宅担当課長","answer":"昨年度も２３件ということで、大体二十数件程度毎年この３住宅で、ファミーユ下神明と西五反田ですね、こちらのほうで入居されていると。残り半分程度が６月に募集しております借上型やそれ以外の建設型の住宅ということになっております。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"４８件入居しているうち２３件が建設型ということなんですが、平成２０年度と平成１９年度、あと平成１８年度、平成１７年度もわかれば教えていただきたいのと、あと民間に比べるとちょっと安いということで、なかなか確かにご家族の方が住めるようなところというのは非常に高くて大変だなということで相談を受けたことがあるんですけれども。","respondent":"柏原住宅担当課長","answer":"入居の件数です。先ほども申し上げましたとおり平成２０年度が２３件です。ただ、申しわけございません。平成１８年、平成１９年はちょっと手元に数字がございませんが、同様の数字で推移しております。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望なんですけども、広報が９月１日にあって、その日を含めた申込期間が１週間ぐらいしかないんですね。ちょっとお知らせしてから申し込みの間の時間がちょっと短過ぎるんじゃないかなと思うんですけど、それをもう少し改善することはできないでしょうか。ぜひお伺いしたいんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"松澤委員","kind":"質問","question":"簡単なことなんですけど、区民住宅のあき家入居予定者ということで、抽選日が１０月５日、抽選番号を１０月１日に発送するというんですけど、抽選の仕方、さっき課長がこうやっていたからガラガラでやるのかなと思うんですが、ちょっと抽選のやり方というのを教えてください。","respondent":"柏原住宅担当課長","answer":"それでやりまして、その番号で順番を決めるというふうなやり方でございまして、その当たった番号につきましては、１５日ごろまでにはご本人のところに発送するという流れになります。","id":"exchange-034"},{"speaker":"松澤委員","kind":"質問","question":"そのときに、当然応募した方は全員目の前ですよね、いるということでよろしいんでしょうか。","respondent":"柏原住宅担当課長","answer":"こちらの抽選なんですけど、抽選日、どこでやりますというのはご案内いたします。昼間の時間帯ですので、皆さんがいらっしゃるというのはなかなかちょっと難しい。","id":"exchange-035"},{"speaker":"松澤委員","kind":"質問","question":"私は何回応募しても当たらないのでという方がいらっしゃったものですから、こういうところで聞くのはどうかとは思ったんですけど。そうすると、応募した方には抽選番号をお知らせすると同時に、何月何日、どこそこの会場でやっていますから来てくださいというご案内はされているということでよろしいですね。","respondent":"柏原住宅担当課長","answer":"はい、おっしゃるとおりでございまして、いつ、どこでやっているというのはちゃんとご案内をしております。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"まちづくり事業の紹介というところですけれども、「ほか」と書いてあるので多分入っているんじゃないかと思うんですが、確認なんですが、耐震補強の支援企業の紹介ですとか、太陽光の発電、設置の助成ですとか、区営住宅ですとか、リフォーム助成とか、そういった事業の紹介というのは入っているのか。","respondent":"柏原住宅担当課長","answer":"こちらのほうは大崎のほうでやっておったんですけれども、聞いたところによりますと、飲食であるとか、それからイベントのブースの関係でどうやら制限があったらしくて、去年は大分規模を小さくしてやったということなんですが、平成２２年度につきましては。","id":"exchange-037"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"今の課長のご説明だと、たまたま会場の関係で同じになった。当然、でも来年度以降もこの形でずっと続けていくということでよろしいんでしょうか。確認が１点です。それから、内容としては、二つのもの、ちょうど足した内容になっているのか、新たにつけ加わったものとか、なくなったものとかがあるのかどうかということを教えていただきたい。とりあえずこの二つをお願いします。","respondent":"柏原住宅担当課長","answer":"こちらのほう、第１回としておりますが、一緒になったきっかけは若干そういうのがあるんですけれども、形としてはこういった形で続けていければと考えておりますが、何せちょっと初めてやる企画ですので。","id":"exchange-038"},{"speaker":"阿部副委員長","kind":"質問","question":"先ほどからちょっとご答弁を聞いていると、ちょっと盛り上げ方が、第１回ですからもう少し、こういうことで一緒になったら、こんなメリットがあって、こういうということもある程度はあったほうが、参加したり、中でやっている方も気持ちよくできると思うので、そこはどうでしょう。ちょっと一言お願いします。","respondent":"柏原住宅担当課長","answer":"ましてや、区の中の職員もハードとソフトの人たちがどうしても分かれがちですので、一緒にイベントをやることによって、お互いが認識し合えるところがありますので、そういったところが大きな目的だというふうに私どもは考えております。","id":"exchange-039"},{"speaker":"若林委員","kind":"確認","question":"これは当初予算では別々に予算をとられたということで、別に予算をもらっていたということを確認したいのと、１１日が雨天の場合は、ふくしまつりは中止ということになるのかどうか。その二つ。","respondent":"柏原住宅担当課長","answer":"ただ、今回やるに当たっては、共同といいますか、細かい話をしますと、ふくしまつりの予算をこちら側に執行委任していただく形で一緒に執行するという流れでやる予定です。それから雨天の場合です。","id":"exchange-040"},{"speaker":"若林委員","kind":"質問","question":"大崎駅はオープンな形だったので、すごく大規模という感覚を毎年持っていたんですが、中小企業センターでやると、そこら辺、実行委員長としてでしょうから、当然どういうことに、意気込みも含めてしたいのか。ネーミングは、そうすると何かふくしのおまつりをここで継続しているんですよというネーミングは何かなかったのかなという思いがあるんですが、それについての意見をお聞かせください。","respondent":"柏原住宅担当課長、齋藤道路公園課長","answer":"そういったところもありましたので、内部で検討したところ、事務局とそういったところも、みんなの、ハードもソフトも含めたみんなのフェスタだということで、こういった名前にさせていただいたというところです。特にお悩みなのは、ボランティアの方たち、支援者の方たちが大変高齢化していて、２日間はもたない、１日にしてくれというのが一つと、障害者福祉課で持っている予算は３０万円しかないので。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"防災上の観点から説明があったんですが、ちょっと区民の声なども含めて、もう一度ここに道をつくるという経過というんですかね、経緯というのをもう一度改めて教えていただきたいと思います。照明灯の完成イメージがあまり見えないんですが、そこら辺はわざとなのか教えてください。","respondent":"品川防災整備担当課長","answer":"経過についてご説明いたします。平成９年度になりますが、防災生活圏推進事業計画というものを策定しております。この中で、小山台一丁目、それから小山台二丁目の２カ所の入口整備を行うという計画がされました。","id":"exchange-042"},{"speaker":"安藤委員","kind":"意見","question":"井戸は近隣の方のボランティアの方が世話をされているということなので、ぜひ活用できる方向で、今保育園の方のご好意で利用していただいているんですけれども、できるような方向でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"阿部副委員長","kind":"質問","question":"一つだけ教えてください。暫定開放が８月で完成が２月で、半年ぐらいの違いであったら、２回に分けて工事するより、１回のほうがコスト的に安く済まないかなと思ったんですけれども、なぜ二段階で整備することになったのか理由を教えてください。コストの違いとか、もし計算されていたら教えてください。","respondent":"品川防災整備担当課長","answer":"８月の暫定開放については、過去の経緯がいろいろございまして、近隣住民の皆様の常時開放という声がかなり大きかった場所です。区としましても、近隣住民の皆様のご意向を最優先して、とにかく通れるということをまず優先して８月ということを決めました。","id":"exchange-044"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"この間、近日、東五反田二丁目第２地区再開発が竣工したと思うんですけれども、建設された住宅戸数というのは幾つで、どんな住宅が建設されたのか教えていただきたいのと、どうなっているのか、例えば最多価格帯は幾らぐらいで、最高価格と最低価格も教えていただきたいと思います。販売状況は、現時点でどうなっているのか教えてください。最後ですが、総事業費と最終的な補助金の投入額は幾らになるのか。","respondent":"三宅都市開発課長","answer":"すみません、ちょっとお答えするようなものを今持ち合わせていませんでして、一応資料としてお配りしておると思います。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"私のほうにだけということで、それはそれでいただきたいんですが、ご承知のようにかなりの税金が入っていて、区民の皆さんもかかわっている事業ですので、ぜひ委員会は竣工して、事業が完了したというならば、その他、報告事項でやってもいいのかなと思うような案件だと思いますので、ぜひ簡単でもいいですから、委員会報告としてお願いしたいんですけれども。重ねていかがでしょうか。","respondent":"岩田都市環境事業部長","answer":"行政が議会に対して行政として出す資料というのは、再開発事業の中身についての資料は幾らでもお出しできますが、先ほどご要望なさったのは、再開発組合から取得をした民間事業者が分譲する営利上のことですので、それは議員がご要望であれば。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"どんな形になるか知りませんけども、お願いしたいのと、あと販売状況に関しては、予算特別委員会などで既に区側も討議していただいているので、ぜひ前向きに検討していただきたいなというふうに思っていますけれども、何かそれが報告できなくなった理由とかがあるのか。私は報告していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118011?Template=document&Id=3986#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":37725,"voices":140}},{"id":"h22-20100824-9","meetingId":"h22-cm08","date":"2010年8月24日","dateIso":"2010-08-24","committee":"文教委員会","time":"午後１時０３分～午後４時１３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","topics":[{"id":"topic-01","title":"の平成２３年度入学予定者の取り扱い","agenda":"の平成２３年度入学予定者の取り扱い","exchanges":[{"speaker":"井上委員","kind":"質問","question":"今、説明があった中でお伺いしたいのは、品川小学校の入学の優先順位というところで、下線の特例を今回初めてとったというその理由と、あと無抽選というか、当然第１順位は無抽選かと思うんですが、これは仮定の話になるかと思いますが、その７０人をもし居住の方たちがいた場合には、当然クラス数の変更ということになると思うので、この第１。","respondent":"市川教育次長","answer":"そういうことも含めて対応します。それと３点目のご質問は、先ほど私、ちょっと説明の言葉が足りなかったのかもしれないんですが、ある小学校に、そこの小学校の区域内でもない、それからそこの中学校の区域内でもないお子さんがいることはままあります。","id":"exchange-001"},{"speaker":"井上委員","kind":"確認","question":"確認です。ここだけに限らず、住宅状況というのが大変今、品川区ではいろいろな状況があるかと思いますので、そういうまちづくり等も関連した中で、その時期時期に応じて対応されていくという考え方なのかが１つ。そうすると、そこに入学した人たちが第１順位なものですから、必ずそういうふうに入学ができるということなんでしょうか。わかりますか。","respondent":"市川教育次長","answer":"それから２点目は、ひょっとすると私の説明が混乱させたのかもしれないんですけれども、品川小学校に入学できる子どもというのは、今のルールでいきますと、この品川・大崎ブロックのところでならば選べることになっています。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成２２年度にこの通学区域内希望者に対して抽選を実施するといった意味では、小・中学校で抽選になった学校がそれぞれどれだけあったのかというのを教えていただきたいのと、あと２点目のところでは、学級数を見ると、平成２２年度と平成２３年度と、増えているところと若干減っているところがあるんですが、その辺をどういう考えで増やして、どういう考えで減らしていったのか。","respondent":"市川教育次長","answer":"この理由は、特別支援学級の通級学級を新たに開設した関係で、教師数が対応できないということで、受入可能数としては学級数を１つ減らしたという、こういった施設上の理由がほとんどです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"最後のところなんですけれども、毎年いろいろなことを勘案しながら学級数とか人数が変わってきているということなんですけれども、ちょっとその辺、基準があるのかなと思ってお伺いしたので、その辺１点。","respondent":"市川教育次長","answer":"ただこれは気持ちがそうでも、先ほど来申し上げているように、施設のキャパシティーというものがありますので、そこの見合いの中で気持ちの行ったり来たりとか、それから施設をどのように転用、活用していくのかということの調整がついているうちはいいんですけれども。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"安全確実な線というのは、やはりそうですよね。そういった面では確実なところを、なるべくわかりやすくしていただきたいなと思いますので、それが１つと、あと２点目のところで、品川小学校のところの第４順位のところで区内全域と書いてあるんですけれども、それはほかの小中一貫校も区内全域だったんですか。ちょっとそこがはっきりしなかったのでお願いします。","respondent":"市川教育次長","answer":"この意味は、基本的には各ブロックに１校ずつということで今、開設を進めておりますので、バランスよく配置ができたときには、この第４順位をどうするかということは検討することになろうかと思いますけれども、まだその意味では配置計画の途上であるということで。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"第４順位の小学校の区内全域で希望ができるというあたりの問題点というのをぜひつかんでいただきたいなと、これは１点で終わりますけれども、あとまた３５人、今回のこの可能人数を決めることでは、選択制と矛盾するものではないといったことでしたけれども、私は本来、選択制というのならば、どこを選んでも入れる、どこの学校でもゆとりのあるというのが当然であるけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"無制限に増やしてほしいと思っているわけでもないし、本来通学区域内、本来の指定校を選んでほしい、それが中心であるんだったら、各学校をバランスよく本来なるはずじゃないじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"若干それに近いような状況になってきたかなという雰囲気はあるんですが、でもそこがどうしてこういう動きがあるのかというのは、もちろん立地条件等々いろいろな問題もあるんでしょうけれども、そういう動きがあるのはどういう理由なのかなというところは少し分析がなされていると思うんですが、どういう見解のもとでどこまで分析されているんでしょうか。３つ目は、文部科学省で３０人学級でしょうか。","respondent":"市川教育次長、若月教育長","answer":"それと少人数学級の動向についてのご質問ですけれども、仮に国の制度が変わった場合でも、これまで５０人学級が４５人学級になって、あるいは４５人学級が４０人学級になったときも、一定の年数。１つだけ補足をさせてください。選択制についてなんですが、これついてはどうも皆さん方、なかなかご理解いただけないんですけれども、結論から申し上げますと、選択制をやめたり、あるいは変更する意志は全くありません。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほどの人数の変更、平成２２年度、平成２３年度の変更の分、よくわかりました。そういう状況に合わせていろいろ工夫されているということがわかりました。そういう意味で、学校選択制の意味合いというのをどういうふうに積み上げていっているんですかということだと思うんですね。ですから、自分たちが何のためにやっているのかという原点に立ち戻ることも必要なんじゃないかなと思います。","respondent":"若月教育長","answer":"まだ多くの校長はその辺がまだまだ強くきちんと学校のポリシーとして物を伝えるということができないわけですね。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"その第２順位で言うと。そうすると、８０人のキャパシティーしかないところに、そのお子さんたちが１１０人いるとすれば、その３０人のお子さんたちは抽選になってしまうということは、本来の公教育のケースとしてはいかがなものかと思うんですけれども、そのことについてそういうふうになった場合にどうなるんでしょうか。","respondent":"市川教育次長","answer":"第２順位のほうは、城南中学校の通学区域内の小学校の在籍者で、城南中学校の区域外の子どもたちという意味ですので、今、委員がご心配になっている該当者については、第１順位のほうの城南中学校の通学区域内居住者というほうで読み取れることになります。","id":"exchange-010"}]},{"id":"topic-02","title":"の平成２３年度使用教科書採択結果一覧（小・中学校・特別支援学級用）","agenda":"の平成２３年度使用教科書採択結果一覧（小・中学校・特別支援学級用）","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"今回の採択された教科書が載っているんですが、会社名で前回のと変更があるところがあったら教えていただきたいのと、採択への流れ、手順をご説明いただいたんですけれども、教育委員会のところにおいての主だったご意見とか、何かあったら聞かせていただきたいということと、あと教科書の本の展示なんですけれども、今回、品川図書館１カ所でしたよね。","respondent":"冠木指導課長","answer":"要は文部科学省が決めている学習指導要領、もちろんこれは踏まえてありますけれども、それを踏まえつつ、私どもが小中一貫教育要領というのをつくって、それに基づいて教育を実施しておりますので、その小中一貫教育を進めていく上で十分な内容であったり、あるいは例えば５年生。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"品川区は検定にかかった教科書以外に、副教科書とか副読本とか多数出ていますよね。その辺は基準とか、どこで選ぶとか、その辺を含めて教えていただけたらと思います。","respondent":"冠木指導課長","answer":"品川区がつくっております教科書等々につきましては、学習指導要領がありまして、私どもの進めている小中一貫教育要領がありまして、その差の部分。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"その作成のところなんですけれども、毎年使ってみてどうかといったところでの見直しというか、検討というのはどういうところでされているのか、最後にお伺いします。","respondent":"冠木指導課長、和氣小中一貫教育担当課長","answer":"今回、国の学習指導要領も変わりましたけれども、私どもの小中一貫教育要領についても、その新しい学習指導要領が品川区に追いついてくる形で変わってきたものですから、その部分で小中一貫教育要領も十分に検討して。日々検討しながら、子どもたちによりよいものをつくっているです。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"１つだけお願いします。採択の中身についてはよくわかりました。例えば国語であれば５社から選んだということなんですが、５社の前に何カ所かあるのですか。その中から、たくさんの中から５つを選ぶという段階があるのか、それとも教科によって大分、７社であったり３社であったりという、そこの選定の中身を教えてください。","respondent":"冠木指導課長","answer":"国語について今、５社とご案内いたしましたのは、文部科学省の検定を通った教科書が５社ですので、その５社の中から私どもが十分に検討いたしまして、教育委員会で採択をいただいたところです。","id":"exchange-014"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"北品川児童センターですよね。あそこは北品川保育園もありますよね。そこの安全性、影響はどうなっているのでしょうか。","respondent":"安井子育て支援課長","answer":"基本的に１階、２階が保育園なんですけれども、こちらは児童センターに上がるのは外階段みたいな形になっておりまして、保育園の中には階段が中に設置されておりますので、基本的には影響がないよう、工事を進めていきます。","id":"exchange-015"},{"speaker":"西本委員","kind":"意見","question":"北品川保育園に来られる方は自転車が多いんですね。なので、工事車両が入ってきたりすると、結構朝晩の出入り、工事とは重ならないかもしれないんですけれども、ちょっと危険かなとも思うので、そこはちょっと現場の方とか、園の中での工夫とかをしていただければなと思います。","respondent":"吉岡保育課長","answer":"工事に関しましては、今、委員からお話がありましたことを踏まえまして、十分に安全は園のほうでも確保してまいりたいと思いますので、その辺十分調整してまいります。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"小中一貫校の校庭のことなんですけれども、お伺いしたいのは、総務委員会のところで、品川地区の小中一貫校のところの校庭が、小学校と中学校合わせて、一貫校になることによって若干というか、小さくなる、狭くなるということで、隣地を含めて広くなるという話を伺ったんですけれども、その辺で校庭の基準というものがあるのかどうか、ちょっとその辺と。","respondent":"田村庶務課長","answer":"実際に平成２３年４月、品川学園がもうオープンですし、それまでは仮設として城南中学校が使っているわけですから、やはり予算編成あるいは引き続き具体的な売買にあたっての協議は進めておりますが、ちょっと竣工にはここで方針が出ないということですけれども。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/976656?Template=document&Id=4708#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":28551,"voices":67}},{"id":"h22-20100824-5","meetingId":"h22-cm08","date":"2010年8月24日","dateIso":"2010-08-24","committee":"総務委員会","time":"午後１時０２分～午後２時３８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに(1)、平成２２年度都区財政調整交付金当初算定の結果","agenda":"はじめに(1)、平成２２年度都区財政調整交付金当初算定の結果","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"１ページ目の基準財政需要額の説明では、特別区が等しく行うべき事務を遂行することができる云々となっておりますけれども、実際に、基準財政需要額のところでは、経常的経費と投資的経費と二つになっているんですけれども、経常的経費のほうは１ページ目の説明で大体「ああ、そうかな」というふうになるんですけれども、投資的経費のほうの考え方というのは。","respondent":"金子企画財政課長","answer":"投資的経費についてのお尋ねですけれども、これは第二のところに掲げてあるとおり、こちらも各区が等しく行うべき事務を遂行することができるように、そういうような考え方で算定されているものです。具体的に申し上げますと、区はさまざまな施設を持ってあります。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"投資的経費、２３区で比較するとちょっとばらつきが出てくるような感じがするんです。そうすると、今の説明ですと、例えば大田区と比べて品川区はそういう施設がおくれているとかという事情を反映して算定しているわけじゃないということですか。","respondent":"金子企画財政課長","answer":"これは三つほど補正の種類がありまして、そこで各区の特殊事情を一定程度平準化する形で、各区が同じ行政レベルに達するような形に補正するというような計算の仕組みを後で加えるというふうになっておりますので、そういう意味では。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"標準的なものと、実際のところでいわゆる態容補正というんですか、そういう補正をやるんだというご説明なんですが、例えば今の説明で、私が一番よくわからないのは、政策的な各区でやっているものがどういうふうに反映しているのか。今も計算式がいろいろあるんだというお話なんですけれども、そこのところはどうですか。何回聞いてもよくわからないところなんですけれども。","respondent":"金子企画財政課長","answer":"これは災害時等々の緊急に発生したものに使うというのがまず第一でありまして、そのほかに各区の政策的な違いの部分がある程度反映される部分があるんですけれども、こういったところにおきまして、一定程度の差が出てくるということは当然ありますが、この普通交付金の場合には。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、普通交付金のところでいけば各区が等しく行うということになると、その区が、とりわけほかの区と比べて突出しているということがあって、逆にそれで上乗せになっているということではないということなんでしょうか。この２点、お願いします。","respondent":"金子企画財政課長","answer":"１点目ですけれども、先ほど申しましたのは基本的なところの考え方で、そういう意味では、同じレベルに持っていくということなんですけれども、それは各区の地理的、歴史的条件によっても違う部分が当然あるので、そういう意味での政策的な出っ張り。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"意見","question":"まだまだ腹に落ちない部分がいっぱいあるんですけれども、そうすると、基準財政需要額を決めていく、その中で経常的経費と投資的経費があるんだけれども、基本的には２３区等しく行うということをやりながらも、政策的なところも反映して決めていくという仕組みになっているということだけれども、そうすると、政策的な経費のところをだれがどういうふうに主張しているのかということと。","respondent":"金子企画財政課長","answer":"これについて最終的に２３区の段階でまとめて、統一的な要求にするわけですが、その過程は先ほど申し上げたとおりで、各区段階、ブロック段階、そして２３区に持ち上げて、この計算式では当てはまらないところの要求についてまとめて。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"今回、投資的経費のことは、全体の額としても大分落ちているんですよね。前年度比約３６％減となっています。そういうことになると、例えば再開発なんかでも、予定どおりやれるかどうかということにも当然影響してくるのかなと思うんですけれども、そこら辺の、現在の当初算定のところで行きますと、再開発の部分で行くとどういう見通しになるのかということを最後に伺います。","respondent":"金子企画財政課長","answer":"その結果としまして、平成２２年度は、公共施設の改築工事費の年度事業量と道路改良費といったものを圧縮するということをしております。したがいまして、各区ともこの部分については計算上減額されることになっています。","id":"exchange-006"},{"speaker":"土井委員","kind":"質問・要望","question":"これで一定程度方向が見えてきつつあるものもあるということなので、今回の財調の具体的な額は、この２月のレベルの基準に従ってやったということで、今、まさにその部分がこれから議論をされていって、来年度に決まっていくということになるんですけれども、今、都区財調とのかかわりについては、どの程度、どういう形の議論があるのかなというのを、直接すぐではありませんけれども、聞かせていただきたい。","respondent":"日下部企画部長","answer":"今の土井委員のご指摘、都区のあり方の検討と財調の関係だと思います。","id":"exchange-007"},{"speaker":"土井委員","kind":"質問・要望","question":"当然のことながら、５５％に決めてきた経緯がまさしくそうであったわけで、これからそれも含めた議論になってくるんだろうと思いますので、そういう中にまた参加をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"林委員","kind":"質問","question":"１ページ目の１行目に、「平成２２年度における都と特別区及び特別区相互間の財政調整については」と書かれているんだけど、この最後の部分の「特別区相互間の財政調整」、今、土井委員からも出たけれども、これについては話し合いがきちんとついているんですか。２３区間で財政調整についての話はやってきたのかどうか。","respondent":"金子企画財政課長","answer":"毎年さまざまな項目において協議がされているわけですけれども、東京都と特別区との間で最終的な協議がされますが、その前に特別区の段階での意志一致というものを図らなければなりませんので、そういう意味では、それが今の計算方法なんですけれども、それをどう変えていくか。","id":"exchange-009"},{"speaker":"林委員","kind":"質問","question":"当然、毎年行われているというのはあるんだけど、想像するのに、例えば渋谷区と港区が不交付になる。この２区は、当然不交付になりたいとは思っていないだろうと想像するんです。渋谷区にしろ、港区にしろ、不交付になったのは許し難い事実だけど仕方がないかというふてくされた態度で合意になったというふうに想像するんだけど、その辺、部長はいわゆる２３区間の話し合いの会議には出ているわけですか。","respondent":"日下部企画部長","answer":"今回の、今、ご指摘のありました渋谷区と港区の問題というのは、いわば２月８日に都と区、それから言うまでもありませんが２３区間で合意した基本的な財政調整の方針、これに基づいて、簡単に言えば要するに、計算するわけです。","id":"exchange-010"},{"speaker":"林委員","kind":"質問","question":"今の段階で文句が言えないのではなくて、どうせ区長はわかっていない上で仕方ないなという話になる。その手前のところで詰めをしていくわけでしょう。そうすると、この話を進めていくのに、そういう要素というのは入ってこないんですか。都と区でやっているわけだから、政府なんていたってしようがないというふうに、感情的にも、理論的にもそういうことが議題にも上らないんですか。","respondent":"日下部企画部長","answer":"財政調整については、これは言うまでもございませんけれども、全国の中で唯一の大都市制度という特殊性が非常にありますので、ある意味で私ども、財政調整について議論をするときは、当然地方交付税に準拠した仕組みですから。","id":"exchange-011"},{"speaker":"林委員","kind":"意見","question":"これからいろいろな話し合いが進む中で、財調のことをわかっていない都議会にものを頼みに行くとえらいことになるということも私たちは考えている。そうすると、皆さん方の中でも、一番危なく考えるのは、都庁と行政に２３区側が翻弄されてしまうような、それには十分注意しながら、都区の協議会に臨んでいってほしいなと思うので、お願いをしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"堺委員","kind":"質問・要望","question":"先ほど冒頭でご説明いただいたんですが、確認でご説明いただきたいんですが、市町村民税法人分、これは前年度に比較して２２.６％、金額にして１,４５６億６,４５７万２,０００円マイナスとなっているわけですが、その辺の理由ですね。これまた、次回の段階で新たに積み上げて交付されるという説明だったかなと思うんですが、それも確認させていただきたいと思います。","respondent":"金子企画財政課長","answer":"Ａのところと一番下の約８,６７８億円というものの差は、ご指摘のとおり１０３億円余ありますけれども、これは東京都の最終補正予算、ここで最終的に固定資産税、市町村民税法人分の額が決まってまいりますので、そこのときに東京都と区との協議で取り扱いが決まってくるです。","id":"exchange-013"},{"speaker":"堺委員","kind":"質問","question":"約束されているというのは、先ほどの特別区相互間の課税調整みたいなもので約束されているのと、都と区との間で約束されているんだと。その両方の約束ですか。","respondent":"金子企画財政課長","answer":"確かに昨年は一気に交付金総額が落ち込んで、平成２２年度についても大きく落ち込むだろうという見込みが立っていまして、東京都と区が協議する中でどの辺を押さえるかという話が出てきました。","id":"exchange-014"},{"speaker":"堺委員","kind":"質問","question":"そうすると、その分だけ、当初各区それぞれの特色というのもあるんでしょうけれども、品川区は品川区としてそれに沿う形で、当初はここまでやろうと思っていたんだけれども、財源という点で言うと、ここまでにせざるを得ないなというような考え方にならざるを得ないのかなと思いますが、そういう意味でも、事業のおくれというのは当然出てくるような気もするんだけど、その辺はどうなのかということと。","respondent":"金子企画財政課長","answer":"もう一つは、１０３億円余の差額ですが、正確に言いますと、先ほどもちょっと申し上げましたけれども、固定資産税と市町村民税法人分は今の段階での見込みであります。東京都の最終補正の段階で、さらに現実に合った見込み、変わる場合には当然その見込みに修正が入ります。","id":"exchange-015"},{"speaker":"須貝委員","kind":"意見","question":"その辺のシミュレーションを描いているのかどうか。そうすると、ここで圧縮されるというのはちょっと合点がいかないんですが、逆に交付金の配分率を、特例になるかどうかわからないですが、逆に２３区の配分率を上げていくという方向にもっていかないと、将来的に、財源的に、品川区も２３区もみんな困ると思うんですが、その辺についてちょっとご見解をお聞かせください。","respondent":"金子企画財政課長","answer":"先々の話ですが、そういう意味では、先ほど企画部長が申し上げましたとおり、事務の配分に伴って条例の定める割合５５％というのも変わってくるというのが前提ですので、これは都区のあり方の検討の進展にあわせて、区としても対応を考えるというふうになるだろうと思っています。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"先々、交付金の総額、算定の総額を見ると非常に心配されますので、区のほうとしてもさまざまに努力はされていると思いますが、ある意味かなり大変な状況、危険な状況になった場合には、都のほうにお願いして、事業の配分というのは置いといて、逆に直接都民サービスをしているところに緊急に、一時的にでも配分率を上げていただくようなお願いをされてもいいんじゃないかと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-02","title":"ＣＳＲ講演会と事例発表","agenda":"ＣＳＲ講演会と事例発表","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"これはわかるかどうか、わかったら教えてほしいと思うんですけれども、１００歳以上の行方不明の件が大分問題になっているんですが、品川区ではそういう方はいなかったということなんですけれども、どうも調査の仕方が、各自治体で工夫してやっているのかなと思うんですけれども、品川区の場合どういう調査の仕方をやっていったのかなというのを教えていただければと思います。","respondent":"中川原広報広聴課長","answer":"私のほうでプレス対応させていただいた段階の状況ですが、８月１０日現在、１２０名の１００歳以上の高齢者がいらっしゃるということで、その方たちにつきまして、マスコミ等から問い合わせがございましたので、所管の部門と相談しまして現状を確認いたしました。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"確認","question":"１００歳の件にあわせて、今、特に暑くて熱中症で亡くなる方がいることも問題になっていて、実際に顔を見るとか、そういう確認が非常に重要になっているなと思っているものですから、できたら区で持っている情報での突き合わせだけではなくて、実際に暮らしぶりを見に行くことができればなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/653420?Template=document&Id=1862#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":27677,"voices":59}},{"id":"h22-20100825-14","meetingId":"h22-cm08","date":"2010年8月25日","dateIso":"2010-08-25","committee":"行財政改革特別委員会","time":"午後１時０２分～午後６時１１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","topics":[{"id":"topic-01","title":"を行います。 旧第一日野小学校跡地の活用","agenda":"を行います。 旧第一日野小学校跡地の活用","exchanges":[{"speaker":"石田委員","kind":"質問","question":"どのくらいの期間で契約をしたのか、何年契約でやられているのか。それとその契約のやり方ですね、例えば１年契約で毎年更新をしていくのか、それとも複数年契約でやられたのかというのが１点。実際に年間で契約した場合は金額が幾らかというのが、わかったら教えてください。","respondent":"久保田行財政改革担当課長","answer":"その中で契約期間が決まりましたら、契約書上はそういう形で契約を結んでいきたいという予定です。暫定ですから、その後本格活用等もありますので、その時期等も決まりましたら、その辺は調整をしていきたいという予定です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"契約料が幾らなのかというのは大事な問題だと思うので、それがブラックボックスになっているというのは、ちょっと承認しがたいところがあると私は考えております。今回の貸付の目的、改めて暫定活用の目的なんですけれども、これは何なのかということを改めてお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"駐車場として貸し出す目的ですけれども、当初の予定では、建て替えに伴いまして代替の駐車場として使わせてもらいたいということでございましたが、建て替え計画のほうの時期は、今、経済情勢等を見きわめているということもございまして、それまでの間、実際のところ。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"その本活用の期間を教えてください。校舎の部分ですけれども、今回はネットを引いて入らないようにするということで、そのまま置いておくわけですけれども、区民要望などがあれば、例えば改修などをして暫定的に活用することは可能なんでしょうか。その校舎のほうの扱いですが、本活用の際はどのようになるのか、そこら辺も合わせてお伺いします。","respondent":"久保田行財政改革担当課長","answer":"それと本活用のときに校舎はどうなるかですが、これも平成１７年にＴＯＣからは代替駐車場として活用したいということでございましたので、その場合には一定程度の台数の車をとめなければなりませんので。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"一民間企業の建て替えに小学校の土地を貸し出すというのはちょっと異例なケースだと思うんですけれども、今回ＴＯＣに貸し出す上で、区が地域経済の活性化に貢献しているんだというご説明が何度かあったと思うんですが、具体的には地域経済の活性化に貢献するというのはどういうことなのか、具体的にもう少し教えていただきたいのと、今回のように、これから民間企業から貸し付けの申し出があった場合。","respondent":"久保田行財政改革担当課長","answer":"特に五反田地区につきましては、昼間人口がかなり高く夜間人口が少ないということもありますので、地元の商店や経済に関しましては、やはり外部から来る方が消費とか経済の大きな役割を担っていると認識してございまして。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"今ちょっと経済状態もいろいろ動いておりますし、切実な区民要望との関係でいいますと、土地がないということが理由で、例えば特養などでは増設などがお預けにされているような状況もあります。どうでしょうか。","respondent":"久保田行財政改革担当課長","answer":"委員がおっしゃるように可能性として契約をしないということであれば、別契約になりますので、その可能性はあるとは思いますけれども、私どもとしましては、平成１７年から話を進めてまいりまして、ＴＯＣといたしましても建て替えについて強い意向を持っておりますので。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"先ほど賃貸料など今後詰めていくというところで、第三者の鑑定する方たちも入れてということですが、これはどういう方たちで進めていこうとしているのかということ。例えば旧第一日野幼稚園であれば、すこやか園ができましたけれども、このエリアでは待機児が多いということを考えれば、暫定的にでもそういった対応をするとか、もっと広い視野で検討があってもいいと思うんですが、２点お伺いします。","respondent":"久保田行財政改革担当課長","answer":"２点目の校舎の活用ですけれども、私どもとしましては、先ほどもご説明いたしましたように、ＴＯＣの本格活用の際には校舎のほうも解体いたしまして全面的に活用するですので、それまでの期間、暫定的な貸し出しではありますけれども、将来的に校舎の解体も予定している中では。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"新しい施設があることはわかりますけれども、施設として新しく建て替えろとか費用をかけてどうこうせよということではなくて、子どもの施設として旧第一日野幼稚園がここにあるわけですから、今本当に大変な待機児対策というところで活用できるものであれば、ちゃんと横の連携をとって検討していく余地はあるのではないかということをぜひ検討していただきたいという、意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/677130?Template=document&Id=5890#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":8979,"voices":25}},{"id":"h22-20100826-15","meetingId":"h22-cm08","date":"2010年8月26日","dateIso":"2010-08-26","committee":"環境対策特別委員会","time":"午後１時０３分～午後３時２５分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","topics":[{"id":"topic-01","title":"地球温暖化対策に関することとして、区民への普及啓発","agenda":"地球温暖化対策に関することとして、区民への普及啓発","exchanges":[{"speaker":"川西委員","kind":"質問","question":"大変立派な資料をつくっていただいて、感激しております。１つは、資料３の学校関係の資料について、校長会が先生たちにお話をされて段取りを決めたんだと思うんですけれども、学校関係のこれに対する反響はどうなのかということが１つ目。それから２つ目の質問は、資料２－３の環境学習講座についてですが、この企画というのはどこでやっていらっしゃるのですか。","respondent":"工藤環境課長","answer":"１点目の学校ＩＳＯ、家庭ＩＳＯにつきまして、学校に対する協力依頼はどのような形でやっているかということと、その反応、反響ですけれど、学校ＩＳＯは、私どもも校長会の中で毎年この取り組みをＰＲして、実施しています。","id":"exchange-001"},{"speaker":"川西委員","kind":"質問","question":"わかりました。この講座の中で、寄せ植えとかの企画がありますけれども、そのもとになる土づくり、自然の堆肥づくり、こういうものを取り上げるように、どこかで言っていただけるのか、私がいずれ、来年でも会員になったらそこで言うのかと思っていますが、お答えはいいですから申し上げておきます。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどの説明でも、これで全部というわけではないでしょうけれど、上のメニューはそろってきて、いろいろ実践や行動が進められてきたわけですよね。それを通じて発見したこと、当初掲げた目標や目的に対してどこまで到達しているのか、その状況、今後の課題や解決していくべき問題、そのことをどんなふうにお考えになっていらっしゃるのかご説明願います。","respondent":"工藤環境課長","answer":"環境情報活動センター自体は、情報の発信と活動の拠点と位置づけまして、最新の資料、新聞の記事、環境関連の資料は置いておりますけれど、現在、環境情報は様々なものがでておりますので、その辺で情報センターとしての機能を高めるためには、その情報を整理しまして。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"それによって課題や問題がまた見えてくるのかなと思ったんですね。打ち水大作戦も一生懸命やられているとは思うんですけれど、その思いを一過性のイベントにするだけでなく、そこに込められた意味をはっきりさせることが必要なのかなと思うんですけれど、地域ぐるみの取り組みに発展させていくという方向性については、どんなふうにお考えになっていらっしゃるのか伺いたいと思います。","respondent":"工藤環境課長","answer":"やり方としてはいろいろな角度からやっていくというのが、地道な活動ですけれど必要であると考えていますので、私どもとしましてはさまざまなメニューを提供しながら、また他の自治体がやっている部分等も勉強、研究しながら。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"環境啓発・学習のためにいろいろな自治体でＤＶＤなどを作成しながら、区の計画だったり、一人一人ができる取り組みだったり、そもそも地球環境は今こういう危機的な状況にあるといういろいろな問題点も含めたＤＶＤなどを作成して、町会で取り組んでもらう、マンションで取り組んでもらう、地域全体で取り組んでもらう、いろいろな活用の見本を提示しながら地域での取り組みをつくっていく。","respondent":"工藤環境課長、藤田水とみどりの課長","answer":"東京２３区と市区町村が一体となって、そういった双方向で啓発するような仕組みを検討しておりまして、環境を促進しようという参加型のホームページづくりを進めておりますので、そういったものができましたら区としても紹介したり。今年度の環境対策ということで、道路公園課では駐車場の遮熱性の塗装を行うことを広くご案内する形で対応してきているところです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"今後の方向性について、区民と区と、また区民同士のいわばキャッチボールができるみたいなお話がありましたけれど、一般家庭に広げたいという話もありましたけれど、一人一人の取り組みを紹介して、また広げていく、それもすごく大事だと思うんですけれども、あわせてそれを地域ぐるみに発展させていく方向性を、例えばうちの町会では今年１年間でこういうことをやっていこうじゃないかと。","respondent":"工藤環境課長、藤田水とみどりの課長、三宅都市開発課長","answer":"商店街でやっていますドライミスト等、これもまた温暖化に対する特徴的な取り組みですけれども。しかしながら区としてもう少し積極性を出そうということで、当面建て替え予定がないようなところでも、強度的に問題がないという場所もありますので。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"確認","question":"何点か確認させてほしいんですけれど、まず意見ですけれど、環境対策全般については、品川区の場合３５万人の区民全員に対するものですから、それを全部品川区でやるような話がさっきありましたけれど、それはできないと思いますし、費用対効果という部分に対応しながら、例えば仕組みづくりとか施策とか、そういうことを通して区民の支援、啓発を進めていくことが品川区の役割と思っていますので。","respondent":"工藤環境課長","answer":"推進会議の位置づけですけれども、先ほどお話しましたように、環境保全の取り組みを区民、事業者等の社会を構成するすべての人々と協調して進めるという理念のもとに設立されたものです。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"推進会議の位置づけというお話をいただきましたけれど、何が聞きたいかというと、これから品川区のいろいろな政策を具体化していくに当たって、どこがメーンとなっているのかということ。だからその品川区の推進のメーンとなるのがこの環境活動推進会議であるとするならば、この構成とか内容はもう少し検討したほうがいいんじゃないでしょうかということなんです。いかがでしょうか。","respondent":"工藤環境課長","answer":"しかしながらこれを起点としまして、この会議体で品川区全域すべての環境施策を広げるということは難しいかもしれませんけれど、３４名の委員の方は、環境に関する高い志を持って、それぞれのバックボーンの中で、環境の専門家の方もかなりいらっしゃいます。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうしたら余計に、もちろん今の話はわかるんですけれど、今のお話で確認できたのは、これを母体に品川区の具体的な環境対策を推進していくというのであるならば、例えば区内の大学の教授であるとか、事業者も東京ガスだけでは当然いけないわけです、いろいろな業界があるわけで。次に行きます。そこまでやってあげると、子どもたちも学校もよりやる気になると思うんですが、いかがでしょうか。","respondent":"工藤環境課長","answer":"学校ごとに毎年の電気料の比較をしたり、毎月の比較、翌月との比較、前年度同月との比較等は、データで示していない面がありますので、そういった部分ができるような形で、今検討しています。","id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問","question":"具体的に目に見えた形のほうが当然いいわけですから、それはぜひ今言ったシステムを活用していただいて、毎月は大変でしょうから１年間で区切った中で、１年間頑張った結果こうなりましたということを学校にフィードバックしてあげると非常に喜ぶと思いますので、それはぜひ検討してくださいということをお願いしておきます。当然、子どもたちにお願いする目的は続けてもらいたいわけですよね。いかがですか。","respondent":"工藤環境課長","answer":"ホームページに関しましては、このようなチェックシートをホームページにアップするということは、区民の方が必要な情報を取れるという部分では重要だと考えていますので、そういった部分は早急に検討してまいりたいと考えています。","id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問・要望","question":"目的としては、小学校の子どもたちがこれを通して環境施策に触れて、その子どもがずっと成長していくに伴って環境に対する意識も持っていっていただきたい、そのきっかけづくりとしてこれをやるわけでしょうから、だったらそれを行政が、しかも今あるホームページにつなげていくことができれば、コストも安く、意識も啓蒙して、結果として毎月自分の省エネ活動が現に目に見えるという形でわかるのだから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"端的に伺います。今３４人の委員がいるということですけれども、意見の集約には若干人数が足りないというようなことを伺ったんですが、今後必要に応じて、内容ありきで人数を選んでいくのか、それとも器ありきでこの人数を選んでいるのか、はたまた要綱には公募の人数が書いてあるのか、そのことをお聞きします。","respondent":"工藤環境課長","answer":"やり方としてはいろいろとあろうかと思いますけれど、会議体の委員の数につきましては、応募状況や今後取り組む課題等によって、また検討していきたいと考えています。","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問・要望","question":"それと、資料４のパンフレットは、先ほど川西委員がおっしゃったとおり非常にわかりやすくできているんですが、最後の面を見ていただきたいんですが、一番下にありますところで、「品川区環境清掃事業部」となっていますけれど、ないですよね。このパンフレットだけこうなっているんだけれど、どこかでまたつくっちゃったんですか。","respondent":"工藤環境課長","answer":"すみません、これは平成２０年度に作成したものを今回お出ししました。平成２１年度からの組織改正ということで古い資料で申しわけございませんけれど、このまま出させていただきました。","id":"exchange-013"},{"speaker":"大沢委員","kind":"確認","question":"在庫がなければ、残って不良在庫になっちゃうのはもったいないなと。それこそリデュース、無駄を省くという役所の態度が本末転倒になっちゃうけれど、残っていないということでしたら、気づいていらっしゃっているか確認させていただきたかっただけなので、直してください。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"阿部委員","kind":"質問・要望","question":"ご説明のあった順番に幾つかお伺いしたいと思います。参加者を見ると結構人数が多いので、子ども向けのものを増やせないかなと思うんですが、いかがでしょうか。最後に、目黒川の風の道というのは何年も前からやっていますが、結局、涼しむというような形で導入されていたと思うんですけれども、風の道をつくったことでどうであったかという、何か客観的な検証というのはなさっているんでしょうか。","respondent":"工藤環境課長、三宅都市開発課長","answer":"順番にお答えいたします。最初の環境活動推進会議の検討内容ですけれども、形式的には何の部門についてということはございません。それと２点目の地域住民への周知ですけれども、この点は十分ではないと認識しております。","id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"どうなっているのかなと思うんです。そうすると、どれだけの部分でどれだけの力を割いていけば、どれだけの結果が出るかということをまず考えて、その中でどういう手段で議論の場をつくっていくかという順番で物事を考えていくべきであろうかと思うんですが、その辺の考え方を。あるいはそういうことはほかでやっている、こういう組織でやっているというなら、それを教えてください。","respondent":"工藤環境課長","answer":"私どもとしましても、この会議の中で地球温暖化防止対策を盛り込んだ地域推進計画につきましてはしっかりと説明して、ご理解いただいているところです。そういった中で、家庭以外の部分も今後考えていきたいと考えています。","id":"exchange-016"},{"speaker":"阿部委員","kind":"質問","question":"それはあくまでもこの推進会議の中でやっていくということですか。それとも専門性の高い分野については、区だけでやっていくということになりますか。","respondent":"工藤環境課長","answer":"方向性としては、先ほど言われましたように推進会議の幅を広げるといいますか、そういった手法もあろうかと思います。いわゆる産業部門等に関しましては、どういったことができるのかという部分はまた環境課の中で検討していきたいと考えております。","id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"このインターネット環境家計簿は、今後どのような形で区のほうで位置づけしていくのかというところをお伺いしたいと思います。もう１つ、都のほうでやっています「アクション７（セブン）」ですね、前に１回お話があったかと思うんですが、小学校で多分１回やったと思いますけれど、今回この都のほうの制度を使った学校はあったのかどうか、まず２点をお伺いします。","respondent":"工藤環境課長","answer":"２点目のアクション７ですけれども、東京都のほうが学校に対してお願いしている環境チェックシートのようなものでございまして、そのチェックシートを家庭に持ち帰って実施するという形になっています。","id":"exchange-018"},{"speaker":"浅野委員","kind":"質問・要望","question":"ありがとうございました。情報が入りましたら教えてください。生協だけでもかなりの方が参加されているということを考えるならば、もうそろそろ、こういうことがやられていますよ、区民としてどうですかという案内を始めてもいいのかなという気もするんですけれど、区のほうの考えをお聞きします。ちょっと私もつかめなかったんですけれど、何か情報がありましたら教えていただきたいと思います。","respondent":"工藤環境課長","answer":"こちらは東京都が昨年度からモデル的な実施で始めたものでありまして、東京ガスや生協と連携して、診断員の方が家庭に派遣されて、家庭における機器や使用方法を診断すると聞いております。私どもとしましても、こちらの制度がモデル的に実施されたということは把握しております。","id":"exchange-019"},{"speaker":"浅野委員","kind":"意見","question":"ありがとうございました。もちろんマイナス６％が２５％に変わっても、キャンペーンが変わっても、進めていくことだけは変わらず継続していくことだと思いますので、引き続き家庭部門の削減達成のために、ぜひとも取り組んでいきたいと思いますし、また私どももいい情報は提供していきたいと考えていますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"山元委員","kind":"質問・要望","question":"子どもはもちろん書くんでしょうが、親御さんも書かれているかと思いますけれど、その辺の親御さんの意識はどうなのか、もしわかれば教えてほしいと思います。もう１つ、エコライフ普及事業の学校ＩＳＯの中で共通内容のところを見ますと、いろいろ細かいことが書いてあって、「ごみ減量のため給食は残さないよう心がけます」と書いてあります。何か情報を得ていれば教えてほしいと思います。","respondent":"工藤環境課長","answer":"最後の共通項目以外の独自の取り組みにどのようなものがあるかですけれど、学校によりましては、例えば物を大切にするということから、小学校では「消しゴムとか自分の持ち物にちゃんと名前をつけます」とか、学校にある校庭の樹木を大切にするとか。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問・要望","question":"環境活動推進会議は、人数が今のままでいいのかとか討議する内容がどうなのかといろいろな意見がありましたけれども、もう１回まとめてお聞きします。そもそもこれは区長の委嘱機関で、任期が２年ですよね。区の大事な根幹にかかわる環境対策のことが、こういう会議体で、検討するとかというご答弁もありましたけれど、そういうことではないのかなと私は理解したので、もう１回整理をしていただきたい。","respondent":"工藤環境課長","answer":"そういった中で、何ができるのかということを考えていくことになろうかと思います。エコライフ普及事業につきましては、今後どのように展開していくかというところでありますけれど、今後いろいろと検討していきたいと考えています。","id":"exchange-022"},{"speaker":"阿部委員","kind":"質問","question":"細かいことで、今のご意見について言わせてください。学校ＩＳＯの取り組み宣言の中で、「ごみ減量のため給食を残さないよう心がけます」という言葉は、とても気になるんですね。給食を残さないのはごみ減量のためなんでしょうか。給食を残さず食べるというのは、まず食べ物に対する感謝であって、ごみを出しちゃいけないから給食を食べますというのは、ちょっと何か。これは意見です。","respondent":"工藤環境課長、太田品川区清掃事務所長","answer":"学校ＩＳＯの「ごみ減量のため給食を残さない」という項目につきましては、少し検討してまいります。２点目の件ですけれども、私のほうでも普及啓発だけだとは思っておりません。要するにごみになるものを減らしましょうという意味で、物を大切にしましょうとかリデュースの部分を言ったものだと思いますので、その辺については環境課と十分、表現の調整をしていきたいと考えています。","id":"exchange-023"},{"speaker":"飯沼委員長","kind":"質問","question":"先ほどこのパンフレットは平成２０年ということで、ＤＶＤの作成はどうかというご意見もあったんですけれども、今年度は地球温暖化対策の推進計画ができた年でもありますし、マイナス２５％を掲げているので何とか目標に近づくという意味では、新しくつくり直すとか、特に地域とかグループで学び合える、学習し合えるような協働を進めていく観点で。","respondent":"工藤環境課長","answer":"こちらができましたのが平成２０年ということですので、それから環境というのは年々変わっているような状況がありますので、そういった部分を含めまして、新しい情報とか新しい考え方という部分を取り組めるかどうかということも含めまして、検討したいと考えています。","id":"exchange-024"}]},{"id":"topic-02","title":"を行います。 中小規模事業所への省エネ推進支援事業","agenda":"を行います。 中小規模事業所への省エネ推進支援事業","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"簡単に、４事業所ということですけれど、これは公募をするんでしょうか。それとも、例えば教えてほしいんですけれど、業種をあえていろいろなところに振り分けて、ＣＯ2をたくさん排出する事業者等当然あるわけですよね、それを比較検討できるような業種を品川区が指定して募集するのか、その確認をまずお願いします。","respondent":"工藤環境課長","answer":"それともう一つは、説明していませんでしたが１５kl以上１,５００klまでの事業所になりますと、東京都の省エネ診断の無料対象になりまして、そちらで対応されるということですので、品川区のほうではその部分に入らない事業者を制度として補完しようです。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"提案","question":"調査することが目的であるならば、業種を絞ったらいかがでしょうかという話になるけれども、その整合性はいかがでしょうかというのが１つ。合わせて、省エネ診断Ｑ＆ＡのＱ２の回答の中には「義務はありません」という表現でなく、「こういう制度があるから検討してみたらいかがですか」というふうにしたほうが、よりこの制度の計画が進むと思うんですが、いかがでしょうか。","respondent":"工藤環境課長","answer":"私どもも診断後の義務は求めませんけれど、当然品川区の助成制度とか融資の部分、環境対策資金ということはものづくり・経営支援課のほうでやっていますので、そういった部分については活用を促していくことであります。","id":"exchange-026"},{"speaker":"伊藤委員","kind":"質問","question":"大切なことは、これを通して診断結果が出た後、願わくばその業者が自分たちの努力でやっていくことを願っているわけでしょ。大きくは言えない、でも願っていると。となれば、このチラシは、診断結果として出したほうが親切ではないでしょうかということは、意見だけつけ加えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"今のやりとりにもありましたけれど、要するに診断が無料だけれど、その後の設備投資は自己負担だよということなんでしょうか。その負担感を含めているのであれば、どうして支援策、助成策を考えないのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"環境対策であり、あわせて中小企業の方にとっては環境への負荷を抑えると、あわせてご商売されているわけですから、自分たちの経営も維持していかないといけない。そのための支援は中小企業への支援でもあるわけですよね。でもこのチラシだけだとなかなかそこが、そのつながりが見えてこないなと思うわけです。改めていかがでしょうか。","respondent":"工藤環境課長","answer":"診断結果・改善提案というものが報告書で出されますので、そちらのほうで品川区の融資制度等を紹介するような形で、診断をお願いする会社にそのような形でやっていきたいと考えています。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"融資制度を紹介するというお話がありましたけれど、しっかりと助成の制度も必要だと思いますので、ぜひ検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"阿部委員","kind":"質問","question":"診断対象は４事業所とあるんですけれども、診断を受けるのに負担がなくて、その後やってもやらなくてもよくて、かつ区の資金制度もある。４事業所は何か少ないような感じがするんですけれど、４事業所で切っちゃうんですか、それとももう少し多ければ増やしていくことになるのか。","respondent":"工藤環境課長","answer":"昨年からこれに似た事業を入れたという区がございまして、そちらのほうに実績を確認して予算を組みました。予算額内で可能であれば、これ以上の申し込みがあった場合には、できるだけ対応はしていきたいと考えています。","id":"exchange-031"},{"speaker":"阿部委員","kind":"質問","question":"参考までに１件の診断企業は、区がもつのはどのくらいの金額の予算なのかということ。それから周知の方法ですね。制度を知ってもらうということと、「省エネルギー診断を受けてみませんか」というチラシになっていますが、診断を受けるのが目的というより光熱費を減らしたいというところに目的があると思うので、どういう形で周知をしたんですかというところを教えてください。","respondent":"工藤環境課長","answer":"費用につきましては、予算を８０万円取ってあります。１件当たり２０万円という見積もりですけれど、場合によってはそれ以下の費用で実施された場合は、予算の範囲内での対応ができるというふうに考えております。","id":"exchange-032"},{"speaker":"浅野委員","kind":"質問","question":"さらに大きくなると、全事業者合わせて３０から３００klの部分も、報告書制度からいえば任意提出という形で、単独で１,５００kl以上の大規模工場については義務ベースになる。大規模は少ないと思いますけれど、中小ですとか、１５から３０kl、または１５kl以下が今回対象になるところですけれど、全体的な数というのは把握されているのかどうか、ちょっと気になるので教えていただけますか。","respondent":"工藤環境課長","answer":"従業員数で５名を統計で見ますと、製造業で１,３４１、小売で２,８８３、サービス業で２,０５５、合計６,２７９という対象があるというふうに考えているところです。","id":"exchange-033"},{"speaker":"浅野委員","kind":"質問","question":"１５klから３０klで、都の無料診断制度を使える対象となる企業はどのぐらいですか。今のは１５kl未満のところですよね。","respondent":"工藤環境課長","answer":"そちらのほうは資料を持ち合わせておりませんので、後から調べてご報告いたします。","id":"exchange-034"},{"speaker":"浅野委員","kind":"質問・要望","question":"多分１５kl未満のほうが断然、６,０００ということで多いと思うんです。それで先ほど質問がありました４事業所でいいのかと。大きいところは当然、報告書も義務提出になっていますので、やらざるを得ない部分もあるんですけれど、そういう部分は区としても当然力を入れていっていただきたい。そのように思うところです。","respondent":"工藤環境課長","answer":"こちらの制度は初年度ですので、どれぐらい申し込みがあるかという部分もあるかと思います。当然私どもも、今年度の申し込み状況を見まして、来年度以降どうするかを今年度の状況を見ながら考えていきたいと考えています。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"ＣＯ2で言えばどのぐらい減ったのか、電気で言えばどれぐらい減るのか、ソニーのところは建設中ですから似たような別のところで、どうなったとか、いろいろな説明の仕方はあると思うんです。仕組みの説明はあるんですけれど、効果についての説明が載っていないので、ぜひＣＯ2、電気量、また室内の温度、周辺環境の温度がどうなのか、効果についてぜひ資料を合わせて説明していただきたいと思います。","respondent":"三宅都市開発課長","answer":"こういった建物の取り組み以外の緑の関係も含めてですけれども、これは昨年、大崎駅西口のあたりで日中の温度を測定してございまして、植栽の多い大崎の森と称しているエリアでは、おおむね周辺と比べて１度から２度気温が下がっているということを観測しています。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"資料について説明してくださっても正直よくわからない部分があるので、どういう効果があるのかまとめていただいて、資料を出していただきたいのと、ご説明の中で光触媒のほうはやっていないと言われると、何のためにいれたんだと、その辺も含めてちゃんと報告をいただきたいと思いますので、ぜひよろしくお願いします。","respondent":"三宅都市開発課長、片田防災まちづくり事業部長","answer":"結果としては、今ご説明したところが数字で把握できている部分でございまして、個々の項目の結果をお示しするようなデータはございません。前回ご視察の中でいろいろな設備等々見ていただきましたが、まだ建設中のものもあれば、できてから２年たつとかいう建物の中で、今申し上げましたように一定程度の数値が出ているところで、わかる範囲の部分についてはご説明。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/187541?Template=document&Id=6194#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":37295,"voices":93}},{"id":"h22-20100914-6","meetingId":"h22-cm09","date":"2010年9月14日","dateIso":"2010-09-14","committee":"区民委員会","time":"午後１時０２分～午後３時２１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","topics":[{"id":"topic-01","title":"を行います。 初めに、(1)荏原東地区地域複合施設","agenda":"を行います。 初めに、(1)荏原東地区地域複合施設","exchanges":[{"speaker":"山内委員","kind":"質問","question":"新しくなって広くなるということで、まず使用料等はどうなるのかということと、それから、広くなるということなので、人員の配置とかいうこともあると思うんですけれども、その辺はどうなるんでしょうか。","respondent":"中山地域活動課長","answer":"建物そのものは広くなりますけれども、職員配置というのはあくまでも集会所の数、あるいは地域センターの地域事務を含めた役割が変わらない限り、現状の配置は変わらないものと考えております。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"地域センター機能の中で、現状、先ほど第１集会室が多少平米的にも広くなるということで、駐輪と駐車という中で、現状の中では車、地域センターも含めて適度にスペースが確保されております。多少、今気になっているのが、第１集会室で利用者が多い場合など、自転車がある程度多いというのが荏原第五地域センターの印象だったので、この図面でいうと、そんな配置なんかはどのようなるのか教えてください。","respondent":"中山地域活動課長","answer":"駐輪のスペースも、基本は、この図でいいますと１階の、ちょうど字で補助２６号線（計画）と書いてある、左のほうのホワイエの上の部分、ここがメインの駐輪スペースというふうに考えておりまして、現状よりは広いスペースを設ける予定です。","id":"exchange-002"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"１つは、今回、合築ということで、地域センター、昭和５３年築ということですからかなり古いと言えるのかもしれないですけれども、さっき説明があった学校側から見たメリットという話がありましたけれども、合築する理由というのか、その辺をちょっと基本的なところで教えていただきたいのですが、例えば敷地面積が広がることで建ぺい率が変わるんだよとか、そういうものがあれば教えていただきたいです。","respondent":"中山地域活動課長","answer":"それで、それぞれ全体で考えた際に、やはり敷地の有効利用、それから、建物の自由設計度を高めるという観点から、教育委員会も含めた区有地の全体の中で考えてみようというのが１つ検討のきっかけだったわけですけれども、そういう中で、この配置にもよるわけですが。","id":"exchange-003"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"後段のところは、わかりました。この業務の取り扱いの中身というのは変わっていくのかどうか、そこをもう一つお願いします。","respondent":"中山地域活動課長","answer":"所管ではない学校の関係の、今後どうやっていくかという話がどうしても主になっておりましたけれども、そういう中で、例えば連携と裏腹というふうに申し上げた、それぞれ管理の明確化であるとか。","id":"exchange-004"}]},{"id":"topic-02","title":"の八潮南小学校跡区民活動交流施設、活動拠点室の使用団体募集ついて","agenda":"の八潮南小学校跡区民活動交流施設、活動拠点室の使用団体募集ついて","exchanges":[{"speaker":"菊地副委員長","kind":"質問","question":"１つだけ教えてもらいたいのですが、今、最後におっしゃられた審査基準、こういった審査基準があって、審査が行われて、確定をしますよね。審査会を開いてやるということですから、どういうふうに知らせていく、通達していくことになるのかというのを、ちょっとそこだけ聞かせてください。","respondent":"秋山協働・国際担当課長","answer":"一応、活動拠点室の募集の定義というのを設けてございまして、その中で審査基準の視点というものを明らかにして、応募のほうをしていただくと。もちろん審査の結果についてはホームページ等で公表をしていくものです。","id":"exchange-005"},{"speaker":"菊地副委員長","kind":"質問","question":"結果はいいんです。結果はわかるんです。限られたブースですから。だから、漏れた方にどういうふうに示していくのかということを教えてもらいたい。","respondent":"秋山協働・国際担当課長","answer":"失礼しました。審査の中で、審査基準に照らしてどのようであったのか、例えば意欲としてちょっと足りなかった、そういう審査基準に照らしてこういう内容であったという、当落だけではなくて、中身についてもお知らせをしていくということを考えてあります。","id":"exchange-006"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"同じような、多分区内でこういう活動をされていらっしゃる方たちですから、同じような意欲を持って、同じような中身で活動されている方たちって多いんだと思うんですけれども、同じようなレベルの方たちを選ぶわけですから、当然、選に漏れた方たちが納得できるような示し方がないと、多くの団体がもし申し込んだときには、非常に不満として残る部分なのかなというふうに思うんです。ちょっとこれは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"石田委員","kind":"質問","question":"１点だけ、区民活動交流施設内に設けるということで、使用時間というのは、その施設の使用時間と同じなんですか。","respondent":"秋山協働・国際担当課長","answer":"この区民活動交流施設の使用時間と同じです。午前９時から午後９時半の時間で、お休みの日とかありますが、それは別として、一応区民活動交流施設と同等、同じという扱いです。","id":"exchange-008"}]},{"id":"topic-03","title":"の「品川区地域安全のつどい」の開催","agenda":"の「品川区地域安全のつどい」の開催","exchanges":[{"speaker":"菊地副委員長","kind":"質問","question":"ちょっと１つ教えてもらいたいんですが、いろんな報道があってよくわからないんですけれども、従来、これまでの制度の中でも、国との協議の中で戸籍そのものを抹消していくという制度はあったわけですよね。報道の中ではそんな感じの書き方もあったりして、その辺の従来の制度がどうであったのか。その上に立って１,００７名の方が残っているんだよというところをちょっと説明してもらえますか。","respondent":"梶戸籍住民課長","answer":"ただし、戸籍というものは、あくまでも先ほどご説明いたしましたとおり、通常は死亡、あるいは失踪届、そういうもの等がないと除籍とならないものですから、そういったところについては、あくまでも調査を重ねまして、慎重にやっていくというところが実際です。","id":"exchange-009"},{"speaker":"菊地副委員長","kind":"確認","question":"今説明のあった部分で、じゃあ、従来の制度の中で、これも手続をしたとしますよね。それが国によって除籍が確認をされたという方は、今の説明だと１,００７名の中には残っていないということですよね。そうすると、１,００７名の方に、従来の制度の中でその手続をしてこなかったということなんですか。","respondent":"梶戸籍住民課長","answer":"先ほど言った高齢者消除という手続については、いろいろ調査があるということはご説明させていただきましたけれども、その１,００７人がここに残っているということは、高齢者消除をしていない方、そのまま残っている方がいますということです。","id":"exchange-010"},{"speaker":"菊地副委員長","kind":"質問","question":"ですから、その手続そのものを、品川区として、その調査そのものを従来はしてこなかったというふうにとらえていいんですか。","respondent":"梶戸籍住民課長","answer":"制度として定期的にやっていたという形ではございませんが、前の段階で何もないとか、気づいた段階でやっていたということはあります。ただし、公に定期的に毎年何十人といった形ではございませんでした。","id":"exchange-011"},{"speaker":"菊地副委員長","kind":"質問","question":"もう一つ。そうすると、定期的にやっていなかったという話なんですが、そうすると、最後に品川区としてそうしたことをやったというのはいつなんですか。","respondent":"梶戸籍住民課長","answer":"こちらも、高齢者消除という特別な手続をしたということは、ちょっと今は資料には残っていないんですけれども、はっきりしたことはあれなんですけれども、定期的にやっていないということで資料は残っていないんですけれども、平成４年、あるいは５年ごろに調べていた調査。","id":"exchange-012"},{"speaker":"山路委員","kind":"意見","question":"山北町で災害がありましたよね。品川区と協定を結んでいる町でありますし、私たちも山北町は何回かお邪魔しました。非常に深い関係にあるのですが、品川区として災害に対して何かやられたかどうか聞かせていただけますか。","respondent":"中山地域活動課長","answer":"先週ですか、いわゆる水害というか、報道では相当、川のはんらん等があるということで映像としては非常に衝撃的なものがあったのですが、町のほうで、その被害状況について先週かけて調査をしたところですが、あまり道路の通行止めに至るような被害というのは。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/764503?Template=document&Id=2590#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":15710,"voices":61}},{"id":"h22-20100914-7","meetingId":"h22-cm09","date":"2010年9月14日","dateIso":"2010-09-14","committee":"厚生委員会","time":"午後１時０２分～午後２時３６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","topics":[{"id":"topic-01","title":"高齢者のための新たな医療制度等について（中間とりまとめ）","agenda":"高齢者のための新たな医療制度等について（中間とりまとめ）","exchanges":[{"speaker":"南委員","kind":"確認","question":"今、ほんとうに大ざっぱな説明をいただいて、なかなか理解するのも難しいかなと思っているんですけれども、この中間とりまとめについて、区としての見解というか、ほとんどが引き続き検討となっているのであれですけれども、大枠はどういうことなのか、ちょっと改めて確認したいんです。具体的なところについては、これからの検討だというふうに認識していいのかどうか、まず一つ、確認したいと思います。","respondent":"本城国保医療年金課長","answer":"そのうえで、国民健康保険のほうは、この改革案におきましては、両方の案があるですが、７５歳以上、あるいは６５歳以上の高齢者の部分の財政運営については、都道府県単位の運営にするという、そのような形で、若い人と別勘定での国民健康保険になることを想定しているものです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"今、国民健康保険の運営そのものも決して安定している状況ではなくて、毎年、保険料が値上がりしているという現状があって、この特別区長会で出した要望書を確認すると、国の責任が、制度の根幹にかかわるところが先送りされているということと、だれが国民の医療に責任を持っているのかというところで、財源を確保する、根本的なところがなかなか示されていないというところで。","respondent":"本城国保医療年金課長","answer":"現在の案は、あくまでも中間とりまとめということで、国の説明では、これで一応のフレームを確定した後に、財政的なシミュレーションはこれからするということで整理されているところです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、保険者としての品川区として、そういう問題点を含んだ中間とりまとめということではあるけれども、具体的な詳細はこれからなんだけれども、一定程度の姿形が示されてきつつある中で、しかも別勘定になるという点については、どのような問題点が予想されるのかと伺ったんですけれども、あれば、そこをちょっと教えていただきたいと思います。","respondent":"本城国保医療年金課長","answer":"その趣旨としては、保険料に連動させることによって、保険料の収納のインセンティブを働かせる一つの方策として提案しているというような説明がされているところです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"要するに、自治体によって、例えば、高齢者が大勢分布している自治体と、そうではないところと、単純に比較したときに、高齢者が大勢いらっしゃるところは、当然、給付も多くかかるわけですから、同一の料金だととても大変な状況がある、そして、しかも、所得の低い世帯の地域の自治体では、収納そのものも、今でも大変苦労があるわけですけれども、そうなると、収納率が高かったり、低かったりという点で。","respondent":"本城国保医療年金課長","answer":"この中で、「収納状況等を勘案し」と書いてありますので、収納率に応じた保険料になるということは、一つ一番主なものとして想定されているところですが、それ以外に、どういう要件を勘案するかということについては、まだ具体的に示されていないので。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"収納率を勘案して保険料率を定めるということは、具体的に、収納率が低かったら、どういうふうな保険料になるのか。一般のレベルからして、高くなるのか、低くなるのか、具体的に教えていただきたい。","respondent":"本城国保医療年金課長","answer":"そのあたり、８ページの○の続きに書いてあるのが、そのような趣旨のところです。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、高齢者の多い地域とか、所得の低い方々が多くいらっしゃる地域、そういうところは、当然収納に非常に努力が必要だと。その点については、いかがでしょうか、最後の質問にしたいと思います。","respondent":"本城国保医療年金課長","answer":"先ほど、十分な準備期間を設けるという決議を、市長会でもしているというお話しさせていただきましたが、あわせて、新たな医療制度改革の発足によって、国民健康保険制度の負担増を決して招かないように、国の責任において万全な対策を講じることとか。","id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問","question":"先ほどからのやりとりを聞いておりますと、結局、この資料の中身の説明だけであって、区としてどう考えるのかという姿勢が見えないと、率直に思いました。今の時点で、改めて、品川区に伺いたいのは、後期高齢者医療制度は、多くの方に理解を得られた制度改正だとお考えなのか。つまり必要な改正だったと思っていらっしゃるのか、今の時点に立っての区の評価を伺いたいと思います。","respondent":"本城国保医療年金課長","answer":"ただ、緊急申し入れにもありますように、これからますます医療費が増大する中で、将来を見据えた中では、制度の抜本的な改正も必要になるということにつきましては、現在の制度の課題の一つと考えているところです。","id":"exchange-007"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"やはり国民の理解が得られていない制度だと、それを背景に動いてきたと思うんですけれども、その点はどうお考えなのか、ご説明いただきたいと思います。つまり、制度が変わる以上、各地域センターごとに説明会を行うとか、そういう丁寧な説明は、当然、必要だと思うんですけれども、今、どんなふうにお考えなんでしょうか。","respondent":"本城国保医療年金課長","answer":"本日、ご説明していますのは、平成２５年の改正に向けた高齢者医療制度の骨格について、今、示されているものをご説明させていただいているところですが、内容をまず提示されて、それを、区の立場としても精査するというのが、まずは先決で、そのためにおきましても。","id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"１人で２回、３回という方もいて、そういう状態が起きたわけですよね。電話を含め、窓口も含め、こういう混乱を招いたと思います。最後に伺いたいのは、品川区も子どもの医療費無料化は、紆余曲折を経ながら、中学３年生まで広がりましたけれども、やはり、次は高齢者の医療費無料化に向けて、また医療費の負担軽減に向けて、一歩足を踏み出すべきだと、私は思うんですけれども、そこはいかがでしょうか。","respondent":"木下健康福祉事業部長","answer":"この背景にあるのは、多分、今、お話ししたようなことも含めた長期的展望に立った医療制度改革にしなさいと、このことを慎重に検討しなさいというのが、現在の立場だと考えています。","id":"exchange-009"}]},{"id":"topic-02","title":"子宮頸がんワクチン予防接種助成事業（予定）","agenda":"子宮頸がんワクチン予防接種助成事業（予定）","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そうすると、任意ですから必ずしも全員ではないですけれども、考え方として、中学校を卒業した１６歳から１９歳の年齢の方々は、この対象から外れるわけですよね。ですから、その辺で、学校の教育が一番スムースにいくのかなと思うんですけれども、その辺についても、しっかりと教育の場面を提供できるようにしていくべきだと思いますので、その辺について、改めて伺いたいと思います。","respondent":"吉田保健予防課長","answer":"最後の、性感染症としての学校教育というところでは、所管ではございませんので、お答えは大変難しいところがありますけれども、我々としては、保護者を含め、何らかの啓発を実施してまいりたいと考えています。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"もしそういうふうに予算化されていった場合には、品川区としての予算額というのは、残っている６分の１ぐらいの補助なのかなと思っているんですけれども、額については、これからの審査になってくると思うんですけれども、受診される区民の皆さんからすると、無料の予防接種が受けられると、そういうふうに理解していいのでしょうかということを、ちょっと聞きたかったので。","respondent":"吉田保健予防課長","answer":"ですから、それを勘案した範囲内で一定額の補助ということで、今まで任意接種では一部補助を続けてまいりましたので、その方向で検討してまいりたいと考えています。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"このワクチンの製造元でグラクソ・スミスクラインのプロフィールを教えていただきたいのと、このワクチンで、どれだけのシェアを持っているのか、教えていただきたい。","respondent":"吉田保健予防課長","answer":"供給量としては、製造元に確認したところ、どのぐらい輸入しているかというところまでは教えてはいただけないんですけれども、十分量確保はできるというような回答でした。","id":"exchange-012"},{"speaker":"山元委員","kind":"質問・要望","question":"もう１回確認をさせていただきたいのは、平成２２年度は、中学２年生、３年生の女子ということで、これは来年の１月から３月の３カ月の間に接種をしてということでいいのでしょうか。","respondent":"吉田保健予防課長","answer":"それを、わずか２カ月なり、３カ月内でというのは大変厳しい話ですので、ちょっとどのぐらいというのは、現在申し上げられないんですが、それより長い期間を検討していますけれども、ご希望の方は確実に接種が受けられる体制をつくってまいりたいと考えております。","id":"exchange-013"},{"speaker":"山元委員","kind":"意見","question":"そうすると、中学３年生は３月で卒業をしてしまって高校生になってしまいますが、そういう人たちに対して、多分、皆さんにお知らせが行くんだと思うんですが、内容は、もちろん過ぎてからでも受けられるようなご案内になりますか。","respondent":"吉田保健予防課長","answer":"卒業とは、おそらく関係ない形で、ある程度、接種可能な期間を設けてお知らせを出すような形になるかと思います。","id":"exchange-014"},{"speaker":"山元委員","kind":"質問・要望","question":"最後に１点、もう１回確認です。この子宮頸がんといいますか、普通、私たちが子宮がんの検診を受ける場合、何点かありますが、その確認をさせていただきたいのと、それから、このワクチンに対しての検診というか、内容は、ワクチンだけをするということでいいのか、ちょっと確認をさせていただきたいんです。","respondent":"吉田保健予防課長","answer":"その点につきましては、中でも、まだ十分に検討が進んでいないところですが、いずれにいたしましても、２０歳の方につきましては、検診と、ワクチンの両方をお勧めするような内容にしたいと考えております。","id":"exchange-015"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今年の３月１２日の予算特別委員会で、子宮頸がんワクチン接種への全額助成実施を求めて質問したときに、担当課長から三つの問題があると、それで、慎重に対応を考えていく必要があるというお話があったんですけれども、その問題がどう克服というか、解決というか、考えられて実施に至ったのか、専門的なことは僕はわからないので、ご説明いただきたいと思うんです。","respondent":"吉田保健予防課長","answer":"全額助成につきましては、先ほどの繰り返しになってしまうかもしれませんが、任意予防接種につきましては、一部助成という考え方で、これまでも考えてまいりましたので、その方向で検討してまいりたいと考えています。","id":"exchange-016"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"２０歳、３０歳代の女性に急増する。ワクチンで予防できる唯一のがんだと。その踏み切れない理由がどこにあるのか、任意だからという説明ですけれども、なぜ希望する人に全額補助ができないのか、そこをもう一度ご説明いただきたいと同時に、全額補助にぜひ踏み出すべきだと思いますけれども、再度、いかがでしょうか。","respondent":"吉田保健予防課長","answer":"予防接種自体は、メリットばかりではなくて、やはりデメリットの部分もあると考えております。ですから、その双方を勘案してお打ちいただくというのが趣旨かと考えていますので、区といたしましては、一部補助の方針で考えております。","id":"exchange-017"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"任意だからという説明では納得できないんですね。つまり、希望している人になぜ全額の補助ができないのかということなんですよ。もちろん任意だということはわかりますよ。任意であるわけだから、希望する人がやるわけですよね。その人に対して、どうして全額というふうにできないのか、そこがわからないので、説明していただきたいと思います。","respondent":"吉田保健予防課長","answer":"定期予防接種につきましては、努力義務というのが必ずつきまとっておりますので、当然、国、あるいは東京都の負担がございまして、季節性インフルエンザを除き全額無料という形で実施をさせていただいているものです。","id":"exchange-018"}]},{"id":"topic-03","title":"今季のインフルエンザワクチン接種","agenda":"今季のインフルエンザワクチン接種","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"６５歳以上の今までの予防接種として、予防接種そのものは１回ですが、公費助成というのはどのぐらいで、現実的に、ご本人負担はどのぐらいなのか、一般的な価格でいいんですけれども、それを教えていただきたいと思います。","respondent":"吉田保健予防課長","answer":"インフルエンザワクチンにつきましては、定期予防接種につきましても、１０月１日からの接種ということで、現在、実施している医療機関はまずないという認識です。ですから、事前に接種を行われるということは、まずない、おそらく市場に出ていない。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"私の言い方が悪かったのなら悪いんですけれども、１０月１日以降、接種を開始するわけですよね。ですから、三者協で９月３０日までに結果が出て、助成しますということになればいいんですけれども、１０月１日とか、接種できる時期の早々に接種してしまった場合に、もし事務的な連絡が十分に行き届かなくて対象にならなかった場合、還付で来るのか、ちょっと細かいことなんですけれども、伺いたかったんです。","respondent":"吉田保健予防課長","answer":"一部、ご説明が漏れてしまいましたが、６４歳以下の、現在、２３区で検討している対象者といたしましては１～１３歳未満の方で、この方々は、２回ワクチンを接種しなければいけないということで、大変負担が重くなるということで。","id":"exchange-020"},{"speaker":"中塚副委員長","kind":"質問","question":"今回の新型インフルエンザワクチン接種についてですけれども、すべての国民を対象に接種を行う方針と、予防接種法が改正されるということなんですけれども、今までどうだったのか、今回、それがこうだと、その理由や背景、そこをご説明いただけますでしょうか。","respondent":"吉田保健予防課長","answer":"ただ、実際にこの法案が可決され、施行される時期につきましては、今のところ、一切情報が入っておりませんので、今年度中になるだろうと予想はしているところですが、実際にいつから実施されるかについては、現在のところ未定といったところです。","id":"exchange-021"},{"speaker":"中塚副委員長","kind":"意見","question":"もう少し、要するになぜすべての国民を対象に接種することが方針になったのか。先ほどのご説明ですと、昨年来の新型インフルエンザをめぐるいろいろな議論の積み重ねの経過だということはわかったんですけれども、なぜ今回、全員としたのか、もっと言えば、その位置づけにした理由をご説明いただけますか。","respondent":"吉田保健予防課長","answer":"これは国の審議会の中で出てきている意見ですので、ニュアンスとして細かくお伝えできない部分もあるかと思いますが、基本的には、昨年のインフルエンザについては、若年者の流行が中心であったということで、まだ十分に免疫を持っていない方が国民の中にいらっしゃる。","id":"exchange-022"},{"speaker":"中塚副委員長","kind":"質問","question":"とりわけ、所得の少ない方への対応というのは非常に急がれていると思うんですけれども、所得の少ない方への対応、対策については、どのように考えているのか、減免や無料化を検討しているのかどうか、伺いたいと思います。この実態については、まず区はご存じなのかどうか。やはり、まずは所得の少ない人からでも、無料化についても、しっかりと検討すべきではないかと思うんですけれども、いかがでしょうか。","respondent":"吉田保健予防課長","answer":"ただ、一定の低所得者への対応といたしましては、生活保護などの方には費用助成を行うというのを、国は出しておりますので、区としてもそれに沿った対応で考えていきたいと考えております。","id":"exchange-023"},{"speaker":"中塚副委員長","kind":"質問","question":"国に沿った対応をとらざるを得ないというのが、よく意味がわからないんです。しっかりと、区として主体的に区民の命を守る、そういう姿勢、そういう検討をしっかり持つことが必要だと、私は思うんですけれども、いかがでしょうか。改めて、所得の少ない方への対応、インフルエンザ接種の無料化や自己負担をなくすことをしっかり検討すべきだと思うんですけれども、いかがでしょうか。","respondent":"吉田保健予防課長","answer":"それにつきましては、特に東京２３区につきましては、人の移動も多い、それから、ほかの区でかかりつけ医を持っている方も大変多いということがありますので、相互乗り入れができるような形、しかも、今回は２回接種という対象者が一部出ておりますので。","id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"２４時間対応ということなんですけれども、電話を受けたところが、それぞれの所管に、必ず情報が伝わり、対応することができるということなんですけれども、例えば夜の１１時とか、１２時とか、そういう時間帯に子どものすごく泣く声が聞こえるとか、ちょっと気になったし、いつもあの辺から聞こえてくるというような場合があったとしたときに、電話をしたとすると。","respondent":"冨岡高齢者福祉課長","answer":"それはあくまでも宿直等の意見になりますが、緊急性がどの程度か、これはかなり研修等をしまして、うまく伝わるように、間違いのないようにということで対応してまいりたいと考えております。","id":"exchange-025"},{"speaker":"山元委員","kind":"質問","question":"南委員の質問とちょっと関連するんですが、先ほど、専用ダイヤルの電話が設置されるとおっしゃっていたんですが、そうすると、今のお話の続きになりますが、夜の場合は、宿直のところではなくて、専用ダイヤルの電話に直接いくのでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"電話の整備の関係ですが、電話番号は専用回線でありますので、切り替えをいたしまして、必ずだれかにつながるという形で、その後はまた連絡をする。","id":"exchange-026"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"その他でちょっと１点、伺いたいことがあったんですけれども、熱中症のことなんです。今年の夏は非常に暑くて、多くのお年寄りが具合を悪くされたり、命を落とす事態が続いているので、品川区の状況を伺いたいと思うんです。この事態を、品川区としてはどう考えていらっしゃるのか、区の対応策も含めて、ちょっとご報告いただけますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"やはりお年寄りの話を聞くと、クーラーを直すお金がないとか、設置するお金がないとか、クーラーはあるけれども、電気代の負担が心配でなかなかつけるのも不安だと、こういう事態を背景に熱中症、また命を落とすという事態には、やっぱり必要な対策を講じるべきだと思いますので、ぜひ、ご検討いただきたいと思います。実態については、後ほど、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/347330?Template=document&Id=3278#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":29444,"voices":84}},{"id":"h22-20100914-8","meetingId":"h22-cm09","date":"2010年9月14日","dateIso":"2010-09-14","committee":"建設委員会","time":"午後１時０４分～午後３時３４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","topics":[{"id":"topic-01","title":"を聴取してまいります。 はじめに、(1)の中央環状品川線工事関係","agenda":"を聴取してまいります。 はじめに、(1)の中央環状品川線工事関係","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"シールドマシンの補修工事のほうですけれども、住民に配布ということなんですが、どういうものを配布したのか、何部配布したのか、教えてください。それから、時期は２月中旬ごろということなんですけれども、この工事だけでかかる費用は、大体どのぐらいなのかということを教えてください。","respondent":"山崎マスタープラン担当課長","answer":"アンケートにつきましては、配布部数が２万７,８９５枚、回答数が１,４３０枚、率にしますと５.１２％ということになっています。それから、シールドマシンのほうの補修工事、立正大学で行われる説明会に、何人ぐらいの集約を見込むのかです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"説明会に来なくても、今、何をやっているのか、周辺の方が不安に思うと思うので、内容がわかるような看板の設置とか、それはもうやっているのかもしれないですけれども、もしやっていないとしたら、必要だと思うんですけれども、そういった予定はあるのかどうか、お伺いします。","respondent":"山崎マスタープラン担当課長","answer":"説明会につきましては、まず、今回、お示しの計画をもって行います。それから、チラシ等々、周辺の町会、自治会に配るときに、十分に説明をさせていただきながら配布をしているということと、今回、前面のマンションの下が、例えば商店だったり、いろいろあります。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"さっき気になっていたのは、５０ｍ範囲の町会、自治会には説明して配布というのは、これはポスティング形式でやったのか、それとも、町会に委託枚数をお渡しして配ってもらったのか。ポスティングをやったということでよろしいのでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"首都高のほうで、説明を兼ねたポスティングという形で極力やっていただいたと伺っております。","id":"exchange-003"},{"speaker":"阿部副委員長","kind":"質問","question":"換気所の件なんですけれども、２点ほど質問させてください。デザインでは換気所とは思えないなかなかしゃれたものなので、すばらしいと思うんですけれども、この図を見る限りでは、路面のシャッターの部分が何となく殺風景な感じがしますので、路面の部分は、特にデザインに配慮してほしいです。これはまだ書いてあるだけで、未定なんですか、今後、意見を言っていくということなんでしょうか。","respondent":"山崎マスタープラン担当課長、片田防災まちづくり事業部長","answer":"すみません、今回につきましては、景観に関してのアンケートということで実施しているものです。前面の目黒川の植栽等も含めまして、そういった路面の部分につきましては、詳細については、まだ未定という形になってあります。ただ、どういうみどりを植えようかとか、そういうところの点については、これから意見を踏まえて検討という部分もありますし、基本的には、事業者が対応すると聞いてあります。","id":"exchange-004"},{"speaker":"阿部副委員長","kind":"質問","question":"東京都のものなので、東京都が決めて、東京都が管理するというのは大変順当なことだと思うんですけれども、緑地の管理とか、結構きめ細かいものが必要だと思いますので、東京都の管理だからということで、何だか木が伸び放しになっていたり、ちょっとごみがたまったままとかいうのは、あまり嬉しくないと思うので、その辺をお伺いしたいと思ったんですけれども、何かお考えがありましたら。","respondent":"片田防災まちづくり事業部長","answer":"基本的には、事業者が管理される部分ですが、区のほうとしても、適正な管理が行われるよう指導していきたいと考えております。","id":"exchange-005"},{"speaker":"若林委員","kind":"質問・要望","question":"要するに工事でしたので、壁をつくって歩行者からこっちが見えない状況が長く続いていて、まちの活性化というんですか、住民にとっては大変つらい何年間を過ごしきたという部分がありますので、ぜひそこら辺のところを、区のほうとしてもご配慮いただいて、要望になりますけれども、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"それで、完成期間がおくれるというのはどれぐらい見ているんですか。当然、補修している間、掘った内壁のところはどんどんやっているわけですから、その期間だけおくれるのか。２４時間稼働するわけですから、このおくれがそっくり完成時期のほうにつながるのかと思っているんですけれども、どのぐらいおくれるのか、わかりましたら教えてください。","respondent":"山崎マスタープラン担当課長","answer":"本停止に伴う補修工事による品川線全体、平成２５年を予定しておりますけれども、そこには、今のところ影響が出ないということで伺っています。","id":"exchange-007"}]},{"id":"topic-02","title":"の耐震化推進啓発の結果","agenda":"の耐震化推進啓発の結果","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"アンケートを取ったということですが、個別訪問して取らなければ、なぜ改修とか、建て替えとかしないかということが、区としてわかりませんでしたか、という質問なんです。それから、ちょっと細かくなってしまいますけれども、問１の自宅の耐震診断の結果はいかがでしたか」というのは、８割が必要ありと出たわけということに対して、区はどう思うかということを、まずお聞きしたい。","respondent":"品川防災整備担当課長","answer":"当然、この金額を少しでも上げていかなければいけない方向にあることは確かだと考えておりますが、では一体どのぐらい上げればいいのかというところを、今回、問５で、費用は大体幾らまで出していいですかというところで、このように表で出ておりますが、これを踏まえて。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"ということは、８割方の住宅はやらなくてはいけない。そうすると、改修できない理由、現状を聞き取り調査した結果というのは、もうわかったわけですから、その結果を、支援制度の見直し、検討するということは、もうその辺は、そんなに難しくなくて、８割方がある、そして、金額も大体でているということは、ストレートに言うならば、もう助成の金額を上げていくしかないと思うんです。","respondent":"片田防災まちづくり事業部長","answer":"現在、次年度の予算等を含めて検討している段階でもありますので、今回のアンケート調査を含めて、そういう施策の中に、平成１９年ですから、ちょうど事業を進めてから３年経ちますので、そういう実績効果を踏まえたローリングを行いたいということで、考えているところです。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問・要望","question":"経済的なことなんだと、お金なんだというのは、これだけ出ているわけじゃないですか。だから、アンケートを取って、施策に反映していくのだったら、もう金額のことしか、経済的なことが一つではないじゃないですか。だって、アンケートに出ているんですから、これだけの数字が。だから、一つではなくて、もうちょっと上げていくんですかと、将来的に。","respondent":"片田防災まちづくり事業部長","answer":"ですので、ただ単に工事費用を上げますということではなくて、いかに改修に結びつくための工夫ができるどうか、それは当然、お金のことにもつながってくるわけですので、一応、金額的なところも含めて、政策の中でも、工事期間中の問題等もありますので、例えば改修にあたって。","id":"exchange-010"},{"speaker":"渡部委員","kind":"質問・要望","question":"であれば、少ない費用でできる方法、これならできるのではないでしょうかみたいな、重ね重ねのＰＲ等や説明だったうえで、耐震シェルターについてどうお考えですかという形であれば、スムーズにいけるのかなと思うんですが、その辺、要するに問６自体に、問５から問７にはつながると思うんですけれども、ここでいきなり問６という全く違う質問になっていると思ったので、その辺の意図を教えてください。","respondent":"品川防災整備担当課長","answer":"３点目のアンケートの方法なんですが、これはやはり選択肢にしております。そういう形で行いました。それから、４点目のシェルターにつきましては、問６の質問した対象者につきましては、耐震改修工事を、今後実施する予定がありますかという方について聞いております。","id":"exchange-011"},{"speaker":"渡部委員","kind":"質問・要望","question":"わかりました。シェルターの件は、わかりました。ただ、区としては減災の部分もありますけれども、その方の命がまず助かってもらうことが第一だという点で、やはり、改修を進めていただく、それが無理なら、なるべく廉価な費用でできる簡単な工事等を働きかけて、これからもやっていただきたいと思いますので、今回のアンケートを見ながら質問をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"マンションに関して、まだ診断しか助成がないんですが、範囲拡大というのは、どういうふうに考えていらっしゃるのかお伺いします。それから細かい点でわからなかった点なんですが、８ページでアンケートの収入のところなんですけれども、２００万円以下の方が７２％で、年金のみの方はそこに含めているというご説明だったんです。","respondent":"品川防災整備担当課長","answer":"１番の総合的なアンケートの考えについてですが、この結果を踏まえまして、費用の助成額、それから宣伝方法、改修とかについては、ある程度の該当する家を訪問して説明していくような方法は考えられますので、その辺は、総合的に考えていきたいと考えています。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"こちらも、補強の支援もつくるべきだと思いますので求めたいんですが、９ページに書いてあることは、助成範囲の拡大を望んでいると言っているんですが、これは何を指しているのか聞いたんですけれども、それがちょっとよくわからなかったので、そこだけ教えてください。","respondent":"品川防災整備担当課長","answer":"マンションにつきまして、委員のほうからお話があったように、耐震助成を考えていないということではなくて、区全体としての状況として、マンションは今、９０％になるけれども、木造のほうはまだ足りていないというところも踏まえながら考えていきたいということでありますので。","id":"exchange-014"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"極端に少ないんですよね。だから、この結果を見て、これが区民の数字であるととらえると、大変読み間違えると思うので、５ページの読み方はぜひ気をつけていただきたいと思います。先ほど、助成額を増やすということをおっしゃっていましたけれども、ただ増やすということではなくて、もう少しきめ細かく見ていくべきだと思うんですけれども、その辺のお考えを教えてください。","respondent":"品川防災整備担当課長、片田防災まちづくり事業部長","answer":"これは実際に何人中の３３人かといいますと、問３で、「耐震改修工事を実施する予定がありますか」に、いいえと答えた７３人の中で聞いております。ということで、全体としては４０人の方が、金額は出しておりません。やはり、ここに出されているＮ＝３３という数字についても、逆にやろうと思っている人は、このぐらい出してほしいというような思いも、一方ではあると思いますので、そうではない方。","id":"exchange-015"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"部分改修というのは、一言で言って、検討すべき項目であろうと思いますので、ぜひ、よろしくお願いします。そこをちょっともう少し整理していただきたいと思うので、そういう考え方はありますか。","respondent":"片田防災まちづくり事業部長","answer":"したがいまして、特に高齢者でなかなか厳しいという方については、シェルターということも考えておりましたので、現時点で、まだ把握してきているんですけれども、去年は助成事例が一、二あったんですけれども、今年はまだ出ておりませんので、一応、受け持ちではなくて。","id":"exchange-016"},{"speaker":"市川委員","kind":"質問・要望","question":"先ほどからのマンションの助成内容、具体的にお聞きしたいんですけれども、先ほどもあったんですけれども、７ページの戸建ての助成範囲の拡大で、回答２０件というのがあるんですが、ここでは、現状、どういった助成の範囲なのか、教えていただきたい。それから、４ページでアンケート調査結果の中で、耐震で前よりも建物が狭くなるということで３件の方が回答していらっしゃいますが、どういうことなのか。","respondent":"品川防災整備担当課長","answer":"３点目の、こちらを資料として使っていく方向ですが、先ほども発言したとおり、金額等、このアンケートの結果にのっとって制度改正を考えております。","id":"exchange-017"},{"speaker":"市川委員","kind":"質問","question":"今の一番最初にお答えいただいた、助成範囲の拡大のところで、具体的に何を対象にするのか、アンケート調査の中で、調べたのでしょうか、具体的にこういったものもつけてほしいとか。","respondent":"品川防災整備担当課長、片田防災まちづくり事業部長","answer":"耐震改修をする前に補強設計というものがあります。これが、現在、４０万円ぐらいかかると言われておりますが、この部分に対して、今、補助が全くないので、これについての補助を考えている状況です。検討しているイコール予算がつくということではございませんので、その辺を効果的な進め方ができるようにするという状況ですので、よろしくお願いします。","id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"アンケート結果が７割ぐらいで、だって助成を受けて耐震診断をして、その結果何もしなかったという方たちにどうですかって聞いているんだから、ほとんど１００％近く、アンケート結果が出なきゃおかしいと思うんです。７０％ぐらいで事足りたと思っているんですか。それをまずお聞かせください。","respondent":"品川防災整備担当課長","answer":"中には、やはりアンケートに答えたくないという方も何人かいらっしゃいますので、区としては、そこはやはりやむを得ない状況があるとは考えておりますので、答えた方の中で検討していかなければいけないというふうには考えます。","id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"答えなくないというのは、これは推測でしかないけれども、どのように推測しているのか。ただ、答えたくないというから、はあ、そうですかっていうことですか。見た感じ、どういう方たちが答えたくないというのか。どういう方たちが答えたくないと思っているという報告はないのですか。","respondent":"品川防災整備担当課長","answer":"やはり、不在している件数がかなり多いというところが、７０％の回答率になっている原因だと考えてます。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"何か、そのアンケートの取り方が安易に取っているような、こんなことを言うと一生懸命仕事をしている人たちに対して申しわけないかとは思いますけれども、一度、耐震診断を受けて、助成を受けたんだから、それについて結果、工事をしない方に対して、どうなんですかというのは、やっぱりきめ細かくやるべきだと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-03","title":"の目黒駅前地区再開発事業の経過","agenda":"の目黒駅前地区再開発事業の経過","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"用途地域の変更と、高度利用地区の変更があるんですけれども、容積率がそれぞれ変化するということですが、変更されることで、建てられる建築物の制限がどう変わるかというか、そこら辺をもう少し教えていただきたい。それから、用途地域を再開発に先行して変更したという例では、区内でほかにあるのかどうか、あわせてお伺いします。","respondent":"三宅都市開発課長","answer":"２点目、用途地域、高度利用地区の変更によって制限がどう変わるということですが、今、ご説明しましたように、一番後のページの高度利用地区のところですけれども、これによって空地をどれだけ生み出したかということですとか、境界線から壁の位置をどれだけ内側にしたかとか。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"防火のところも、準防火地域がどう変わるのかも、あわせて教えていただきながら、この関係というんですか、それをもう少し説明していただきたい。容積率を上げる理由を聞かせてください。そういった理由は、ちゃんと明示されて縦覧されるのか、どうかということ。かつてのお知らせですと、結構書いてあったような気がしたんですけれども、なぜ意見書提出できると書かないんですか。","respondent":"三宅都市開発課長","answer":"広報において、問い合わせ先など示しておりますので、お問い合わせがあれば、縦覧ができることの内容とあわせて、意見書が出せることにつきましても、ご説明する予定になっております。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"紙面に限りがあると言っても、１行で済むことだと思いますので、胸を張って進めたいという計画であれば、堂々と意見を募集していますということを書くべきなのではないかと思いますので、今後、ぜひ改善してください。ですから、私は、その思いにこたえて、せめて少し風を軽減するように計画を変更すべきなのではないかと思うんですけれども、そのつもりがあるのかどうかというのが一つ。","respondent":"三宅都市開発課長","answer":"そもそも、この環境アセスメントという制度ですけれども、これは大規模な開発事業を行う際に、事業実施によって環境への影響をできるだけ少なくするための仕組みとなっています。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"軽減策をとるから大丈夫なんですよ、それを指導していきますということなんですが、よそが出してくれる軽減策をとった後が、今、示された資料で、ランク２のところがかなり増えるという状況だと思います。地元自治体としては、こういう地元の住民の皆さんの利益に配慮して、強く東京都に対して話し合いに応じてくださいと求めるべきなのではないかと思うので、それはいかがでしょうか。","respondent":"三宅都市開発課長","answer":"準備組合と近隣の方々との交渉なんですけれども、陳情があったということで、協議を延期したというようなことは、私どもも聞きまして、そういうことではなくて、対話は必要であるし、十分な理解が得られるように説明が必要であるということを伝えております。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"改めてお伺いしたいんですけれども、目黒駅前地区再開発事業なので、地区整備構想なんですが、トライスククエア構想って、何でこういう名前がついているんでしょうか、教えていただきたい。それから、この間、大崎のまちを見まして、再開発、すばらしいなと思いまして、やってよかったと思ったんです。別に私がやったわけではないですけれども、やっぱり推進してよかったなと感じました。","respondent":"三宅都市開発課長","answer":"水とみどりのネットワークですけれども、水のほうは、目黒の場合は、すぐ近くに川はございませんけれども、右側の花房山通り沿いなど、広場状空地などつくりますので、そこにみどりを連続させていくとか、近くに庭園美術館ですとか、自然教育園、それから少しくだりますと。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問・要望","question":"そういう意味で、区界の場所ですけれども、やっぱり潤いのあるまちづくりをしていっていただきたいと思います。いつまでいてくださるかわからないですけれども、いてくださる期間を、そういう熱き思いでやっていっていただきたいと思うんですけれども、その辺のご認識、仕事にかける思いというものを、ちょっとお聞きしたいと思います。","respondent":"三宅都市開発課長","answer":"私の思いだけではどうにもならないんですが、ただ、今、準備組合のほうでも、非常に大規模なみどりを考えておりまして、空地の建物が建っていない部分の３５％以上を緑化するという義務はあるんですけれども、その数字を５割ぐらいに高めて頑張ろうと。","id":"exchange-027"},{"speaker":"阿部副委員長","kind":"質問","question":"簡単なことから１点、教えてください。もともと、第１種住宅地域だったわけですよね。駅前のこういうところで、ああ、住居地域だったのだということ自体にびっくりしてしまったんですけれども、都バスの営業所が第１種住宅地域、これは普通なことなのでしょうか。ちょっとすみません、その辺よくわからないので、教えてください。","respondent":"三宅都市開発課長","answer":"平成８年、先ほどのトライスクエア構想のところでご説明しましたが、研究所のところで、住居系の用途地域の変更、用途地域が変わったということで変更しております。","id":"exchange-028"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"ですから、大きくこのまちが変わっていくことに対して何らかの不安も持っておられるということは、とても想像に難くないです。先ほどもちょっとお話が出ましたけれども、対話を一時的にも拒否するというような態度では、ちょっとこの先、思いやられますので、これは区としても、ぜひ、注意深く見ていただきたいと考えていますが、いかがお考えでしょうか。","respondent":"三宅都市開発課長、片田防災まちづくり事業部長","answer":"３点ございまして、一つ目が、用途がモザイク状であるという点ですけれども、先ほども申し上げましたように、もともと都バスの車庫で使っておりましたところなので、住居地域ということではあったんですが、この機会に。やはり地域との機能分担ですよね、やはり駅周辺に見合った都市利用等が図られる必要があるということも含めて、全体バランスをとって、私ども考えているところですので、引き続き。","id":"exchange-029"},{"speaker":"若林委員","kind":"質問","question":"一定の何か冷却期間等は置かれたかもしれないけれども、という認識で、地元の方の話し合いをとにかく進めてほしいと、当然、真摯に話し合うを持つべきだと、それでさっきの答弁があったわけですけれども、私はそういう認識でいるんですが、ちょっとコメントをいただければ。","respondent":"三宅都市開発課長","answer":"そういうことを聞きましたので、私どものほうでも、準備組合のほうに、あまり間をあけないようにということで指導をしたところです。","id":"exchange-030"},{"speaker":"若林委員","kind":"意見","question":"そこに何か拒否するとか、拒否しないとかということではなくて、当然、都市計画が決まろうと何しようと、陳情の審査の中では、都市計画そのものが違っていないんだというご指摘もさせていただいたんですけれども、いろいろな建物をつくっても、当然、地元の地権者、住民同士で真摯に話し合いをするという脈絡の中での一連のことだったので、さっきの拒否したとか、拒否されたとか。","respondent":"三宅都市開発課長","answer":"委員おっしゃるように、両者の信頼関係のもとにお話し合いが継続されるように、今後とも指導してまいりたいと思います。先ほどの、用途地域の変更とセットで再開発をやった事例がないかというご質問ですが、大崎ニューシティで事例がございました。","id":"exchange-031"}]},{"id":"topic-04","title":"の大崎駅西口地区および周辺地区におけるまちづくりの現況","agenda":"の大崎駅西口地区および周辺地区におけるまちづくりの現況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと何点か質問したいんですが、南地区開発の権利変換計画の策定状況と、改めてちょっと、権利変換計画がおくれているわけを教えていただきたいと思います。それから、手法というんですか、単独開発なのか、区がどういうふうにこの開発にかかわっているのかという部分。例えば、何らかの規制の緩和ですとか、補助金とか、そういったものはあるのかどうか、お伺いします。","respondent":"三宅都市開発課長","answer":"まさに準備組合の中での検討が中心になってあります。区とのかかわりですけれども、そういう計画の案といいますか、内容、姿が見えてきたときに、また助言等をしていきたいと考えています。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"大崎三丁目地区のほうですけれども、単独開発ではないですよね、いろいろな地権者がかかわっているので、そうなんですけれども、複数の事業者なので、補助も考えていく可能性はあるということだったんですが、いわゆる補助金を、こういった開発計画に入れる場合の何か考え方というか、どういうときに区として入れていく方向になるのか。その辺を教えていただきたいと思います。","respondent":"三宅都市開発課長","answer":"基本的に組合再開発、複数の地権者が力を合わせて再開発をやるということに補助しておりまして、それによって都市基盤設備や公開空地の整備があわせてなされるということであれば検討するということにしております。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"計画のアウトラインなんですけれども、これは住宅なのか、オフィスなのか、一体何をするのかアウトラインを教えていただきたいと思います。それから、補助金の投入とか用途地域の変更とか、補助金、そういったものは考えられるのかどうか、お伺いします。その結果、地区の整備計画策定ということなんですが、これはどういう位置づけの計画になるのか、いつごろまとめる予定なのかを、お伺いします。","respondent":"三宅都市開発課長","answer":"１期、２期といいますか、時期を分けて開発を進めるというようなところで、これまで検討が進められてきましたけれども、この際、一体的にやろうというふうに準備組合の中で意思決定がなされたです。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後の広町のほうですが、東京都と警視庁と協議をするということなんですが、地区の特性についてという言葉もありましたけれども、一体どういうことを調査あるいは協議するのかということを、もう少し具体的に教えていただきたいんです。","respondent":"三宅都市開発課長","answer":"中身というよりも、きっかけのほうをお話ししたほうがいいかと思いますけれども、第一三共の研究開発センターがこの地域の中心部にあるということでございまして、第一三共の研究開発機能の更新、集約などの検討をなさっている。","id":"exchange-035"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"今回、浸水被害が実際にあったのは２件ということなんですが、上大崎地域のほうで、警戒に当たった箇所が多かったと伺っているんですけれども、今回、上大崎の地域で被害が集中したといいますか、その理由というんですか、どういうふうにお考えになっているか。かつては、このようなことがかなり多かったこととあわせて、教えていただきたいと思います。","respondent":"中山防災課長、齋藤道路公園課長","answer":"それほど、これまで大きな水害は出ておりません。ただ、花房山というぐらいですから、線路沿いはかなり急勾配になってございまして、その水が道路の歩道から流れ込んだのではないかと考えています。東京都が都道の改修工事をやるときに、歩道の取付方の傾斜をちょっと間違えて、それで店舗に入りやすいような傾斜をつくった。東京都が対応いたしますので、今後、同様地域で浸水被害はないと考えております。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118011?Template=document&Id=3988#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":41730,"voices":103}},{"id":"h22-20100914-9","meetingId":"h22-cm09","date":"2010年9月14日","dateIso":"2010-09-14","committee":"文教委員会","time":"午後１時０２分～午後４時２６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","topics":[{"id":"topic-01","title":"校舎改築事業の進捗状況","agenda":"校舎改築事業の進捗状況","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"２枚目のところの豊葉の杜学園のところのプールが、どういうプールなのかなというのを教えていただきたいのと、あと小中一貫校のところは、学校のエリアと一般開放の部分とか、あと豊葉の杜は地域センターがありますよね。率直な疑問で、北棟の２階に８年生と９年生が入っていて、大きな子が２階で、小さい学年が上なので、ちょっとその辺がどうしてこうなのか、ちょっとその辺を説明してください。","respondent":"田村庶務課長","answer":"５年生、６年生、７年生というつながりを見ても、やはりここの同じフロアに４階で３学年、一緒に生活させたいということで、フロア的にアリーナの部分を除くと４階という形で考えているところです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"いまひとつ動線がわからないんですが、北棟のクラスというのは、必ず南棟の小中一貫校の入口のところから入って、階段を下がったり、北棟に行くには上がって、みんな連絡通路を通って下に行くか、上に行くかという感じなんですか。かなり連絡通路の頻度が高い、あそこを通過するということなんですね。その辺との関係はどうなるのかというのを一つお伺いしたい。","respondent":"田村庶務課長、吉岡保育課長","answer":"地域センターの関係は、地元要望等もありまして、既存の荏原第五地域センターよりは若干広くなるというように私どもは聞いているところです。形態につきましては、現在は二葉つぼみ保育園は０歳から３歳までの保育園、二葉幼稚園は４歳児と５歳児のそれぞれ２クラスずつの幼稚園ですので、形態といたしましては。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"二つあるんですけれども、特別支援教室が南棟の２階にありますが、これは小学校と中学校と、両方あわせてここにあるんですかね。この辺でちょっとほかの学年というか、クラスとの交流がここだけなくて、ちょっと切り離されてしまっている感があるんですけれども、その辺のお考えを一つお伺いしたいのと、あと１ページ目の全体的なところで、御殿山小学校のところに御殿山幼稚園がありますよね。","respondent":"和氣小中一貫教育担当課長、吉岡保育課長","answer":"特別支援教室の位置ですが、真ん中に音楽室を挟んでいるのですが、若干今まだ変わる可能性があるんですけれども、基本的には場所ではありませんで、どういう形で工事をしていくかということでございまして、今はどこの特別支援学級も。それで、再開発については、今のところ平成２６年度ぐらいだったと思うんですけれども、施設の完成が予定されてありますので、再開発施設の中へ施設の完成後に御殿山幼稚園は戻るということで、今のところ考えているところです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ということは、品川学園の幼保一体の施設というのは、どういうふうになるのか、そこを教えてほしいのと、あと先ほどの特別支援教室なんですが、いろんなところでさまざまな交流は行われると思うんですけれども、例えば「おはよう」と校門をくぐる段階から、なるべくいろんな接触をしたり、姿が見えるところがいいなというところでは、日常的に例えば同じ学年とか。","respondent":"吉岡保育課長","answer":"品川地区の幼保一体施設が来年４月に開設されるんですけど、再開発事業が完了して施設ができた後に御殿山幼稚園が戻る、その戻った後の品川地区の幼保一体施設はどうなるかという話だと思うんですけれども、基本的には幼稚園を新設する考えはございませんので。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"何らかの幼児施設ということで、今国の動向もいろいろあるので、とても心配なところもあるので、ぜひ認可保育園機能の充実というところをしっかりと念頭に置いて考えていただきたいなと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"１枚目のほうで、御殿山小学校のところなんですけれども、今の関連で一つ伺っておきますけど、品川学園のところで、御殿山幼稚園が戻ったときには、ここは新たな認可保育園としますということで今までずっと説明をされていたかと思うので、幼保一体型の認可保育園であるということも変更はなかったんだろうと思いますが、そこのところをお願いします。２点お願いします。","respondent":"吉岡保育課長、田村庶務課長","answer":"ただ、その形態をどうするかについては、今後検討しますけれども、当然保育園がこれだけの需要がある中ですから、認可保育園としての扱いになるです。御殿山小学校の関係、少し説明不足の点がありましたけれども、再開発の時期とやっぱりどういうふうに動いていくのか、たしかもう２年ぐらい当初の計画からおくれているので、それとの整合性なり調整はしています。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"予算がついているから執行をという行政の考え方は当然だと思うんですけれども、そちらの建設のほうの予定が地域住民合意も含めて、そういうことがちゃんと合意されるのに時間がかかるということであれば、この計画はそれに沿って少しずつ地域的なもので変更するということも視野に入れなければならないということに教育委員会は判断をしているのでしょうか。","respondent":"田村庶務課長","answer":"今ゾーニングの幾つかの課題はあるにしろ、やはり今年度については基本計画を作成するということですから、粛々と、ただいろいろな動向は、あるいは調整等は引き続きやっていきますが、予定どおり基本計画について、何とかこれに従って実施していきたい。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"２点目で、裏のほうの今度は荏原東なんですが、南棟の幼保一体施設のほうの地域交流というのは、どういうふうなイメージを持っているのかということと、あと先ほどの特別支援の教室の場所なんですが、場所ではなくて、交流の工夫であるということはそのとおりだというふうに思いますけれども、そこで、設計的にここしかなかったんですよということなのか、何か工夫がある中でここになったのか。","respondent":"吉岡保育課長、和氣小中一貫教育担当課長","answer":"ただし、平成２５年度のオープンになりますので、その時点での保育需要のありようによっては、やはり若干の修正がかかる可能性もないではないというのが今現在の状況と考えています。この場所は総合的に先ほどの８年生とか５年生、６年生、７年生の配置とか、何が一番合理的かというのを多角的に検討して、騒音の問題、動線の問題を含めてこの場所に決めたということで。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"そのときに、やはりこういう設計について、子どもは確かにこの設計で入ってしまえばなれることは十分承知をしていますが、大人がそこで子どもにとって本当に今回の文教委員会で一たん視察で子どもの最善の利益といったときに、行政として建物を建てなきゃいけないという使命はとても理解しますけれども、子どもたちにとって本当にこれでいいのかというところは、どういうふうに考えて。","respondent":"和氣小中一貫教育担当課長","answer":"結果的にさまざまな課題が出てきたとすれば、それはもちろん修正いたしますが、もちろん最善を尽くして子どもたちの目線に立ち、限られた、もしくは条件下の中で、最も理想的なことを追求してやらせていただいておりますので、その合理性云々と言われたときに。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"じゃあ要望しておきます。校舎としてはとても立派なものができても、中で生活するのは子どもですから、そこの部分にこういうプランについてみんなはどう思うかというぐらい子どもたちに一度は意見を聞いてもいいのかなというふうに思いますので、そういったところをぜひしていただきたいなと思いますが、お考えだけ、何かいろいろとありそうですので、お伺いしたいと思います。","respondent":"田村庶務課長","answer":"ですから、テラス的な要素ですけど、やはり都市部の中で限られたスペースを有効に活用するということで、教育委員会がトップダウンでこの計画を決めたわけでもないですから、ただ、限られた敷地で校庭もとり、高さの近隣配慮もし、そういうことを総合的に考えると。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"一つだけちょっと気になるんですけど、荏原東地区のところで、特別支援学級が１年－４年、５年－９年というものがあって、２階のところなんですね。これは非常に地域の方もおっしゃっているところがありまして、何か隔離しているんじゃないかなという話もちょっと聞こえてくるんですよね。その辺はどういうふうに地域の方に説明とかされるのでしょうか。いかがでしょうか。","respondent":"和氣小中一貫教育担当課長","answer":"逆に言えば、１・２年と３・４年はサンドしているわけですね、間に挟んで両方の上下の真ん中に置いているわけで、そういう意味で隔離をするということにはならないし、逆に隔離をするという意図があるというように思われたこと自体が大変に私は心外です。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"伊藤学園のときもそうですし、今までできたものについても、どうもこの特別支援学級というところの考え方はもっと普通学級に近いところに設置できないのかなというのは、そちらのほうからどうなんでしょうかね、私は教育上いいんではないかなと思うんですが、ここまでできちゃっているものを今さら変えろということは難しいと思うんですけど。","respondent":"和氣小中一貫教育担当課長","answer":"ですから逆にそういう質問がいっぱい出てくること自体がよく理解できないといいますか、特別支援学級が学校の中で常に交流をしながらやっていくという方向性については、もちろんその方向性でやってきているわけでございまして、その違いだけだというように理解しています。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、やっぱり親たちにしてみると、通常の子どもたちと交流を持ってほしいという部分もあるわけですよね。なので、こういう形になってしまって、そうじゃないというふうに思われるところがあれば、そこはちゃんと説明していかなきゃいけないだろうなと思いますので、しっかりとその辺は説明をしていただきたいなと思います。それに関しては、どういうふうに対応されるのかお聞きしたいと思います。","respondent":"冠木指導課長","answer":"特別支援教育の考え方ということでは、すべてがそれぞれの学年の教室と一緒になるということではなくて、一定の判断のもとに就学相談を経て、そして特別支援等々ケアが必要なお子さんについては特別支援教室を運営しているわけですから。","id":"exchange-013"},{"speaker":"金野委員","kind":"質問・要望","question":"荏原東地区小中一貫校のこの図面の中での、ちょうど北側のほうなんですけれども、教師と書いてある箇所が何カ所かあるんですが、これは校務センターとの使い方で、これは教師という、このお部屋はどういうものなのか教えていただきたいのと、２点目が、北側に厨房が１階にあるかと思うんですが、多分これは給食室なんだろうなと思って見ているんですが、いわゆる給食室。","respondent":"和氣小中一貫教育担当課長、田村庶務課長","answer":"今新しい小中一貫校については、なるべく教員がフロアに休み時間もいていただいて作業していく、なるべく子どもと触れ合うということで考えていますので、教師コーナーを設置して、日常的に、朝は職員室に行きますが。ご指摘のように北側の厨房は学校の給食施設です。実施設計の段階ですのでちょっと見づらいのですが、厨房で給食をつくると、同じフロアはワゴンで運びます。","id":"exchange-014"},{"speaker":"金野委員","kind":"質問","question":"教師というそのスペース、わかりました。いわゆるここでお仕事をするというよりは、子どもたちと交流をするのに、目が行き届くという表現がいいんでしょうか、わかりませんが、子どもたちとかかわれる位置に教師のスペースを設けたということですが、先生たちはここでお仕事というよりは、子どもたち、ちょっとイメージが、ごめんなさい、わからないので、もう少し詳しく教えてください。","respondent":"田村庶務課長、和氣小中一貫教育担当課長","answer":"そこのちょうど５mmぐらい行った右上に四角に囲ってあるのがわかるでしょうか。ちょっと細かくて申しわけないんですけど、これがエレベーターです。これが給食室専門のエレベーターという形になっています。そこに専用の鍵つきのロッカーが置いてあったり、パソコンもやれるように無線ＬＡＮが配置してあったり、そこで大事な子どもの成績なんかは処理できませんが、日常の作業、教材準備とか。","id":"exchange-015"},{"speaker":"金野委員","kind":"質問","question":"スクールカウンセラーの方々が配置をされて、相談をするお部屋というんでしょうか、それは設置をされているんでしょうか。","respondent":"和氣小中一貫教育担当課長","answer":"北側２階の平面図をご覧いただきますと、保健室の両側に「相談」と小さく書いてあるんですが、ここが基本的にカウンセリングするための部屋というように考えています。保健室と一体利用という形で考えてあります。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"今のカウンセラー室、相談室なんですが、多分学校に来られない子とか不登校の子たちが来るんだと思うんですよね。その子たちというのは、同じクラスの子たちとかに会いたくないんですよ。そういう子もいるんですよね。そうすると、ここに来るんですよ。２階、教室の前を通ってということになるんですか。ちょっと、これ、もうちょっとわからないようなところにならないですかね。","respondent":"和氣小中一貫教育担当課長","answer":"それはまたそういう通路、その子どもによってまた違いますので、よく考えたいと思います。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"不登校の友達たちというのはいろんな事情があると思うんですが、いろんな事情に合わせて、なかなか難しいと思うんですが、子どもたちの気持ちに配慮していただいて対応していただきたいと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"井上委員","kind":"質問","question":"給食食材を同じエレベーターということだったんですが、それは学校給食法とかなんかある中で、何も影響はないものでしょうか。","respondent":"和氣小中一貫教育担当課長","answer":"既にそういう利用はしておりまして、伊藤学園などはエレベーターを設置していますが、ワゴンにいろいろ工夫して安全を確保しているです。","id":"exchange-019"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"例えば利用状況とか、そういった大まかにわかるような資料を現地でいただけるのでしょうか。","respondent":"田村庶務課長","answer":"車中でそもそも鈴ケ森小学校を何で選んだかという資料を車で差し上げて、その後現地で校長先生をまじえて１５分ぐらい時間があるので、そちらの中でご説明させていただきたいと思います。場合によっては、移動の時間に私から説明させていただきたいと思います。","id":"exchange-020"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"所管が違ったら違うと言っていただきたいんですけれども、見守りホットライン、２４時間受け付けるということですが、具体的にどういう形で受け付けるんですか。だれがやっているんですかね。専門的な人を配置するという意味なんでしょうかというのが一つ。それから３番の施設を区単独で確保するということですが、どういう施設を確保するんでしょうか。","respondent":"安井子育て支援課長","answer":"基本的には就業時間がありますので、それ以降は宿直の新たな業務として追加してこれをやっていくということで、２４時間受け付けるわけですけども、非常に緊急な場合はこちらでもなかなかできないときもある。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"(3)はわかりました。知りたいのは、やっぱり夜間のほうだと思います。夜間に受け付けたときに、確かに宿直の方が各所管の課長なのか部長なのか知りませんけれども、その人たちに連絡を入れてというところだと思うんですけれども、ただやっぱりいらっしゃらない場合だってあると思いますし、あと緊急性もかなり要する部分があるかと思うんですけれども、そこら辺の対応というのはされているんでしょうか。","respondent":"安井子育て支援課長","answer":"虐待の相談というような、そういうこともほとんどないんですけれども、逆にないからいいということではなくて、そういうようなことがあったら、今もそうなんですけど、宿直の対応ですとか、年末年始の対応ですとか。","id":"exchange-022"},{"speaker":"西本委員","kind":"意見","question":"今日でなくていいので、どういう流れになるのかもう少しはっきり知りたいところです。というのは、啓発パンフレットもつくるわけですよね。だから、児童相談所というところはどういうところかわかると思うので、そこに連絡しようというケースはあるんでしょうけれども、区がこれからやるよということを公に出すということは、それなりに数が増えてくる可能性があると思うんですよね。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"関連で、この「しながわ見守りホットライン」というのは、その計画の中のＤＶというところの大きなところで取り組まれている新たなものというふうにとらえているんですが、文教委員会資料として出されているのでこういうふうな簡単なものになっているのかなというふうに思うので、本来的には人権啓発課のそこの部分が大もとの所管をして、これをもっときっちりとしたものというふうに。","respondent":"安井子育て支援課長","answer":"全体計画の中での位置づけというのは入っていくんだとは思うんですけれども、先ほど委員おっしゃったとおりです。ここでは総務委員会に報告案件の大もとを出しておりますので、そこら辺のところで文教委員会でご報告させていただいているところです。","id":"exchange-024"},{"speaker":"金野委員","kind":"質問・要望","question":"そこら辺はどうなっているのか、ちょっと所管が違うかもしれないんですが、その点、１点お聞きしたいのと、あと町会や民生委員を中心にというふうになっているんですが、ここの方は当然なんですけど、もっと広く広報されたほうが絶対にいいと思います。というのは、私たちが気がつかないところで起きているというのは、本当に身近な地域の方々の情報だろうと思いますので、その点はいかがでしょうか。","respondent":"安井子育て支援課長","answer":"啓発パンフレットについては、どのぐらいの程度までやるのか、というのはなかなか難しいところがあるので、ＤＶと児童虐待と高齢者虐待とそれぞれ違う部分もあるんですけれども、命や体を守るという意味において。","id":"exchange-025"},{"speaker":"伊藤副委員長","kind":"質問","question":"三つ指摘と質問をします。例えばまもるっちとのリンクを考えたらどうでしょうか。質問します。だから、入口から出口まで一貫した考え方とシステムをつくっていかないと、今委員がおっしゃったようにこの件は達成されない可能性が十分あるわけだから、その３点についての検討と、それからまだまだこれからいただいた指摘があるんでしょうから、品川区の考え方についてお答えください。お願いします。","respondent":"安井子育て支援課長、冠木指導課長","answer":"ただ、時間外になってしまうと、親御さんのほうへ、私が聞くところによると、携帯に連絡が入るというような形になっているようなので、そこら辺のところがちょっと果たしてうまくいくのか。私どもも子育て支援課と連携をとってやっているところですが、特に悪質なケースにつきましては、これは子どもの場合は最終的には一時保護の後に家庭裁判所等々の判断も仰がなければいけないようなケースもありますので。","id":"exchange-026"},{"speaker":"伊藤副委員長","kind":"意見","question":"だけども、その後の展開をどういうふうに行政のほうで考えて、このケースはこうしていくとか、このケースは具体的にこうしていくとかという、その後の部分がしっかりないと委員としては納得できないという意見がある、皆さん同じ意見だと思いますから、そのことを改めてお願いして、あわせてこれをさらに展開するに当たっては、委員会に私個人からも改めてお示ししていただきますようにお願いをいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"すみません、保育ママの事業再開ということで、どのように、資格とか、どういうことで変わられて、結果的に１名ということなんですが、それについてはどういう評価をしているか。もう少し多くあって、事業再開というふうにお知らせをいただくような事業だろうなと思うんですけど、結果的に１名だということはどういうことなのか教えていただけますか。","respondent":"伊崎待機児童対策担当課長","answer":"この１名という状況につきましては、できるだけ今後もこの事業の周知を図って、やってくださる気持ちのある方を今後も募っていきたいと考えているところです。","id":"exchange-028"},{"speaker":"井上委員","kind":"質問・要望","question":"資格審査のところでということが広報の食い違いなんかがあるということで、ちょっと置いといたとすると、要件として自宅での保育というのになかなか課題があるということだと思うんですけれども、そこを区としてはこの事業を再開するに当たって、それだけを求めていたら多分区内の自宅状況で言えば難しいということは想像できるところで、今後これを展開しようと新たなことを考えていこうとされるのか。","respondent":"伊崎待機児童対策担当課長","answer":"区といたしましては、こちらの在宅型の保育ママ制度だけではなく、施設型といいまして、施設を見つけていただいて、そこで保育ママをやっていただくという形態を今検討しています。","id":"exchange-029"},{"speaker":"金野委員","kind":"質問・要望","question":"今のところとの関連で、これは要望です。以前私どものほうでも、本会議等々で質問をさせていただいたんですが、空き店舗あるいはそういったところを活用して、何人かの保育ママたちと一緒に、というのが非常に安全性も、そして預かってほしい側の親側も、安心して預けられるんではないかということもありますので、ぜひこの施設型を早急にご検討いただきたい、このように思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"私が関心を示したのは、緊急待機児対策で私立の認可保育園開設準備助成というので、新しく来年の４月に私立の認可保育園二つが開設しますよといった事業が具体化されていて、お問い合わせ先が吉岡保育課長になっているんですけれども、ちょっと区長記者懇談会というのは、どういう性格なのかがよくわからないんですけれども、実際に新聞記者に情報が提供されたということにおいて、全く新しい事業。","respondent":"古川子ども未来事業部長","answer":"私どもといたしましては、当然補正予算にかかわる部分です。これは開設準備金等の助成にかかわりますので、来るべき次の第３回定例会の中で補正予算をお願いする中で、正式なご説明をしていきたい、このように考えております。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"タイミングがあると思うんですよね。求めている民間の保育園なので、増設といったらみんなゾクゾクとするのと、ビビッと反応して、一体どんな中身と、そういった面では、本当に議会にしっかりご報告をいただかないと立場がなくなってしまいますので、その辺は本当に何回かこの間あったわけですけれども、気をつけて、改めていただきたいなと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/976656?Template=document&Id=4710#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":31817,"voices":91}}]);
